class MyApp extends StatelessWidget {
  const MyApp({super.key});

  // Public, unauthenticated route for Google Play Store's Account Deletion
  // requirement (see AccountDeletionScreen) — reachable at /account-deletion
  // or ?page=account-deletion. Firebase Hosting's "**" -> /index.html
  // rewrite (see firebase.json) means a direct browser navigation to that
  // path reaches this Flutter app instead of 404ing at the server, and
  // Uri.base picks it up from there. Checked ahead of AuthGate so this shows
  // regardless of login state — signed in, signed out, or no account at all.
  bool get _isAccountDeletionRoute {
    if (!kIsWeb) return false;
    final path = Uri.base.path;
    return path == '/account-deletion' ||
        path == '/account-deletion/' ||
        Uri.base.queryParameters['page'] == 'account-deletion';
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'NODA Civimech Engineering (PVT) Ltd.',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(primarySwatch: Colors.blue, useMaterial3: true),
      scrollBehavior: AppScrollBehavior(),
      home: _isAccountDeletionRoute
          ? const AccountDeletionScreen()
          : AuthGate(key: UniqueKey()),
    );
  }
}

// Flutter's default ScrollBehavior only treats touch/stylus input as a drag
// gesture — a desktop/web mouse can't click-and-drag any SingleChildScrollView
// (horizontal ones especially, since a plain mouse wheel has no horizontal
// axis to fall back on the way it does for vertical scroll). Every report
// table's horizontal scroll (ManagementSiteReportsScreen, TransportSummaryScreen,
// etc.) sits inside a mouse-driven web app, so this adds
// PointerDeviceKind.mouse to the drag-enabled set app-wide.
class AppScrollBehavior extends MaterialScrollBehavior {
  @override
  Set<PointerDeviceKind> get dragDevices => {
    ...super.dragDevices,
    PointerDeviceKind.mouse,
  };
}

// ---------------- AUTH GATE (auto-login check) ----------------
class AuthGate extends StatefulWidget {
  const AuthGate({super.key});

  @override
  State<AuthGate> createState() => _AuthGateState();
}

class _AuthGateState extends State<AuthGate> {
  String? _cachedUid;
  Future<DocumentSnapshot>? _userFuture;
  late final Stream<User?> _authStream = FirebaseAuth.instance
      .authStateChanges();
  // Fires once per signed-in AuthGate session — see
  // GarageNotificationService, which does its own SharedPreferences-backed
  // once-per-day gating on top of this.
  bool _garageNotificationChecked = false;

  Future<DocumentSnapshot> _getUserDoc(String uid) {
    if (_cachedUid != uid || _userFuture == null) {
      _cachedUid = uid;
      _userFuture = FirebaseFirestore.instance
          .collection('users')
          .doc(uid)
          .get()
          .timeout(const Duration(seconds: 15));
    }
    return _userFuture!;
  }

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<User?>(
      stream: _authStream,
      builder: (context, authSnapshot) {
        if (authSnapshot.connectionState == ConnectionState.waiting) {
          return Scaffold(
            body: Container(
              decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
              child: const Center(
                child: CircularProgressIndicator(color: Colors.white),
              ),
            ),
          );
        }

        final user = authSnapshot.data;

        if (user == null) {
          _cachedUid = null;
          _userFuture = null;
          return kIsWeb ? const PublicWebsiteScreen() : const LoginScreen();
        }

        return FutureBuilder<DocumentSnapshot>(
          future: _getUserDoc(user.uid),
          builder: (context, userSnapshot) {
            if (userSnapshot.connectionState == ConnectionState.waiting) {
              return Scaffold(
                body: Container(
                  decoration: const BoxDecoration(
                    gradient: AppTheme.mainGradient,
                  ),
                  child: const Center(
                    child: CircularProgressIndicator(color: Colors.white),
                  ),
                ),
              );
            }

            if (userSnapshot.hasError) {
              return Scaffold(
                body: Container(
                  decoration: const BoxDecoration(
                    gradient: AppTheme.mainGradient,
                  ),
                  child: Center(
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        Text(
                          'Error: ${userSnapshot.error}',
                          style: const TextStyle(color: Colors.white),
                        ),
                        const SizedBox(height: 16),
                        ElevatedButton(
                          onPressed: () => FirebaseAuth.instance.signOut(),
                          child: const Text('Back to Login'),
                        ),
                      ],
                    ),
                  ),
                ),
              );
            }

            if (!userSnapshot.hasData || !userSnapshot.data!.exists) {
              FirebaseAuth.instance.signOut();
              return const LoginScreen();
            }

            final data = userSnapshot.data!.data() as Map<String, dynamic>;
            final role = data['role'] ?? '';
            final name = data['name'] ?? '';

            if (!_garageNotificationChecked) {
              _garageNotificationChecked = true;
              unawaited(GarageNotificationService.checkAndNotifyIfNeeded());
            }

            // Garage Access override (see AddUserScreen/ManageUsersScreen's
            // Garage Access checkbox/toggle and GarageScreen) — a
            // "mechanic"-style account of any role lands only on
            // GarageScreen, bypassing its normal role screen entirely.
            // Admin/Owner/Management are excluded: they keep their normal
            // dashboard and get Garage as an additive menu item there
            // instead (see AdminDashboard/OwnerDashboard/
            // ManagementDashboard) — a real dashboard is meaningful for
            // those roles, unlike a dedicated mechanic account.
            if (data['canAccessGarage'] == true &&
                role != 'admin' &&
                role != 'owner' &&
                role != 'management') {
              return GarageScreen(name: name);
            }

            switch (role) {
              case 'admin':
                return AdminDashboard(name: name);
              case 'owner':
                return OwnerDashboard(name: name);
              case 'supervisor':
                return data['canAccessFuel'] == true
                    ? SupervisorChoiceScreen(name: name)
                    : SupervisorScreen(name: name);
              case 'driver':
                return DriverTypeScreen(name: name);
              case 'management':
                if (kIsWeb) {
                  return ManagementDashboard(name: name);
                }
                FirebaseAuth.instance.signOut();
                return const LoginScreen();
              case 'field_worker':
                final canDrive = data['canDriveTruck'] == true;
                final canOperate = data['canOperateMachine'] == true;
                if (canDrive && canOperate) {
                  return DriverTypeScreen(name: name);
                } else if (canDrive) {
                  return TruckTypeScreen(name: name);
                } else if (canOperate) {
                  return DriverMachineTypeScreen(name: name);
                } else {
                  FirebaseAuth.instance.signOut();
                  return const LoginScreen();
                }
              default:
                FirebaseAuth.instance.signOut();
                return const LoginScreen();
            }
          },
        );
      },
    );
  }
}

// ---------------- PUBLIC MARKETING WEBSITE (web-only landing page) ----------------
// Shown instead of LoginScreen when a signed-out user opens the app on web
// (see AuthGate's kIsWeb branch). Mobile always goes straight to
// LoginScreen, untouched. This is a plain content page with its own "Login"
// entry point into the real app.
class _WebsiteService {
  final IconData icon;
  final String title;
  final String description;
  const _WebsiteService(this.icon, this.title, this.description);
}

// Shared between WebsiteContentManagementScreen (where admins pick one of
// these by name) and PublicWebsiteScreen's services section (where the
// stored name is resolved back to an icon).
const Map<String, IconData> kWebsiteServiceIcons = {
  'construction': Icons.construction,
  'local_shipping': Icons.local_shipping,
  'engineering': Icons.engineering,
  'precision_manufacturing': Icons.precision_manufacturing,
  'handyman': Icons.handyman,
  'build': Icons.build,
};

class PublicWebsiteScreen extends StatelessWidget {
  const PublicWebsiteScreen({super.key});

  // Fallback content, used until website_content/main exists or whenever a
  // field on it is empty — keeps the site looking complete even before an
  // admin has entered real copy.
  static const String _defaultWhatsappNumber = '94XXXXXXXXX';

  static const List<_WebsiteService> _fallbackServices = [
    _WebsiteService(
      Icons.terrain,
      'Excavation Works',
      'Site clearing, earthmoving, and excavation for projects of any scale.',
    ),
    _WebsiteService(
      Icons.local_shipping,
      'Fleet Management',
      'GPS-tracked truck and machine fleet, coordinated in real time.',
    ),
    _WebsiteService(
      Icons.supervisor_account,
      'Site Supervision',
      'On-ground supervisors managing daily operations and reporting.',
    ),
    _WebsiteService(
      Icons.precision_manufacturing,
      'Construction Machinery Rental',
      'Excavators and heavy machinery available for hire, with operators.',
    ),
  ];

  void _scrollToSection(GlobalKey key) {
    final ctx = key.currentContext;
    if (ctx == null) return;
    Scrollable.ensureVisible(
      ctx,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeInOut,
    );
  }

  void _openLogin(BuildContext context) {
    Navigator.push(
      context,
      MaterialPageRoute(builder: (_) => const LoginScreen()),
    );
  }

  Future<void> _openWhatsApp(
    BuildContext context,
    String whatsappNumber,
  ) async {
    final number = whatsappNumber.isEmpty
        ? _defaultWhatsappNumber
        : whatsappNumber;
    final uri = Uri.parse('https://wa.me/$number');
    final launched = await launchUrl(uri, mode: LaunchMode.externalApplication);
    if (!launched && context.mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Could not open WhatsApp.')));
    }
  }

  @override
  Widget build(BuildContext context) {
    final heroKey = GlobalKey();
    final workKey = GlobalKey();
    final servicesKey = GlobalKey();
    final contactKey = GlobalKey();

    return Scaffold(
      backgroundColor: Colors.white,
      body: Column(
        children: [
          _WebsiteNavBar(
            onHome: () => _scrollToSection(heroKey),
            onServices: () => _scrollToSection(servicesKey),
            onContact: () => _scrollToSection(contactKey),
            onLogin: () => _openLogin(context),
          ),
          Expanded(
            child: StreamBuilder<DocumentSnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('website_content')
                  .doc('main')
                  .snapshots(),
              builder: (context, snapshot) {
                final content = snapshot.data?.data() as Map<String, dynamic>?;
                final whatsappNumber = (content?['whatsappNumber'] ?? '')
                    .toString();

                return SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      _HeroSection(
                        key: heroKey,
                        heroTitle: content?['heroTitle'] as String?,
                        heroSubtitle: content?['heroSubtitle'] as String?,
                        onGetInTouch: () => _scrollToSection(contactKey),
                      ),
                      _WorkGallerySection(key: workKey),
                      _ServicesSection(
                        key: servicesKey,
                        fallbackServices: _fallbackServices,
                      ),
                      _ContactFooterSection(
                        key: contactKey,
                        aboutText: content?['aboutText'] as String?,
                        onWhatsApp: () =>
                            _openWhatsApp(context, whatsappNumber),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

