class MachineManagementScreen extends StatefulWidget {
  const MachineManagementScreen({super.key});

  @override
  State<MachineManagementScreen> createState() =>
      _MachineManagementScreenState();
}

class _MachineManagementScreenState extends State<MachineManagementScreen> {
  final _machineNameController = TextEditingController();
  final _machineNumberController = TextEditingController();
  String _selectedType = '200 Machine';

  final List<String> _machineTypes = ['200 Machine', '70 Machine', 'Loader'];

  Future<void> _addMachine() async {
    if (_machineNameController.text.trim().isEmpty ||
        _machineNumberController.text.trim().isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please fill all fields.')));
      return;
    }

    await FirebaseFirestore.instance.collection('machines').add({
      'name': _machineNameController.text.trim(),
      'number': _machineNumberController.text.trim(),
      'type': _selectedType,
      'status': 'idle',
      'createdAt': FieldValue.serverTimestamp(),
    });

    _machineNameController.clear();
    _machineNumberController.clear();

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Machine added successfully!')),
      );
    }
  }

  Future<void> _deleteMachine(String docId) async {
    await FirebaseFirestore.instance.collection('machines').doc(docId).delete();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Manage Machines'),
        backgroundColor: Colors.orange[800],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                TextField(
                  controller: _machineNameController,
                  decoration: InputDecoration(
                    labelText: 'Machine Name (e.g. JCB 1)',
                    prefixIcon: const Icon(Icons.construction),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _machineNumberController,
                  decoration: InputDecoration(
                    labelText: 'Machine Number / Plate',
                    prefixIcon: const Icon(Icons.numbers),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                DropdownButtonFormField<String>(
                  initialValue: _selectedType,
                  decoration: InputDecoration(
                    labelText: 'Machine Type',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                  items: _machineTypes
                      .map(
                        (type) =>
                            DropdownMenuItem(value: type, child: Text(type)),
                      )
                      .toList(),
                  onChanged: (val) => setState(() => _selectedType = val!),
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _addMachine,
                    icon: const Icon(Icons.add, color: Colors.white),
                    label: const Text(
                      'ADD MACHINE',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.orange[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Divider(),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('machines')
                  .orderBy('createdAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                  return const Center(child: Text('No machines added yet.'));
                }

                final machines = snapshot.data!.docs;

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: machines.length,
                  itemBuilder: (context, index) {
                    final data = machines[index].data() as Map<String, dynamic>;
                    final docId = machines[index].id;

                    return _WebStaggeredFadeIn(
                      index: index,
                      child: _WebHoverCard(
                        child: Card(
                          margin: const EdgeInsets.only(bottom: 10),
                          child: ListTile(
                            leading: CircleAvatar(
                              backgroundColor: Colors.orange.withOpacity(0.15),
                              child: const Icon(
                                Icons.precision_manufacturing,
                                color: Colors.orange,
                              ),
                            ),
                            title: Text(data['name'] ?? ''),
                            subtitle: Text(
                              '${data['type'] ?? ''} • ${data['number'] ?? ''}',
                            ),
                            trailing: IconButton(
                              icon: const Icon(Icons.delete, color: Colors.red),
                              onPressed: () => confirmDelete(
                                context: context,
                                title: 'Delete Machine?',
                                message:
                                    'Are you sure you want to delete this machine? This cannot be undone.',
                                onConfirm: () => _deleteMachine(docId),
                              ),
                            ),
                            onTap: () {
                              pushWebAware(
                                context,
                                MachineProfileScreen(
                                  machineId: docId,
                                  machineName: data['name'] ?? '',
                                  machineType: data['type'] ?? '',
                                  machineNumber: data['number'] ?? '',
                                ),
                              );
                            },
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------- AVAILABILITY MANAGEMENT SCREEN (Admin) ----------------
// Admin-managed master list of Loading Category names
// (loading_availability_options collection). SiteManagementScreen's Site
// Edit dialog builds its "Available Loading Categories" checkbox list from
// this collection live, instead of the old hardcoded
// kLoadingCategories + kOtherCategories, which mixed in non-loading items
// like Fuel Filling/Maintenance. WorkSessionScreen's QR Scan category
// picker reads sites/{id}.availableCategories, so it's automatically
// cleaner too — no changes needed there.
class AvailabilityManagementScreen extends StatefulWidget {
  const AvailabilityManagementScreen({super.key});

  @override
  State<AvailabilityManagementScreen> createState() =>
      _AvailabilityManagementScreenState();
}

class _AvailabilityManagementScreenState
    extends State<AvailabilityManagementScreen> {
  final _itemNameController = TextEditingController();

  Future<void> _addItem() async {
    final enteredName = _itemNameController.text.trim();
    if (enteredName.isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please enter a name.')));
      return;
    }

    final existing = await FirebaseFirestore.instance
        .collection('loading_availability_options')
        .get();
    final normalizedEntry = enteredName.toUpperCase();
    final isDuplicate = existing.docs.any((doc) {
      final existingName =
          (doc.data()['name'] as String?)?.trim().toUpperCase() ?? '';
      return existingName == normalizedEntry;
    });

    if (isDuplicate) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This item is already in the list.'),
            backgroundColor: Colors.red,
          ),
        );
      }
      return;
    }

    await FirebaseFirestore.instance
        .collection('loading_availability_options')
        .add({'name': enteredName, 'createdAt': FieldValue.serverTimestamp()});

    _itemNameController.clear();
    if (mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Item added.')));
    }
  }

  Future<void> _deleteItem(String docId) async {
    await FirebaseFirestore.instance
        .collection('loading_availability_options')
        .doc(docId)
        .delete();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Availability'),
        backgroundColor: Colors.teal[800],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Row(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Expanded(
                  child: TextField(
                    controller: _itemNameController,
                    onSubmitted: (_) => _addItem(),
                    decoration: InputDecoration(
                      labelText: 'Category Name',
                      hintText: 'e.g. Sand Loading',
                      prefixIcon: const Icon(Icons.checklist),
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
                const SizedBox(width: 12),
                SizedBox(
                  height: 56,
                  child: ElevatedButton(
                    onPressed: _addItem,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.teal[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                    child: const Icon(Icons.add, color: Colors.white),
                  ),
                ),
              ],
            ),
          ),
          const Divider(height: 1),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('loading_availability_options')
                  .orderBy('createdAt')
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                final items = snapshot.data?.docs ?? [];
                if (items.isEmpty) {
                  return const Center(
                    child: Text('No availability items yet.'),
                  );
                }
                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: items.length,
                  itemBuilder: (context, index) {
                    final doc = items[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final itemName = (data['name'] ?? '').toString();
                    return Card(
                      margin: const EdgeInsets.only(bottom: 8),
                      child: ListTile(
                        leading: const Icon(
                          Icons.checklist,
                          color: Colors.teal,
                        ),
                        title: Text(itemName),
                        trailing: IconButton(
                          icon: const Icon(Icons.delete, color: Colors.red),
                          onPressed: () => confirmDelete(
                            context: context,
                            title: 'Delete Item?',
                            message:
                                'Are you sure you want to delete "$itemName"? '
                                'Sites that already have it checked will '
                                'keep showing it until re-edited.',
                            onConfirm: () => _deleteItem(doc.id),
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// Backward-compatible reader for a site's GPS location(s). Prefers the
// newer sites/{id}.gpsLocations list (each entry {latitude, longitude,
// label} — multiple entrance/gate points per site); falls back to the
// older single latitude/longitude fields (pre-multi-entrance), treated as
// a single-item list, when gpsLocations is missing or empty. No migration
// write happens automatically here — an old site keeps its old fields
// until an admin captures a new location through
// SiteManagementScreen._showSetLocationDialog, which folds the old point
// in as the first gpsLocations entry ("Original Location") the first time
// that runs. Shared by SiteManagementScreen (the capture dialog + list
// badge) and LiveTrackingScreen (_loadSiteMarkers), so both read the same
// data the same way.
//
// TODO(AutoArrivalDetectionService): when that service is built, "arrived"
// should mean the truck's current position is within 50m of ANY ONE point
// in a site's siteGpsLocations(...) list — not a single-point comparison —
// since a site can now have multiple valid entrances/gates.
List<Map<String, dynamic>> siteGpsLocations(Map<String, dynamic> data) {
  final rawList = data['gpsLocations'] as List<dynamic>?;
  if (rawList != null && rawList.isNotEmpty) {
    return rawList
        .whereType<Map<dynamic, dynamic>>()
        .map((e) => e.cast<String, dynamic>())
        .toList();
  }
  final lat = (data['latitude'] as num?)?.toDouble();
  final lng = (data['longitude'] as num?)?.toDouble();
  if (lat != null && lng != null) {
    return [
      {'latitude': lat, 'longitude': lng, 'label': 'Original Location'},
    ];
  }
  return [];
}

// ---------------- SITE MANAGEMENT SCREEN ----------------
class SiteManagementScreen extends StatefulWidget {
  const SiteManagementScreen({super.key});

  @override
  State<SiteManagementScreen> createState() => _SiteManagementScreenState();
}

class _SiteManagementScreenState extends State<SiteManagementScreen> {
  final _siteNameController = TextEditingController();
  final _siteLocationController = TextEditingController();
  bool _isPlantSite = false;
  bool _canBeLoadingSite = true;
  bool _canBeUnloadingSite = true;

  Future<void> _addSite() async {
    final enteredName = _siteNameController.text.trim();
    if (enteredName.isEmpty || _siteLocationController.text.trim().isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please fill all fields.')));
      return;
    }

    final existingSites = await FirebaseFirestore.instance
        .collection('sites')
        .get();
    final normalizedEntry = enteredName.toUpperCase();
    final isDuplicate = existingSites.docs.any((doc) {
      final data = doc.data();
      final existingName =
          (data['name'] as String?)?.trim().toUpperCase() ?? '';
      return existingName == normalizedEntry;
    });

    if (isDuplicate) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This site is already registered.'),
            backgroundColor: Colors.red,
          ),
        );
      }
      return;
    }

    await FirebaseFirestore.instance.collection('sites').add({
      'name': enteredName,
      'location': _siteLocationController.text.trim(),
      'isPlantSite': _isPlantSite,
      'canBeLoadingSite': _canBeLoadingSite,
      'canBeUnloadingSite': _canBeUnloadingSite,
      'createdAt': FieldValue.serverTimestamp(),
    });

    _siteNameController.clear();
    _siteLocationController.clear();
    setState(() {
      _isPlantSite = false;
      _canBeLoadingSite = true;
      _canBeUnloadingSite = true;
    });

    if (mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Site added successfully!')));
    }
  }

  Future<void> _deleteSite(String docId) async {
    await FirebaseFirestore.instance.collection('sites').doc(docId).delete();
  }

  // Appends a new {latitude, longitude, label} entry to the site's
  // gpsLocations list — reuses TruckLocationService.requestPermission()
  // (the same Geolocator permission flow Truck Trip Tracking already uses)
  // rather than duplicating that permission-request logic here. Reads the
  // site doc fresh right before writing (via siteGpsLocations, which also
  // folds in the old single-field site's point as an "Original Location"
  // entry the first time this runs) so a capture always appends onto
  // whatever is actually there, never overwrites.
  Future<void> _captureSiteGpsLocation(
    String docId,
    TextEditingController labelController,
  ) async {
    final label = labelController.text.trim();
    if (label.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter a label for this location.'),
        ),
      );
      return;
    }

    final hasPermission = await TruckLocationService.requestPermission();
    if (!hasPermission) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Location permission is required to capture this location.',
            ),
            backgroundColor: Colors.red,
          ),
        );
      }
      return;
    }

    try {
      final position = await Geolocator.getCurrentPosition(
        desiredAccuracy: LocationAccuracy.high,
      );
      final doc = await FirebaseFirestore.instance
          .collection('sites')
          .doc(docId)
          .get();
      final existing = siteGpsLocations(doc.data() ?? <String, dynamic>{});
      final updated = [
        ...existing,
        {
          'latitude': position.latitude,
          'longitude': position.longitude,
          'label': label,
        },
      ];
      await FirebaseFirestore.instance.collection('sites').doc(docId).update({
        'gpsLocations': updated,
      });
      labelController.clear();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'Captured "$label" (${position.latitude.toStringAsFixed(4)}, '
              '${position.longitude.toStringAsFixed(4)})',
            ),
            backgroundColor: Colors.green,
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to capture location: $e')),
        );
      }
    }
  }

  Future<void> _deleteSiteGpsLocation(
    String docId,
    List<Map<String, dynamic>> currentLocations,
    int index,
  ) async {
    final updated = List<Map<String, dynamic>>.from(currentLocations)
      ..removeAt(index);
    await FirebaseFirestore.instance.collection('sites').doc(docId).update({
      'gpsLocations': updated,
    });
  }

  void _showSetLocationDialog(String docId, String siteName) {
    final labelController = TextEditingController();
    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: Text('$siteName — GPS Locations'),
          content: SizedBox(
            width: double.maxFinite,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Live via StreamBuilder rather than a local list copy —
                  // captures/deletes write straight to Firestore, so this
                  // reflects them immediately with no manual dialog-state
                  // bookkeeping needed for the list itself.
                  StreamBuilder<DocumentSnapshot>(
                    stream: FirebaseFirestore.instance
                        .collection('sites')
                        .doc(docId)
                        .snapshots(),
                    builder: (context, snapshot) {
                      final data =
                          snapshot.data?.data() as Map<String, dynamic>?;
                      final locations = data == null
                          ? <Map<String, dynamic>>[]
                          : siteGpsLocations(data);
                      if (locations.isEmpty) {
                        return const Padding(
                          padding: EdgeInsets.symmetric(vertical: 8),
                          child: Text(
                            'No GPS locations captured yet.',
                            style: TextStyle(color: Colors.grey),
                          ),
                        );
                      }
                      return Column(
                        children: [
                          for (var i = 0; i < locations.length; i++)
                            ListTile(
                              dense: true,
                              contentPadding: EdgeInsets.zero,
                              leading: const Icon(
                                Icons.location_on,
                                color: Colors.teal,
                              ),
                              title: Text(
                                (locations[i]['label'] ?? 'Location ${i + 1}')
                                    .toString(),
                              ),
                              subtitle: Text(
                                '${(locations[i]['latitude'] as num).toStringAsFixed(4)}, '
                                '${(locations[i]['longitude'] as num).toStringAsFixed(4)}',
                              ),
                              trailing: IconButton(
                                icon: const Icon(
                                  Icons.delete,
                                  color: Colors.red,
                                  size: 20,
                                ),
                                onPressed: () =>
                                    _deleteSiteGpsLocation(docId, locations, i),
                              ),
                            ),
                        ],
                      );
                    },
                  ),
                  const Divider(),
                  TextField(
                    controller: labelController,
                    // Rebuilds the dialog so the capture button's label
                    // below stays in sync with what's typed here.
                    onChanged: (_) => setDialogState(() {}),
                    decoration: const InputDecoration(
                      labelText: 'Label',
                      hintText: 'e.g. Entrance 2, Gate B',
                      border: OutlineInputBorder(),
                    ),
                  ),
                  const SizedBox(height: 12),
                  SizedBox(
                    width: double.infinity,
                    child: ElevatedButton.icon(
                      onPressed: () =>
                          _captureSiteGpsLocation(docId, labelController),
                      icon: const Icon(Icons.my_location),
                      label: Text(
                        '+ Capture Current Location as '
                        '"${labelController.text.trim().isEmpty ? '...' : labelController.text.trim()}"',
                      ),
                    ),
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Done'),
            ),
          ],
        ),
      ),
    );
  }

  // Same shape as SiteHistoryScreen._showChangeSupervisorDialog — a
  // StreamBuilder list of eligible users, tap to assign, checkmark on the
  // currently-assigned one. canOperateMachine == true here instead of
  // role == 'supervisor', writing sites/{docId}.assignedOperatorUid/Name
  // instead of assignedSupervisorUid/Name. QR Scan's
  // _showQrCategorySelectionDialog reads assignedOperatorName from this
  // same site doc to auto-fill machineOperatorName on a scanned load.
  void _showAssignMachineOperatorDialog(
    String docId,
    String? currentOperatorUid,
  ) {
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Assigned Machine Operator'),
        content: SizedBox(
          width: double.maxFinite,
          child: StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('users')
                .where('canOperateMachine', isEqualTo: true)
                .snapshots(),
            builder: (context, snapshot) {
              if (!snapshot.hasData) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 20),
                  child: Center(child: CircularProgressIndicator()),
                );
              }
              final operators = snapshot.data!.docs;
              if (operators.isEmpty) {
                return const Padding(
                  padding: EdgeInsets.symmetric(vertical: 20),
                  child: Text('No machine operators available.'),
                );
              }
              return SizedBox(
                height: 300,
                child: ListView.builder(
                  shrinkWrap: true,
                  itemCount: operators.length,
                  itemBuilder: (context, index) {
                    final data =
                        operators[index].data() as Map<String, dynamic>;
                    final uid = operators[index].id;
                    final isSelected = uid == currentOperatorUid;
                    return ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.orange.withOpacity(0.15),
                        child: const Icon(
                          Icons.engineering,
                          color: Colors.orange,
                        ),
                      ),
                      title: Text(data['name'] ?? ''),
                      trailing: isSelected
                          ? const Icon(Icons.check, color: Colors.orange)
                          : null,
                      onTap: () async {
                        await FirebaseFirestore.instance
                            .collection('sites')
                            .doc(docId)
                            .update({
                              'assignedOperatorUid': uid,
                              'assignedOperatorName': data['name'] ?? '',
                            });
                        if (context.mounted) Navigator.pop(context);
                      },
                    );
                  },
                ),
              );
            },
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
        ],
      ),
    );
  }

  // Renaming only updates the sites/{docId} doc — existing work_records/
  // fuel_entries keep whatever siteName string they already have (they're
  // historical snapshots, not live references). Live consumers (Working
  // Site search picker, Unloading Site autocomplete) query this doc
  // directly, so they pick up the new name automatically with no code
  // change needed. The Google Sheet tab mapping is different: it's resolved
  // through the site's `sheetName` field when set (see _syncToSiteSpecificSheet),
  // falling back to the static kSiteSheetMap keyed by the site's current
  // name — so a rename alone does NOT require re-editing kSiteSheetMap
  // unless the site has no `sheetName` override set here.
  Future<void> _showEditSiteNameDialog(
    String docId,
    String currentName,
    String? currentSheetName,
    List<dynamic>? currentAvailableCategories,
  ) {
    final nameController = TextEditingController(text: currentName);
    final sheetNameController = TextEditingController(
      text: currentSheetName ?? '',
    );
    final selectedCategories = <String>{
      ...?currentAvailableCategories?.map((c) => c.toString()),
    };
    return showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text('Rename Site'),
          content: SizedBox(
            width: double.maxFinite,
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  TextField(
                    controller: nameController,
                    autofocus: true,
                    decoration: const InputDecoration(labelText: 'Site Name'),
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: sheetNameController,
                    decoration: const InputDecoration(
                      labelText: 'Google Sheet Tab Name (optional)',
                      helperText:
                          'Pins this site\'s sync target so renaming the '
                          'site above never changes which sheet tab it '
                          'syncs to. Leave blank to use the default '
                          'name-based mapping.',
                      helperMaxLines: 3,
                    ),
                  ),
                  const SizedBox(height: 16),
                  const Text(
                    'Available Loading Categories',
                    style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
                  ),
                  const Text(
                    'Used by the Supervisor QR Scan flow to offer only the '
                    'categories relevant to this site.',
                    style: TextStyle(fontSize: 12, color: Colors.grey),
                  ),
                  // Live from the Admin-managed master list (Availability
                  // screen), not the old hardcoded
                  // kLoadingCategories + kOtherCategories — that mixed in
                  // non-loading items like Fuel Filling/Maintenance.
                  StreamBuilder<QuerySnapshot>(
                    stream: FirebaseFirestore.instance
                        .collection('loading_availability_options')
                        .orderBy('createdAt')
                        .snapshots(),
                    builder: (context, snapshot) {
                      if (!snapshot.hasData) {
                        return const Padding(
                          padding: EdgeInsets.symmetric(vertical: 12),
                          child: Center(child: CircularProgressIndicator()),
                        );
                      }
                      final items = snapshot.data!.docs;
                      if (items.isEmpty) {
                        return const Padding(
                          padding: EdgeInsets.symmetric(vertical: 8),
                          child: Text(
                            'No availability items yet — add some in '
                            'Admin → Availability.',
                            style: TextStyle(fontSize: 12, color: Colors.grey),
                          ),
                        );
                      }
                      return Column(
                        children: items.map((doc) {
                          final category =
                              ((doc.data() as Map<String, dynamic>)['name'] ??
                                      '')
                                  .toString();
                          return CheckboxListTile(
                            dense: true,
                            contentPadding: EdgeInsets.zero,
                            controlAffinity: ListTileControlAffinity.leading,
                            title: Text(category),
                            value: selectedCategories.contains(category),
                            onChanged: (checked) => setDialogState(() {
                              if (checked == true) {
                                selectedCategories.add(category);
                              } else {
                                selectedCategories.remove(category);
                              }
                            }),
                          );
                        }).toList(),
                      );
                    },
                  ),
                ],
              ),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                final newName = nameController.text.trim();
                if (newName.isEmpty) {
                  ScaffoldMessenger.of(dialogContext).showSnackBar(
                    const SnackBar(content: Text('Please enter a site name.')),
                  );
                  return;
                }

                // Same trim/uppercase duplicate-check pattern as _addSite,
                // excluding this site's own doc so saving an unchanged name
                // (or just a case/whitespace tweak of it) doesn't falsely
                // flag itself as a duplicate.
                final existingSites = await FirebaseFirestore.instance
                    .collection('sites')
                    .get();
                final normalizedEntry = newName.toUpperCase();
                final isDuplicate = existingSites.docs.any((doc) {
                  if (doc.id == docId) return false;
                  final existingName =
                      (doc.data()['name'] as String?)?.trim().toUpperCase() ??
                      '';
                  return existingName == normalizedEntry;
                });

                if (isDuplicate) {
                  ScaffoldMessenger.of(dialogContext).showSnackBar(
                    const SnackBar(
                      content: Text(
                        'This name is already used by another site.',
                      ),
                      backgroundColor: Colors.red,
                    ),
                  );
                  return;
                }

                try {
                  final newSheetName = sheetNameController.text.trim();
                  await FirebaseFirestore.instance
                      .collection('sites')
                      .doc(docId)
                      .update({
                        'name': newName,
                        'sheetName': newSheetName.isEmpty ? null : newSheetName,
                        'availableCategories': selectedCategories.toList(),
                      });
                  if (dialogContext.mounted) {
                    Navigator.pop(dialogContext);
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('Site name updated')),
                    );
                  }
                } catch (e) {
                  if (dialogContext.mounted) {
                    ScaffoldMessenger.of(dialogContext).showSnackBar(
                      SnackBar(content: Text('Failed to update site: $e')),
                    );
                  }
                }
              },
              child: const Text('SAVE'),
            ),
          ],
        ),
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Manage Sites'),
        backgroundColor: Colors.teal[800],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                TextField(
                  controller: _siteNameController,
                  onChanged: (_) => setState(() {}),
                  decoration: InputDecoration(
                    labelText: 'Site Name',
                    prefixIcon: const Icon(Icons.location_city),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('sites')
                      .snapshots(),
                  builder: (context, snapshot) {
                    final query = _siteNameController.text.trim().toLowerCase();
                    if (query.isEmpty || !snapshot.hasData)
                      return const SizedBox.shrink();
                    final matches = snapshot.data!.docs
                        .map(
                          (doc) =>
                              (doc.data() as Map<String, dynamic>)['name']
                                  as String?,
                        )
                        .whereType<String>()
                        .where((name) => name.toLowerCase().contains(query))
                        .take(5)
                        .toList();
                    if (matches.isEmpty) return const SizedBox.shrink();
                    return Padding(
                      padding: const EdgeInsets.only(top: 8),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          const Text(
                            'Similar sites already registered:',
                            style: TextStyle(
                              fontSize: 12,
                              color: Colors.orange,
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                          const SizedBox(height: 4),
                          Wrap(
                            spacing: 6,
                            runSpacing: 6,
                            children: matches
                                .map(
                                  (name) => Chip(
                                    label: Text(
                                      name,
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                    backgroundColor: Colors.orange[50],
                                    visualDensity: VisualDensity.compact,
                                    materialTapTargetSize:
                                        MaterialTapTargetSize.shrinkWrap,
                                  ),
                                )
                                .toList(),
                          ),
                        ],
                      ),
                    );
                  },
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _siteLocationController,
                  decoration: InputDecoration(
                    labelText: 'Location / Address',
                    prefixIcon: const Icon(Icons.map),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                  title: const Text('Is this a Plant Site?'),
                  value: _isPlantSite,
                  onChanged: (val) =>
                      setState(() => _isPlantSite = val ?? false),
                ),
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                  title: const Text('Can be selected as a Working Site?'),
                  value: _canBeLoadingSite,
                  onChanged: (val) =>
                      setState(() => _canBeLoadingSite = val ?? true),
                ),
                CheckboxListTile(
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                  title: const Text('Can be selected as an Unloading Site?'),
                  value: _canBeUnloadingSite,
                  onChanged: (val) =>
                      setState(() => _canBeUnloadingSite = val ?? true),
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _addSite,
                    icon: const Icon(Icons.add, color: Colors.white),
                    label: const Text(
                      'ADD SITE',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.teal[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Divider(),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('sites')
                  .orderBy('createdAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                  return const Center(child: Text('No sites added yet.'));
                }

                final allSites = snapshot.data!.docs;
                final loadingSites = allSites
                    .where(
                      (doc) =>
                          (doc.data()
                              as Map<String, dynamic>)['canBeLoadingSite'] !=
                          false,
                    )
                    .toList();
                final unloadingSites = allSites
                    .where(
                      (doc) =>
                          (doc.data()
                              as Map<String, dynamic>)['canBeUnloadingSite'] !=
                          false,
                    )
                    .toList();

                return DefaultTabController(
                  length: 2,
                  child: Column(
                    children: [
                      const TabBar(
                        labelColor: Colors.teal,
                        unselectedLabelColor: Colors.black54,
                        indicatorColor: Colors.teal,
                        tabs: [
                          Tab(text: 'Loading Sites'),
                          Tab(text: 'Unloading Sites'),
                        ],
                      ),
                      Expanded(
                        child: TabBarView(
                          children: [
                            _buildSiteList(loadingSites),
                            _buildSiteList(unloadingSites),
                          ],
                        ),
                      ),
                    ],
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildSiteList(List<QueryDocumentSnapshot> sites) {
    if (sites.isEmpty) {
      return const Center(child: Text('No sites in this category.'));
    }

    return ListView.builder(
      padding: const EdgeInsets.all(12),
      itemCount: sites.length,
      itemBuilder: (context, index) {
        final data = sites[index].data() as Map<String, dynamic>;
        final docId = sites[index].id;
        final siteName = (data['name'] ?? '').toString();
        final gpsLocationCount = siteGpsLocations(data).length;
        final assignedOperatorName = data['assignedOperatorName'] as String?;
        final assignedOperatorUid = data['assignedOperatorUid'] as String?;

        return _WebStaggeredFadeIn(
          index: index,
          child: _WebHoverCard(
            child: Card(
              margin: const EdgeInsets.only(bottom: 10),
              child: ListTile(
                leading: CircleAvatar(
                  backgroundColor: Colors.teal.withOpacity(0.15),
                  child: const Icon(Icons.location_on, color: Colors.teal),
                ),
                title: Row(
                  children: [
                    Flexible(child: Text(siteName)),
                    if (gpsLocationCount > 0) ...[
                      const SizedBox(width: 8),
                      Text(
                        '📍 $gpsLocationCount '
                        '${gpsLocationCount == 1 ? 'Location' : 'Locations'} Set',
                        style: const TextStyle(
                          color: Colors.green,
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                    if (assignedOperatorName != null &&
                        assignedOperatorName.isNotEmpty) ...[
                      const SizedBox(width: 8),
                      Text(
                        '👷 $assignedOperatorName',
                        style: const TextStyle(
                          color: Colors.orange,
                          fontSize: 11,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ],
                  ],
                ),
                subtitle: Text(
                  [
                    data['location'] ?? '',
                    if (data['isPlantSite'] == true) '🏭 Plant Site',
                    if (data['canBeLoadingSite'] == false)
                      '🚫 Not a Working Site',
                  ].where((s) => s.isNotEmpty).join('  •  '),
                ),
                trailing: Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    IconButton(
                      icon: const Icon(
                        Icons.my_location,
                        color: AppTheme.primaryMid,
                      ),
                      tooltip: 'Set Location',
                      onPressed: () => _showSetLocationDialog(docId, siteName),
                    ),
                    IconButton(
                      icon: const Icon(
                        Icons.engineering,
                        color: AppTheme.primaryMid,
                      ),
                      tooltip: 'Assigned Machine Operator',
                      onPressed: () => _showAssignMachineOperatorDialog(
                        docId,
                        assignedOperatorUid,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.edit, color: AppTheme.primaryMid),
                      onPressed: () => _showEditSiteNameDialog(
                        docId,
                        siteName,
                        data['sheetName'] as String?,
                        data['availableCategories'] as List<dynamic>?,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.delete, color: Colors.red),
                      onPressed: () => confirmDelete(
                        context: context,
                        title: 'Delete Site?',
                        message:
                            'Are you sure you want to delete this site? This cannot be undone.',
                        onConfirm: () => _deleteSite(docId),
                      ),
                    ),
                  ],
                ),
                onTap: () => pushWebAware(
                  context,
                  SiteHistoryScreen(
                    siteId: docId,
                    siteName: data['name'] ?? '',
                  ),
                ),
              ),
            ),
          ),
        );
      },
    );
  }
}

// ---------------- OWNER DASHBOARD ----------------
class OwnerDashboard extends StatefulWidget {
  final String name;
  const OwnerDashboard({super.key, required this.name});

  @override
  State<OwnerDashboard> createState() => _OwnerDashboardState();
}

class _OwnerDashboardState extends State<OwnerDashboard> {
  final _searchController = TextEditingController();
  String _searchText = '';

  String _todayString() {
    final today = DateTime.now();
    return "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";
  }

  Future<void> _logout() async {
    await FirebaseAuth.instance.signOut();
    if (mounted) {
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  Future<Map<String, int>> _calculateCategoryLoadCounts(
    List<QueryDocumentSnapshot> sessions,
  ) async {
    final Map<String, int> loadCountsByCategory = {};

    for (final session in sessions) {
      final recordsSnap = await FirebaseFirestore.instance
          .collection('daily_sessions')
          .doc(session.id)
          .collection('work_records')
          .get();

      for (final rec in recordsSnap.docs) {
        final data = rec.data();
        if (data['isCompleted'] != true) continue;

        final category = data['category'] ?? 'Unknown';
        loadCountsByCategory[category] =
            (loadCountsByCategory[category] ?? 0) + 1;
      }
    }

    return loadCountsByCategory;
  }

  Widget _summaryCard(String label, int value, IconData icon, Color color) {
    const valueStyle = TextStyle(fontSize: 22, fontWeight: FontWeight.bold);
    return Card(
      elevation: 2,
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Icon(icon, color: color, size: 28),
            const SizedBox(height: 8),
            kIsWeb
                ? TweenAnimationBuilder<int>(
                    tween: IntTween(begin: 0, end: value),
                    duration: const Duration(milliseconds: 800),
                    curve: Curves.easeOut,
                    builder: (context, animatedValue, _) =>
                        Text('$animatedValue', style: valueStyle),
                  )
                : Text('$value', style: valueStyle),
            Text(
              label,
              style: const TextStyle(fontSize: 12, color: Colors.grey),
            ),
          ],
        ),
      ),
    );
  }

  // ---- Extracted so both the (unchanged) mobile body and the new web body
  // can render the exact same chart/quick-links/status list without
  // duplicating the widget trees. ----

  Widget _buildCategoryChart(String todayDate) {
    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance
          .collection('daily_sessions')
          .where('date', isEqualTo: todayDate)
          .snapshots(),
      builder: (context, sessionSnap) {
        if (!sessionSnap.hasData || sessionSnap.data!.docs.isEmpty) {
          return const Padding(
            padding: EdgeInsets.symmetric(vertical: 20),
            child: Text('No data yet for today.'),
          );
        }

        return FutureBuilder<Map<String, int>>(
          future: _calculateCategoryLoadCounts(sessionSnap.data!.docs),
          builder: (context, snapshot) {
            if (!snapshot.hasData) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 30),
                child: Center(child: CircularProgressIndicator()),
              );
            }

            final totals = snapshot.data!;
            if (totals.isEmpty || totals.values.every((v) => v == 0)) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 20),
                child: Text('No loads completed yet today.'),
              );
            }

            final colors = [
              Colors.orange,
              Colors.blue,
              Colors.green,
              Colors.purple,
              Colors.red,
              Colors.teal,
              Colors.brown,
              Colors.indigo,
            ];

            final entries = totals.entries.toList();

            return Card(
              elevation: 2,
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(12),
              ),
              child: Padding(
                padding: const EdgeInsets.all(16),
                child: Column(
                  children: [
                    SizedBox(
                      height: 180,
                      child: PieChart(
                        PieChartData(
                          sectionsSpace: 2,
                          centerSpaceRadius: 40,
                          sections: List.generate(entries.length, (i) {
                            final count = entries[i].value;
                            return PieChartSectionData(
                              value: count.toDouble(),
                              title: '$count',
                              color: colors[i % colors.length],
                              radius: 55,
                              titleStyle: const TextStyle(
                                fontSize: 12,
                                fontWeight: FontWeight.bold,
                                color: Colors.white,
                              ),
                            );
                          }),
                        ),
                      ),
                    ),
                    const SizedBox(height: 16),
                    Wrap(
                      spacing: 12,
                      runSpacing: 8,
                      children: List.generate(entries.length, (i) {
                        return Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Container(
                              width: 10,
                              height: 10,
                              decoration: BoxDecoration(
                                color: colors[i % colors.length],
                                shape: BoxShape.circle,
                              ),
                            ),
                            const SizedBox(width: 4),
                            Text(
                              entries[i].key,
                              style: const TextStyle(fontSize: 12),
                            ),
                          ],
                        );
                      }),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

