  Widget _buildLiveMachineStatus(String todayDate) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        const Text(
          'Live Machine Status',
          style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold),
        ),
        const SizedBox(height: 12),
        StreamBuilder<QuerySnapshot>(
          stream: FirebaseFirestore.instance
              .collection('daily_sessions')
              .where('date', isEqualTo: todayDate)
              .snapshots(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting) {
              return const Center(child: CircularProgressIndicator());
            }
            if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
              return const Padding(
                padding: EdgeInsets.symmetric(vertical: 20),
                child: Text('No machines working today.'),
              );
            }

            // Sort client-side by createdAt (avoids needing a
            // composite Firestore index for date + createdAt).
            final sessions = snapshot.data!.docs.toList()
              ..sort((a, b) {
                final aTs = (a.data() as Map)['createdAt'] as Timestamp?;
                final bTs = (b.data() as Map)['createdAt'] as Timestamp?;
                if (aTs == null || bTs == null) return 0;
                return bTs.compareTo(aTs);
              });

            return ListView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              itemCount: sessions.length,
              itemBuilder: (context, index) {
                final session = sessions[index];
                final sData = session.data() as Map<String, dynamic>;
                final isActive = sData['status'] == 'active';

                return Card(
                  margin: const EdgeInsets.only(bottom: 10),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Padding(
                    padding: const EdgeInsets.all(12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(
                          mainAxisAlignment: MainAxisAlignment.spaceBetween,
                          children: [
                            Expanded(
                              child: Text(
                                sData['machineName'] ?? '',
                                style: const TextStyle(
                                  fontWeight: FontWeight.bold,
                                  fontSize: 16,
                                ),
                              ),
                            ),
                            Container(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 8,
                                vertical: 4,
                              ),
                              decoration: BoxDecoration(
                                color: isActive ? Colors.green : Colors.grey,
                                borderRadius: BorderRadius.circular(20),
                              ),
                              child: Text(
                                isActive ? 'ACTIVE' : 'COMPLETED',
                                style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 11,
                                ),
                              ),
                            ),
                          ],
                        ),
                        const SizedBox(height: 4),
                        Text(
                          'Site: ${sData['siteName']} • Supervisor: ${sData['supervisorName']}',
                          style: const TextStyle(
                            fontSize: 13,
                            color: Colors.black87,
                          ),
                        ),
                        const Divider(height: 16),

                        // Current work record (running one)
                        StreamBuilder<QuerySnapshot>(
                          stream: FirebaseFirestore.instance
                              .collection('daily_sessions')
                              .doc(session.id)
                              .collection('work_records')
                              .where('status', isEqualTo: 'running')
                              .limit(1)
                              .snapshots(),
                          builder: (context, workSnap) {
                            if (!workSnap.hasData ||
                                workSnap.data!.docs.isEmpty) {
                              return const Text(
                                'No active work right now',
                                style: TextStyle(
                                  fontSize: 13,
                                  color: Colors.grey,
                                ),
                              );
                            }
                            final workData =
                                workSnap.data!.docs.first.data()
                                    as Map<String, dynamic>;
                            return Row(
                              children: [
                                const Icon(
                                  Icons.play_circle_fill,
                                  color: Colors.green,
                                  size: 18,
                                ),
                                const SizedBox(width: 6),
                                Text(
                                  'Working: ${workData['category']}',
                                  style: const TextStyle(
                                    fontSize: 13,
                                    fontWeight: FontWeight.w600,
                                  ),
                                ),
                              ],
                            );
                          },
                        ),
                      ],
                    ),
                  ),
                );
              },
            );
          },
        ),
      ],
    );
  }

  // ---- New web-only pieces: search bar + results, and the 4-card grid. ----

  Widget _buildSearchBar() {
    return TextField(
      controller: _searchController,
      onChanged: (val) => setState(() => _searchText = val),
      decoration: InputDecoration(
        hintText: 'Search sites, machines, trucks...',
        prefixIcon: const Icon(Icons.search),
        filled: true,
        fillColor: Colors.white,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(30),
          borderSide: BorderSide.none,
        ),
      ),
    );
  }

  Widget _buildSearchResults() {
    final query = _searchText.trim().toLowerCase();
    if (query.isEmpty) return const SizedBox.shrink();

    return Container(
      margin: const EdgeInsets.only(top: 8),
      constraints: const BoxConstraints(maxHeight: 320),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
        boxShadow: [AppTheme.softShadow],
      ),
      child: StreamBuilder<QuerySnapshot>(
        stream: FirebaseFirestore.instance.collection('sites').snapshots(),
        builder: (context, siteSnap) {
          return StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('machines')
                .snapshots(),
            builder: (context, machineSnap) {
              return StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                    .collection('trucks')
                    .snapshots(),
                builder: (context, truckSnap) {
                  final results = <_OwnerSearchResult>[];

                  for (final doc
                      in siteSnap.data?.docs ??
                          const <QueryDocumentSnapshot>[]) {
                    final data = doc.data() as Map<String, dynamic>;
                    final name = (data['name'] ?? '').toString();
                    if (name.toLowerCase().contains(query)) {
                      results.add(
                        _OwnerSearchResult(
                          type: 'Site',
                          icon: Icons.location_on,
                          id: doc.id,
                          name: name,
                          data: data,
                        ),
                      );
                    }
                  }
                  for (final doc
                      in machineSnap.data?.docs ??
                          const <QueryDocumentSnapshot>[]) {
                    final data = doc.data() as Map<String, dynamic>;
                    final name = (data['name'] ?? '').toString();
                    if (name.toLowerCase().contains(query)) {
                      results.add(
                        _OwnerSearchResult(
                          type: 'Machine',
                          icon: Icons.precision_manufacturing,
                          id: doc.id,
                          name: name,
                          data: data,
                        ),
                      );
                    }
                  }
                  for (final doc
                      in truckSnap.data?.docs ??
                          const <QueryDocumentSnapshot>[]) {
                    final data = doc.data() as Map<String, dynamic>;
                    final name = (data['truckNumber'] ?? '').toString();
                    if (name.toLowerCase().contains(query)) {
                      results.add(
                        _OwnerSearchResult(
                          type: 'Truck',
                          icon: Icons.local_shipping,
                          id: doc.id,
                          name: name,
                          data: data,
                        ),
                      );
                    }
                  }

                  if (results.isEmpty) {
                    return const Padding(
                      padding: EdgeInsets.all(16),
                      child: Text(
                        'No matches found.',
                        style: TextStyle(color: Colors.grey),
                      ),
                    );
                  }

                  return ListView.builder(
                    shrinkWrap: true,
                    padding: const EdgeInsets.symmetric(vertical: 8),
                    itemCount: results.length,
                    itemBuilder: (context, index) {
                      final r = results[index];
                      return ListTile(
                        leading: Icon(r.icon, color: AppTheme.primaryMid),
                        title: Text(r.name),
                        subtitle: Text(r.type),
                        onTap: () {
                          setState(() {
                            _searchController.clear();
                            _searchText = '';
                          });
                          switch (r.type) {
                            case 'Site':
                              Navigator.push(
                                context,
                                MaterialPageRoute(
                                  builder: (_) => SiteHistoryScreen(
                                    siteId: r.id,
                                    siteName: r.name,
                                  ),
                                ),
                              );
                              break;
                            case 'Machine':
                              Navigator.push(
                                context,
                                MaterialPageRoute(
                                  builder: (_) => MachineProfileScreen(
                                    machineId: r.id,
                                    machineName: r.name,
                                    machineType: r.data['type'] ?? '',
                                    machineNumber: r.data['number'] ?? '',
                                  ),
                                ),
                              );
                              break;
                            case 'Truck':
                              Navigator.push(
                                context,
                                MaterialPageRoute(
                                  builder: (_) => TruckProfileScreen(
                                    truckId: r.id,
                                    truckNumber: r.name,
                                  ),
                                ),
                              );
                              break;
                          }
                        },
                      );
                    },
                  );
                },
              );
            },
          );
        },
      ),
    );
  }

  Widget _buildSummaryCardsGrid(BuildContext context) {
    final columns = MediaQuery.of(context).size.width > 1000 ? 4 : 2;

    return StreamBuilder<QuerySnapshot>(
      stream: FirebaseFirestore.instance.collection('sites').snapshots(),
      builder: (context, siteSnap) {
        return StreamBuilder<QuerySnapshot>(
          stream: FirebaseFirestore.instance.collection('machines').snapshots(),
          builder: (context, machineSnap) {
            return StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('trucks')
                  .snapshots(),
              builder: (context, truckSnap) {
                return StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('users')
                      .where(
                        'role',
                        whereIn: ['supervisor', 'driver', 'field_worker'],
                      )
                      .snapshots(),
                  builder: (context, teamSnap) {
                    final cards = [
                      _summaryCard(
                        'Total Sites',
                        siteSnap.data?.docs.length ?? 0,
                        Icons.location_on,
                        Colors.teal,
                      ),
                      _summaryCard(
                        'Total Machines',
                        machineSnap.data?.docs.length ?? 0,
                        Icons.precision_manufacturing,
                        Colors.orange,
                      ),
                      _summaryCard(
                        'Total Trucks',
                        truckSnap.data?.docs.length ?? 0,
                        Icons.local_shipping,
                        Colors.deepOrange,
                      ),
                      _summaryCard(
                        'Total Team Members',
                        teamSnap.data?.docs.length ?? 0,
                        Icons.groups,
                        Colors.deepPurple,
                      ),
                    ];

                    return GridView.count(
                      shrinkWrap: true,
                      physics: const NeverScrollableScrollPhysics(),
                      crossAxisCount: columns,
                      crossAxisSpacing: 12,
                      mainAxisSpacing: 12,
                      childAspectRatio: 1.6,
                      children: [
                        for (int i = 0; i < cards.length; i++)
                          _WebStaggeredFadeIn(index: i, child: cards[i]),
                      ],
                    );
                  },
                );
              },
            );
          },
        );
      },
    );
  }

