    // appear in the fetched records, not a Firestore stream.
    final unloadingSites =
        allRecords
            .map((r) => (r['unloadingSiteName'] ?? '').toString().trim())
            .where((name) => name.isNotEmpty)
            .toSet()
            .toList()
          ..sort();

    return Wrap(
      spacing: 12,
      runSpacing: 12,
      crossAxisAlignment: WrapCrossAlignment.center,
      children: [
