// ---------------- FUEL ENTRY SCREEN ----------------
class FuelEntryScreen extends StatefulWidget {
  final String supervisorName;
  const FuelEntryScreen({super.key, required this.supervisorName});

  @override
  State<FuelEntryScreen> createState() => _FuelEntryScreenState();
}

class _FuelEntryScreenState extends State<FuelEntryScreen> {
  String? _selectedStationId;
  String? _selectedStationName;
  final _truckNumberController = TextEditingController();
  final _litersController = TextEditingController();
  final _amountController = TextEditingController();
  final _billNumberController = TextEditingController();
  String? _billPhotoBase64;
  String _errorText = '';
  bool _isSubmitting = false;

  Future<void> _capturePhoto() async {
    try {
      final picker = ImagePicker();
      final pickedFile = await picker.pickImage(
        source: ImageSource.camera,
        maxWidth: 800,
        imageQuality: 60,
      );
      if (pickedFile == null) return;

      final bytes = await pickedFile.readAsBytes();
      final base64String = base64Encode(bytes);

      // Firestore document limit is 1MB; keep a safety margin
      if (base64String.length > 700000) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(content: Text('Photo too large. Please retake.')),
          );
        }
        return;
      }

      setState(() => _billPhotoBase64 = base64String);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Error capturing photo: $e')));
      }
    }
  }

  Future<void> _submitFuelEntry() async {
    if (_isSubmitting) return;

    if (_selectedStationId == null || _selectedStationName == null) {
      setState(() => _errorText = 'Please select a fuel station.');
      return;
    }
    if (_truckNumberController.text.trim().isEmpty) {
      setState(() => _errorText = 'Please enter a truck number.');
      return;
    }
    final liters = double.tryParse(_litersController.text.trim());
    if (liters == null) {
      setState(() => _errorText = 'Please enter a valid fuel amount (liters).');
      return;
    }
    final amount = double.tryParse(_amountController.text.trim());
    if (amount == null) {
      setState(() => _errorText = 'Please enter a valid amount (Rs.).');
      return;
    }
    if (_billPhotoBase64 == null) {
      setState(() => _errorText = 'Bill photo is required.');
      return;
    }

    setState(() {
      _errorText = '';
      _isSubmitting = true;
    });

    try {
      final billNumber = _billNumberController.text.trim();
      final docRef = await FirebaseFirestore.instance
          .collection('fuel_entries')
          .add({
            'supervisorUid': FirebaseAuth.instance.currentUser!.uid,
            'supervisorName': widget.supervisorName,
            'fuelStationId': _selectedStationId,
            'fuelStationName': _selectedStationName,
            'truckNumber': _truckNumberController.text.trim(),
            'liters': liters,
            'amount': amount,
            'billNumber': billNumber.isEmpty ? null : billNumber,
            'billPhotoBase64': _billPhotoBase64,
            'createdAt': FieldValue.serverTimestamp(),
            'date': GoogleSheetsService.formatDate(DateTime.now()),
          });

      // Sheets row built from the controllers before they're cleared below.
      // Bill photo is intentionally excluded — it's Base64 image data and
      // doesn't belong in a spreadsheet cell.
      GoogleSheetsService.sendRow(
        sheetName: 'Fuel_Reports',
        row: [
          GoogleSheetsService.formatDate(DateTime.now()),
          widget.supervisorName,
          _selectedStationName,
          _truckNumberController.text.trim(),
          _litersController.text.trim(),
          _amountController.text.trim(),
          billNumber.isEmpty ? '' : billNumber,
          GoogleSheetsService.formatTime(Timestamp.now()),
        ],
        recordId: docRef.id,
      );

      _truckNumberController.clear();
      _litersController.clear();
      _amountController.clear();
      _billNumberController.clear();

      setState(() {
        _selectedStationId = null;
        _selectedStationName = null;
        _billPhotoBase64 = null;
        _isSubmitting = false;
      });

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Fuel entry submitted successfully!')),
        );
      }
    } catch (e) {
      setState(() => _isSubmitting = false);
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to submit fuel entry: $e')),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final isDesktop = MediaQuery.of(context).size.width > 700;

    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(4, 4, 12, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    const Expanded(
                      child: Text(
                        'Fuel Entry',
                        style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: Colors.white,
                        ),
                      ),
                    ),
                    IconButton(
                      // Placeholder for now — a dedicated fuel history screen
                      // is a follow-up feature.
                      icon: const Icon(Icons.history, color: Colors.white),
                      onPressed: () {
                        ScaffoldMessenger.of(context).showSnackBar(
                          const SnackBar(
                            content: Text('Fuel history coming soon.'),
                          ),
                        );
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: Center(
                  child: SingleChildScrollView(
                    padding: const EdgeInsets.all(24.0),
                    child: ConstrainedBox(
                      constraints: BoxConstraints(
                        maxWidth: isDesktop ? 480 : double.infinity,
                      ),
                      child: LoginFormCard(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.stretch,
                          children: [
                            const Text(
                              'Select Fuel Station',
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            const SizedBox(height: 8),
                            StreamBuilder<QuerySnapshot>(
                              stream: FirebaseFirestore.instance
                                  .collection('fuel_stations')
                                  .snapshots(),
                              builder: (context, snapshot) {
                                if (!snapshot.hasData) {
                                  return const Padding(
                                    padding: EdgeInsets.symmetric(vertical: 12),
                                    child: Center(
                                      child: CircularProgressIndicator(),
                                    ),
                                  );
                                }
                                final stations = snapshot.data!.docs;
                                return DropdownButtonFormField<String>(
                                  initialValue: _selectedStationId,
                                  decoration: InputDecoration(
                                    prefixIcon: const Icon(
                                      Icons.local_gas_station,
                                    ),
                                    border: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(12),
                                    ),
                                  ),
                                  items: stations.map((doc) {
                                    final data =
                                        doc.data() as Map<String, dynamic>;
                                    return DropdownMenuItem<String>(
                                      value: doc.id,
                                      child: Text(data['name'] ?? ''),
                                    );
                                  }).toList(),
                                  onChanged: (val) {
                                    final selected = stations.firstWhere(
                                      (d) => d.id == val,
                                    );
                                    final data =
                                        selected.data() as Map<String, dynamic>;
                                    setState(() {
                                      _selectedStationId = val;
                                      _selectedStationName = data['name'];
                                    });
                                  },
                                );
                              },
                            ),
                            const SizedBox(height: 16),
                            TextField(
                              controller: _truckNumberController,
                              textCapitalization: TextCapitalization.characters,
                              decoration: InputDecoration(
                                labelText: 'Truck Number',
                                prefixIcon: const Icon(Icons.local_shipping),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                ),
                              ),
                            ),
                            const SizedBox(height: 16),
                            TextField(
                              controller: _litersController,
                              keyboardType: TextInputType.number,
                              decoration: InputDecoration(
                                labelText: 'Fuel (Liters)',
                                prefixIcon: const Icon(Icons.local_gas_station),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                ),
                              ),
                            ),
                            const SizedBox(height: 16),
                            TextField(
                              controller: _amountController,
                              keyboardType: TextInputType.number,
                              decoration: InputDecoration(
                                labelText: 'Amount (Rs.)',
                                prefixIcon: const Icon(Icons.payments),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                ),
                              ),
                            ),
                            const SizedBox(height: 16),
                            TextField(
                              controller: _billNumberController,
                              keyboardType: TextInputType.number,
                              inputFormatters: [
                                FilteringTextInputFormatter.digitsOnly,
                              ],
                              decoration: InputDecoration(
                                labelText: 'Bill Number (optional)',
                                prefixIcon: const Icon(Icons.receipt_long),
                                border: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                ),
                              ),
                            ),
                            const SizedBox(height: 16),
                            const Text(
                              'Bill Photo *',
                              style: TextStyle(fontWeight: FontWeight.bold),
                            ),
                            const SizedBox(height: 8),
                            GestureDetector(
                              onTap: _capturePhoto,
                              child: Container(
                                height: 160,
                                width: double.infinity,
                                decoration: BoxDecoration(
                                  color: Colors.grey[200],
                                  borderRadius: BorderRadius.circular(12),
                                  border: Border.all(color: Colors.grey[400]!),
                                ),
                                child: _billPhotoBase64 == null
                                    ? const Center(
                                        child: Column(
                                          mainAxisSize: MainAxisSize.min,
                                          children: [
                                            Icon(
                                              Icons.camera_alt,
                                              size: 36,
                                              color: Colors.grey,
                                            ),
                                            SizedBox(height: 8),
                                            Text(
                                              'Tap to take bill photo',
                                              style: TextStyle(
                                                color: Colors.grey,
                                              ),
                                            ),
                                          ],
                                        ),
                                      )
                                    : ClipRRect(
                                        borderRadius: BorderRadius.circular(12),
                                        child: Image.memory(
                                          base64Decode(_billPhotoBase64!),
                                          fit: BoxFit.cover,
                                          width: double.infinity,
                                        ),
                                      ),
                              ),
                            ),
                            if (_billPhotoBase64 != null)
                              Align(
                                alignment: Alignment.centerRight,
                                child: TextButton.icon(
                                  onPressed: _capturePhoto,
                                  icon: const Icon(Icons.refresh),
                                  label: const Text('Retake Photo'),
                                ),
                              ),
                            if (_errorText.isNotEmpty)
                              Padding(
                                padding: const EdgeInsets.only(
                                  top: 8,
                                  bottom: 8,
                                ),
                                child: Text(
                                  _errorText,
                                  style: const TextStyle(
                                    color: Colors.red,
                                    fontSize: 13,
                                  ),
                                ),
                              ),
                            const SizedBox(height: 16),
                            GradientButton(
                              label: _isSubmitting
                                  ? 'Submitting...'
                                  : 'SUBMIT FUEL ENTRY',
                              onTap: _submitFuelEntry,
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- SUPERVISOR SCREEN ----------------
class SupervisorScreen extends StatefulWidget {
  final String name;
  const SupervisorScreen({super.key, required this.name});

  @override
  State<SupervisorScreen> createState() => _SupervisorScreenState();
}

class _SupervisorScreenState extends State<SupervisorScreen> {
  String? _selectedMachineId;
  String? _selectedMachineName;
  String? _selectedSiteId;
  String? _selectedSiteName;
  final _startMeterController = TextEditingController();
  bool _isLoading = false;
  bool _checkingActiveSession = true;
  bool _isSiteLocked = false;
  String? _assignedSiteId;

  @override
  void initState() {
    super.initState();
    _checkForActiveSession();
  }

  Future<void> _checkForActiveSession() async {
    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      final existing = await FirebaseFirestore.instance
          .collection('daily_sessions')
          .where(
            'supervisorUid',
            isEqualTo: FirebaseAuth.instance.currentUser!.uid,
          )
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      if (existing.docs.isNotEmpty && mounted) {
        final data = existing.docs.first.data();
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => WorkSessionScreen(
              sessionId: existing.docs.first.id,
              machineName: data['machineName'] ?? '',
              siteName: data['siteName'] ?? '',
              siteId: data['siteId'] ?? '',
              supervisorName: widget.name,
              verificationCode: data['verificationCode'],
            ),
          ),
        );
        return;
      }
    } catch (e) {
      // If offline or error, just fall through to the normal selection screen
    }
    await _prefillAssignedSite();
    if (mounted) setState(() => _checkingActiveSession = false);
  }

  // If this supervisor has an assigned site (see SiteHistoryScreen's
  // "Assigned Supervisor" card), the Site field locks to it — this is a
  // hard restriction, not just a pre-fill (see _isSiteLocked and the
  // _startDay safety check below). No assigned site means the Site field
  // stays fully editable, unchanged from before.
  Future<void> _prefillAssignedSite() async {
    try {
      final uid = FirebaseAuth.instance.currentUser?.uid;
      if (uid == null) return;
      final query = await FirebaseFirestore.instance
          .collection('sites')
          .where('assignedSupervisorUid', isEqualTo: uid)
          .limit(1)
          .get();
      if (query.docs.isNotEmpty && mounted) {
        final doc = query.docs.first;
        setState(() {
          _selectedSiteId = doc.id;
          _selectedSiteName = doc.data()['name'] ?? '';
          _isSiteLocked = true;
          _assignedSiteId = doc.id;
        });
      }
    } catch (e) {
      // Non-critical convenience feature; ignore failures.
    }
  }

  Future<void> _startDay() async {
    if (_selectedMachineId == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please select a machine.')));
      return;
    }
    if (_selectedSiteId == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please select a site.')));
      return;
    }
    if (_startMeterController.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter start meter reading.')),
      );
      return;
    }
    // Defense-in-depth: the Site field is disabled in the UI whenever
    // _isSiteLocked is true, so this shouldn't be reachable in practice —
    // but don't rely solely on a disabled widget to enforce it.
    if (_isSiteLocked && _selectedSiteId != _assignedSiteId) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('You can only start a day at your assigned site.'),
        ),
      );
      return;
    }

    setState(() => _isLoading = true);

    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      // Check if the CURRENT supervisor already has an active session today
      // for this machine — supervisorUid is a required part of this match,
      // not just machineId/date/status. Root cause of a real production
      // permission-denied bug: without it, this query would match ANY
      // supervisor's active session on the machine (a shift handover, a
      // forgotten End Day, shared equipment), and whoever ran _startDay()
      // next would silently reuse someone else's daily_sessions doc —
      // every write after that fails the
      // resource.data.supervisorUid == request.auth.uid rule check,
      // because the doc's actual owner is a different uid.
      final existing = await FirebaseFirestore.instance
          .collection('daily_sessions')
          .where('machineId', isEqualTo: _selectedMachineId)
          .where(
            'supervisorUid',
            isEqualTo: FirebaseAuth.instance.currentUser!.uid,
          )
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      String sessionId;

      if (existing.docs.isNotEmpty) {
        // Resume existing session for today
        sessionId = existing.docs.first.id;
      } else {
        // Check if this SITE already has a verification code generated today
        // (any supervisor at this site should share the same code)
        final siteToday = await FirebaseFirestore.instance
            .collection('daily_sessions')
            .where('siteId', isEqualTo: _selectedSiteId)
            .where('date', isEqualTo: dateString)
            .limit(1)
            .get();

        String verificationCode;
        if (siteToday.docs.isNotEmpty &&
            siteToday.docs.first.data()['verificationCode'] != null) {
          // Reuse the existing code for this site today
          verificationCode = siteToday.docs.first.data()['verificationCode'];
        } else {
          // First session at this site today - generate a new code
          verificationCode = (1000 + Random().nextInt(9000)).toString();
        }

        // Create new daily session
        final docRef = await FirebaseFirestore.instance
            .collection('daily_sessions')
            .add({
              'supervisorUid': FirebaseAuth.instance.currentUser!.uid,
              'supervisorName': widget.name,
              'machineId': _selectedMachineId,
              'machineName': _selectedMachineName,
              'siteId': _selectedSiteId,
              'siteName': _selectedSiteName,
              'startMeter':
                  double.tryParse(_startMeterController.text.trim()) ?? 0,
              'endMeter': null,
              'date': dateString,
              'status': 'active',
              'verificationCode': verificationCode,
              'createdAt': FieldValue.serverTimestamp(),
            });
        sessionId = docRef.id;
      }

      if (mounted) {
        final sessionDoc = await FirebaseFirestore.instance
            .collection('daily_sessions')
            .doc(sessionId)
            .get();
        final code = sessionDoc.data()?['verificationCode'] as String?;

        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => WorkSessionScreen(
              sessionId: sessionId,
              machineName: _selectedMachineName ?? '',
              siteName: _selectedSiteName ?? '',
              siteId: _selectedSiteId ?? '',
              supervisorName: widget.name,
              verificationCode: code,
            ),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Error: $e')));
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  // Searchable site picker — only lets the supervisor pick an existing
  // registered site (unlike the Unloading Site Autocomplete elsewhere,
  // which allows free text). Sites missing the canBeLoadingSite field
  // entirely are treated as eligible, so pre-existing sites registered
  // before this field existed don't silently disappear from the list.
  Future<void> _showSiteSearchPicker() async {
    final selected = await showModalBottomSheet<Map<String, String>>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        String searchText = '';
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.75,
                child: Column(
                  children: [
                    const SizedBox(height: 12),
                    Container(
                      width: 40,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.grey[300],
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        autofocus: true,
                        decoration: InputDecoration(
                          hintText: 'Search site name',
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onChanged: (val) =>
                            setSheetState(() => searchText = val),
                      ),
                    ),
                    Expanded(
                      child: StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection('sites')
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }
                          final filtered = snapshot.data!.docs.where((doc) {
                            final data = doc.data() as Map<String, dynamic>;
                            if (data['canBeLoadingSite'] == false) return false;
                            final name = (data['name'] ?? '').toString();
                            return name.toLowerCase().contains(
                              searchText.toLowerCase(),
                            );
                          }).toList();
                          if (filtered.isEmpty) {
                            return const Center(
                              child: Text('No matching sites.'),
                            );
                          }
                          return ListView.builder(
                            itemCount: filtered.length,
                            itemBuilder: (context, index) {
                              final doc = filtered[index];
                              final data = doc.data() as Map<String, dynamic>;
                              return ListTile(
                                leading: const Icon(
                                  Icons.location_on,
                                  color: Colors.teal,
                                ),
                                title: Text(data['name'] ?? ''),
                                subtitle: Text(data['location'] ?? ''),
                                onTap: () => Navigator.pop(sheetContext, {
                                  'id': doc.id,
                                  'name': (data['name'] ?? '').toString(),
                                }),
                              );
                            },
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );

    if (selected != null) {
      setState(() {
        _selectedSiteId = selected['id'];
        _selectedSiteName = selected['name'];
      });
    }
  }

  @override
  Widget build(BuildContext context) {
    if (_checkingActiveSession) {
      return Scaffold(
        body: Container(
          decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
          child: const Center(
            child: CircularProgressIndicator(color: Colors.white),
          ),
        ),
      );
    }

    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'Welcome, ${widget.name}',
                      style: const TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(
                              builder: (_) => const LoginScreen(),
                            ),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: SingleChildScrollView(
                  padding: const EdgeInsets.all(16.0),
                  child: Center(
                    child: ConstrainedBox(
                      constraints: BoxConstraints(
                        maxWidth:
                            (kIsWeb && MediaQuery.of(context).size.width > 700)
                            ? 500
                            : double.infinity,
                      ),
                      child: GlassCard(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            _WebStaggeredFadeIn(
                              index: 0,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  const Text(
                                    'Select Machine',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      color: Colors.white,
                                    ),
                                  ),
                                  const SizedBox(height: 8),
                                  StreamBuilder<QuerySnapshot>(
                                    stream: FirebaseFirestore.instance
                                        .collection('machines')
                                        .snapshots(),
                                    builder: (context, snapshot) {
                                      if (!snapshot.hasData) {
                                        return const CircularProgressIndicator();
                                      }
                                      final machines = snapshot.data!.docs;
                                      return DropdownButtonFormField<String>(
                                        initialValue: _selectedMachineId,
                                        decoration: InputDecoration(
                                          hintText: 'Choose a machine',
                                          prefixIcon: const Icon(
                                            Icons.precision_manufacturing,
                                          ),
                                          border: OutlineInputBorder(
                                            borderRadius: BorderRadius.circular(
                                              12,
                                            ),
                                          ),
                                          filled: true,
                                          fillColor: Colors.white,
                                        ),
                                        items: machines.map((doc) {
                                          final data =
                                              doc.data()
                                                  as Map<String, dynamic>;
                                          return DropdownMenuItem<String>(
                                            value: doc.id,
                                            child: Text(
                                              '${data['name']} (${data['type']})',
                                            ),
                                          );
                                        }).toList(),
                                        onChanged: (val) {
                                          final selected = machines.firstWhere(
                                            (d) => d.id == val,
                                          );
                                          final data =
                                              selected.data()
                                                  as Map<String, dynamic>;
                                          setState(() {
                                            _selectedMachineId = val;
                                            _selectedMachineName = data['name'];
                                          });
                                        },
                                      );
                                    },
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(height: 20),
                            _WebStaggeredFadeIn(
                              index: 1,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  const Text(
                                    'Select Site',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      color: Colors.white,
                                    ),
                                  ),
                                  const SizedBox(height: 8),
                                  InkWell(
                                    borderRadius: BorderRadius.circular(12),
                                    onTap: _isSiteLocked
                                        ? null
                                        : _showSiteSearchPicker,
                                    child: InputDecorator(
                                      decoration: InputDecoration(
                                        prefixIcon: Icon(
                                          _isSiteLocked
                                              ? Icons.lock
                                              : Icons.location_on,
                                        ),
                                        border: OutlineInputBorder(
                                          borderRadius: BorderRadius.circular(
                                            12,
                                          ),
                                        ),
                                        filled: true,
                                        fillColor: _isSiteLocked
                                            ? Colors.grey[300]
                                            : Colors.white,
                                      ),
                                      child: Text(
                                        _selectedSiteName ?? 'Choose a site',
                                        style: TextStyle(
                                          color: _isSiteLocked
                                              ? Colors.grey[700]
                                              : (_selectedSiteName == null
                                                    ? Colors.grey[600]
                                                    : Colors.black87),
                                        ),
                                      ),
                                    ),
                                  ),
                                  if (_isSiteLocked) ...[
                                    const SizedBox(height: 4),
                                    Text(
                                      'This site is assigned to you by Admin',
                                      style: TextStyle(
                                        color: Colors.white.withOpacity(0.7),
                                        fontSize: 12,
                                      ),
                                    ),
                                  ],
                                ],
                              ),
                            ),
                            const SizedBox(height: 20),
                            _WebStaggeredFadeIn(
                              index: 2,
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  const Text(
                                    'Start Meter Reading',
                                    style: TextStyle(
                                      fontWeight: FontWeight.bold,
                                      color: Colors.white,
                                    ),
                                  ),
                                  const SizedBox(height: 8),
                                  TextField(
                                    controller: _startMeterController,
                                    keyboardType: TextInputType.number,
                                    decoration: InputDecoration(
                                      hintText: 'e.g. 1234.5',
                                      prefixIcon: const Icon(Icons.speed),
                                      border: OutlineInputBorder(
                                        borderRadius: BorderRadius.circular(12),
                                      ),
                                      filled: true,
                                      fillColor: Colors.white,
                                    ),
                                  ),
                                ],
                              ),
                            ),
                            const SizedBox(height: 32),
                            _WebStaggeredFadeIn(
                              index: 3,
                              child: _isLoading
                                  ? const CircularProgressIndicator(
                                      color: Colors.white,
                                    )
                                  : GradientButton(
                                      label: 'START DAY / CONTINUE',
                                      icon: Icons.play_arrow,
                                      onTap: _startDay,
                                    ),
                            ),
                          ],
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- WORK SESSION SCREEN ----------------
class WorkSessionScreen extends StatefulWidget {
  final String sessionId;
  final String machineName;
  final String siteName;
  final String siteId;
  final String supervisorName;
  final String? verificationCode;

  const WorkSessionScreen({
    super.key,
    required this.sessionId,
    required this.machineName,
    required this.siteName,
    required this.siteId,
    required this.supervisorName,
    this.verificationCode,
  });

  @override
  State<WorkSessionScreen> createState() => _WorkSessionScreenState();
}

class _WorkSessionScreenState extends State<WorkSessionScreen> {
  Timer? _tickTimer;

  final List<String> _loadingCategories = kLoadingCategories;
  final List<String> _otherCategories = kOtherCategories;

  // Prefers the site's own `sheetName` field (set via Manage Sites' rename
  // dialog) so a display-name rename never breaks which tab this site syncs
  // to. Falls back to kSiteSheetMap keyed by the site's CURRENT live name
  // (from siteData, freshly read by the caller) rather than widget.siteName,
  // since widget.siteName can be a stale snapshot from an existing
  // daily_sessions doc when this screen was reached via "resume active
  // session" instead of "start a new session".
  void _syncToSiteSpecificSheet(
    List<dynamic> row,
    String? recordId,
    Map<String, dynamic>? siteData,
  ) {
    final liveSiteName = (siteData?['name'] as String?) ?? widget.siteName;
    final sheetName =
        (siteData?['sheetName'] as String?) ??
        kSiteSheetMap[normalizeSiteNameForSheetLookup(liveSiteName)];
    if (sheetName != null) {
      GoogleSheetsService.sendRow(
        sheetName: sheetName,
        row: row,
        recordId: recordId,
      );
    }
  }

  @override
  void initState() {
    super.initState();
  }

  @override
  void dispose() {
    super.dispose();
  }

  CollectionReference get _recordsRef => FirebaseFirestore.instance
      .collection('daily_sessions')
      .doc(widget.sessionId)
      .collection('work_records');

  // Pause any currently running record in this session
  Future<void> _pauseRunningRecord() async {
    final runningSnap = await _recordsRef
        .where('status', isEqualTo: 'running')
        .get();

    for (final doc in runningSnap.docs) {
      final data = doc.data() as Map<String, dynamic>;
      final lastResumedAt = (data['lastResumedAt'] as Timestamp?)?.toDate();
      final currentTotal = (data['totalDurationSeconds'] ?? 0) as int;

      int addedSeconds = 0;
      if (lastResumedAt != null) {
        addedSeconds = DateTime.now().difference(lastResumedAt).inSeconds;
      }

      await doc.reference.update({
        'status': 'paused',
        'totalDurationSeconds': currentTotal + addedSeconds,
        'lastResumedAt': null,
      });
    }
  }

  // Resume a specific paused record (pauses whatever else is running first).
  // Its own call site (the RESUME button) fires this without await, same
  // as _startNewWork's callers used to — wrapped here so an exception
  // shows a SnackBar instead of silently doing nothing.
  Future<void> _resumeRecord(String recordId) async {
    try {
      await _pauseRunningRecord();
      await _recordsRef.doc(recordId).update({
        'status': 'running',
        'lastResumedAt': FieldValue.serverTimestamp(),
        // Resuming means the loading phase isn't over after all — without
        // this the card would show a frozen duration next to a RUNNING
        // badge (see _finishLoadingPhase and LiveTimerText.frozenDuration).
        'loadingFinishedAt': null,
      });
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Failed to resume task: $e'),
            backgroundColor: Colors.red,
          ),
        );
      }
    }
  }

  // Start a brand new work record
  // Returns the created record's DocumentReference — every current caller
  // (manual NewWorkDialog flow, QR Scan's _submitViaQrScan) just awaits
  // this and ignores the result; QR Scan used to need the id to chain
  // into _completeLoadingRecord immediately, but no longer does (see
  // _submitViaQrScan — it's left running for AutoArrivalDetectionService
  // to complete later). Kept returning DocumentReference regardless, since
  // it's harmless and a future caller may want it again.
  Future<DocumentReference> _startNewWork({
    required String category,
    required bool isLoadingCategory,
    String? truckNumber,
    String? billNumber,
    String? unloadingSiteName,
    double? distanceKm,
    String? truckDriverName,
    String? cubeCount,
    String? machineOperatorName,
    String loadType = 'company',
    // Superseded for Private Loads by completeImmediately below (GPS
    // return-path detection was replaced with manual entry — see
    // AutoArrivalDetectionService's doc comment on the now-disabled
    // private-load branch). Kept for Company Loads, whose existing
    // registered-site-arrival detection is unaffected by that change.
    bool? autoCompleteViaGps,
    // True only for a Private Load, both flows (see
    // _submitViaQrScan/_showNewWorkDialog's onSubmit) — a Private Load's
    // unloading location/KM are entered directly at creation time, so
    // there's nothing left to wait for; it's created already complete
    // instead of running. Every other record (any Company Load, or a
    // non-loading category) is unaffected — this only changes the fields
    // set below, nothing about who's allowed to call this method or how.
    bool completeImmediately = false,
  }) async {
    await _pauseRunningRecord();

    // Only the day's first Loading task inherits the day-level start meter;
    // meter tracking beyond that point happens at the day level (see
    // _showEndDayDialog), not per task.
    double? startMeter;
    if (isLoadingCategory) {
      final existingLoadingSnap = await _recordsRef
          .where('isLoadingCategory', isEqualTo: true)
          .limit(1)
          .get();
      if (existingLoadingSnap.docs.isEmpty) {
        final sessionDoc = await FirebaseFirestore.instance
            .collection('daily_sessions')
            .doc(widget.sessionId)
            .get();
        startMeter = (sessionDoc.data()?['startMeter'] as num?)?.toDouble();
      }
    }

    final today = DateTime.now();
    final dateString =
        "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

    return _recordsRef.add({
      'category': category,
      'isLoadingCategory': isLoadingCategory,
      'status': completeImmediately ? 'paused' : 'running',
      'totalDurationSeconds': 0,
      'lastResumedAt': completeImmediately
          ? null
          : FieldValue.serverTimestamp(),
      'truckNumber': truckNumber,
      'billNumber': billNumber,
      'unloadingSiteName': unloadingSiteName,
      'distanceKm': distanceKm,
      'startMeter': startMeter,
      'endMeter': null,
      'truckDriverName': truckDriverName,
      'cubeCount': cubeCount,
      'machineOperatorName': machineOperatorName,
      'loadType': loadType,
      if (autoCompleteViaGps != null) 'autoCompleteViaGps': autoCompleteViaGps,
      'loadStartedAt': isLoadingCategory ? FieldValue.serverTimestamp() : null,
      'loadCompletedAt': completeImmediately
          ? FieldValue.serverTimestamp()
          : null,
      'isCompleted': completeImmediately,
      if (completeImmediately) 'isVerified': true,
      'createdAt': FieldValue.serverTimestamp(),
      // Denormalized for ManagementSiteReportsScreen's flat
      // collectionGroup('work_records') query, so it doesn't need to fetch
      // each record's parent daily_sessions doc just to report on it.
      'date': dateString,
      'machineName': widget.machineName,
      'siteName': widget.siteName,
      'supervisorName': widget.supervisorName,
    });
  }

  // QR Scan flow: pushes the full-screen scanner, decodes the JSON payload
  // Vehicle Registration's QR Generate tab encodes ({"truckNumber",
  // "driverName", "cube"}), then opens the site-specific category picker.
  Future<void> _openQrScanner() async {
    final rawValue = await Navigator.push<String?>(
      context,
      MaterialPageRoute(builder: (_) => const _QrScannerScreen()),
    );
    if (rawValue == null || !mounted) return;

    Map<String, dynamic> qrData;
    try {
      qrData = jsonDecode(rawValue) as Map<String, dynamic>;
    } catch (e) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid QR code — not a recognized truck QR.'),
        ),
      );
      return;
    }

    final truckNumber = (qrData['truckNumber'] ?? '').toString();
    if (truckNumber.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Invalid QR code — missing truck number.'),
        ),
      );
      return;
    }
    // Driver/cube are looked up live from Firestore at scan time, not read
    // from the QR itself — the QR only ever encodes the truck number now
    // (see _QrGenerateTabState._generateQrCode), so a truck's printed QR
    // sticker never goes stale when its assigned driver or cube capacity
    // changes later.
    final truckSnap = await FirebaseFirestore.instance
        .collection('trucks')
        .where('truckNumber', isEqualTo: truckNumber)
        .limit(1)
        .get();
    if (!mounted) return;
    final truckData = truckSnap.docs.isNotEmpty
        ? truckSnap.docs.first.data()
        : null;
    final driverName = truckData?['assignedDriverName'] as String?;
    final cube = (truckData?['cubeCapacity'] as num?)?.toString();

    _showQrCategorySelectionDialog(
      truckNumber: truckNumber,
      driverName: driverName,
      cube: cube,
    );
  }

  // Reads availableCategories from the Supervisor's current working site
  // (widget.siteId — the same site this session/screen was started for, not
  // a re-picked one) and offers only those as completion categories, same
  // color-coded TaskButton grid the manual New Work flow uses.
  Future<void> _showQrCategorySelectionDialog({
    required String truckNumber,
    required String? driverName,
    required String? cube,
  }) async {
    final siteDoc = await FirebaseFirestore.instance
        .collection('sites')
        .doc(widget.siteId)
        .get();
    final availableCategories =
        (siteDoc.data()?['availableCategories'] as List<dynamic>?)
            ?.map((c) => c.toString())
            .where((c) => c.isNotEmpty)
            .toList() ??
        <String>[];
    // Auto-filled from the current working site's assigned operator (Site
    // Management's "Assigned Machine Operator") — left null (not blocked)
    // when the site has no operator assigned.
    final operatorName = siteDoc.data()?['assignedOperatorName'] as String?;

    if (!mounted) return;

    if (availableCategories.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${widget.siteName} has no Loading Categories configured yet — '
            'ask Admin to set them in Site Management.',
          ),
        ),
      );
      return;
    }

    showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Select Category to Complete Loading'),
        content: SizedBox(
          width: double.maxFinite,
          // shrinkWrap alone isn't enough — a site with many categories
          // selected could still overflow a short dialog on a small phone
          // screen, so this needs to be independently scrollable rather
          // than relying on the grid to size itself within an unbounded
          // height.
          child: SingleChildScrollView(
            child: GridView.builder(
              shrinkWrap: true,
              physics: const NeverScrollableScrollPhysics(),
              gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                crossAxisCount: 2,
                crossAxisSpacing: 12,
                mainAxisSpacing: 12,
                childAspectRatio: 1.3,
              ),
              itemCount: availableCategories.length,
              itemBuilder: (context, index) {
                final category = availableCategories[index];
                return TaskButton(
                  label: category,
                  onTap: () {
                    Navigator.pop(dialogContext);
                    _showQrBillNumberDialog(
                      truckNumber: truckNumber,
                      driverName: driverName,
                      cube: cube,
                      category: category,
                      operatorName: operatorName,
                    );
                  },
                );
              },
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
        ],
      ),
    );
  }

  // New step between category selection and submission. Number keyboard +
  // digits-only formatter matches NewWorkDialog's own required Bill Number
  // field — there's no actual uppercase-force pattern for Bill Number
  // anywhere in this codebase to reuse (that pattern exists for Truck
  // Number only); Bill Numbers are consistently treated as numeric-only
  // everywhere else already.
  void _showQrBillNumberDialog({
    required String truckNumber,
    required String? driverName,
    required String? cube,
    required String category,
    required String? operatorName,
  }) {
    final billNumberController = TextEditingController();
    String? errorText;
    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text('Enter Bill Number'),
          content: TextField(
            controller: billNumberController,
            autofocus: true,
            keyboardType: TextInputType.number,
            inputFormatters: [FilteringTextInputFormatter.digitsOnly],
            decoration: InputDecoration(
              labelText: 'Bill Number',
              border: const OutlineInputBorder(),
              errorText: errorText,
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () {
                final billNumber = billNumberController.text.trim();
                if (billNumber.isEmpty) {
                  setDialogState(() => errorText = 'Bill Number is required');
                  return;
                }
                Navigator.pop(dialogContext);
                _showQrLoadTypeDialog(
                  truckNumber: truckNumber,
                  driverName: driverName,
                  cube: cube,
                  category: category,
                  billNumber: billNumber,
                  operatorName: operatorName,
                );
              },
              child: const Text('SUBMIT'),
            ),
          ],
        ),
      ),
    );
  }

  // New step between the Bill Number dialog and submission. RadioListTile
  // pair/styling matches NewWorkDialog's own Load Type field exactly. A
  // Company Load still needs no unloading site here — that's the whole
  // point of AutoArrivalDetectionService's registered-site-proximity
  // auto-detection this flow already relies on (see _submitViaQrScan);
  // Private Load instead uses that service's return-path auto-detection.
  void _showQrLoadTypeDialog({
    required String truckNumber,
    required String? driverName,
    required String? cube,
    required String category,
    required String billNumber,
    required String? operatorName,
  }) {
    String selectedLoadType = 'company';
    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text('Load Type'),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Company Load'),
                value: 'company',
                groupValue: selectedLoadType,
                onChanged: (val) =>
                    setDialogState(() => selectedLoadType = val ?? 'company'),
              ),
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Private Load'),
                value: 'private',
                groupValue: selectedLoadType,
                onChanged: (val) =>
                    setDialogState(() => selectedLoadType = val ?? 'company'),
              ),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                Navigator.pop(dialogContext);
                if (selectedLoadType == 'company') {
                  // Pre-select the unloading site so
                  // AutoArrivalDetectionService's company-load branch can
                  // check that one specific site's siteGpsLocations()
                  // directly, instead of looping every registered site.
                  final selectedSite = await _showQrUnloadingSitePicker();
                  if (selectedSite == null) return;
                  _submitViaQrScan(
                    truckNumber: truckNumber,
                    driverName: driverName,
                    cube: cube,
                    category: category,
                    billNumber: billNumber,
                    operatorName: operatorName,
                    loadType: selectedLoadType,
                    unloadingSiteName: selectedSite,
                  );
                } else {
                  // Private Load — unloading location/KM entered manually
                  // next, and the record is created already complete (no
                  // GPS detection involved) — see
                  // _showQrPrivateLoadDetailsDialog/_submitViaQrScan.
                  _showQrPrivateLoadDetailsDialog(
                    truckNumber: truckNumber,
                    driverName: driverName,
                    cube: cube,
                    category: category,
                    billNumber: billNumber,
                    operatorName: operatorName,
                  );
                }
              },
              child: const Text('SUBMIT'),
            ),
          ],
        ),
      ),
    );
  }

  // New step for a Private Load, after Load Type — replaces GPS
  // return-path detection (see AutoArrivalDetectionService's now-disabled
  // private-load branch) with direct manual entry, same idea as the
  // manual New Work flow's Unloading Site/Distance fields, which already
  // work this way for every load type. No "pick from registered sites"
  // constraint here (unlike _showQrUnloadingSitePicker for Company Load)
  // since nothing needs to match this text against real site coordinates
  // anymore.
  void _showQrPrivateLoadDetailsDialog({
    required String truckNumber,
    required String? driverName,
    required String? cube,
    required String category,
    required String billNumber,
    required String? operatorName,
  }) {
    final unloadingLocationController = TextEditingController();
    final distanceController = TextEditingController();
    String? errorText;
    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
          ),
          title: const Text('Private Load Details'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                TextField(
                  controller: unloadingLocationController,
                  autofocus: true,
                  decoration: InputDecoration(
                    labelText: 'Unloading Location',
                    border: const OutlineInputBorder(),
                    errorText: errorText,
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: distanceController,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: const InputDecoration(
                    labelText: 'Distance (KM)',
                    border: OutlineInputBorder(),
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () {
                final location = unloadingLocationController.text.trim();
                if (location.isEmpty) {
                  setDialogState(
                    () => errorText = 'Unloading Location is required',
                  );
                  return;
                }
                Navigator.pop(dialogContext);
                _submitViaQrScan(
                  truckNumber: truckNumber,
                  driverName: driverName,
                  cube: cube,
                  category: category,
                  billNumber: billNumber,
                  operatorName: operatorName,
                  loadType: 'private',
                  unloadingSiteName: location,
                  distanceKm: double.tryParse(distanceController.text.trim()),
                );
              },
              child: const Text('SUBMIT'),
            ),
          ],
        ),
      ),
    );
  }

  // QR Scan flow only — unlike NewWorkDialog's _showUnloadingSitePicker,
  // this offers no "add as new site" option: a Company Load's
  // unloadingSiteName picked here must be a real registered site with GPS
  // coordinates, since AutoArrivalDetectionService's company-load branch
  // checks that specific site's siteGpsLocations() directly.
  Future<String?> _showQrUnloadingSitePicker() {
    return showModalBottomSheet<String?>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        String searchText = '';
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.75,
                child: Column(
                  children: [
                    const SizedBox(height: 12),
                    Container(
                      width: 40,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.grey[300],
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        autofocus: true,
                        decoration: InputDecoration(
                          hintText: 'Search unloading site',
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onChanged: (val) =>
                            setSheetState(() => searchText = val),
                      ),
                    ),
                    Expanded(
                      child: StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection('sites')
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }
                          final trimmedSearch = searchText.trim().toLowerCase();
                          final filtered = snapshot.data!.docs.where((doc) {
                            // Excludes the supervisor's own current loading
                            // site — selecting it as its own "unloading
                            // site" would make AutoArrivalDetectionService's
                            // 50m arrival check pass instantly (the truck
                            // starts right there), completing the load
                            // before it's actually gone anywhere. Sites
                            // default to canBeUnloadingSite: true, so
                            // without this the current site was always a
                            // selectable (and easy-to-tap-by-mistake) option
                            // here.
                            if (doc.id == widget.siteId) return false;
                            final data = doc.data() as Map<String, dynamic>;
                            // Defaults to true when absent — same
                            // convention as every other canBeUnloadingSite
                            // check in this codebase (see _addSite).
                            if (data['canBeUnloadingSite'] == false) {
                              return false;
                            }
                            final name = (data['name'] ?? '').toString();
                            return name.toLowerCase().contains(trimmedSearch);
                          }).toList();
                          if (filtered.isEmpty) {
                            return const Center(
                              child: Padding(
                                padding: EdgeInsets.all(24),
                                child: Text(
                                  'No matching registered unloading sites.',
                                  textAlign: TextAlign.center,
                                ),
                              ),
                            );
                          }
                          return ListView(
                            children: [
                              for (final doc in filtered)
                                ListTile(
                                  leading: const Icon(
                                    Icons.location_on,
                                    color: AppTheme.accent,
                                  ),
                                  title: Text(
                                    (doc.data()
                                            as Map<String, dynamic>)['name'] ??
                                        '',
                                  ),
                                  onTap: () => Navigator.pop(
                                    sheetContext,
                                    (doc.data() as Map<String, dynamic>)['name']
                                        as String?,
                                  ),
                                ),
                            ],
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }

  // Creates the work_records doc via the same _startNewWork every other
  // Loading task uses. Company Load's unloadingSiteName is pre-selected (see
  // _showQrLoadTypeDialog's site picker step) so AutoArrivalDetectionService
  // can check that one specific site's siteGpsLocations() directly, and
  // stays on the existing GPS-arrival-detection workflow
  // (autoCompleteViaGps: true). Private Load's unloading location/KM are
  // now entered manually (see _showQrPrivateLoadDetailsDialog) and the
  // record is created already complete — no GPS detection involved at all
  // (autoCompleteViaGps omitted; see _startNewWork's doc comment on
  // completeImmediately for the fuller picture, including the manual New
  // Work flow's own Private Load case).
  Future<void> _submitViaQrScan({
    required String truckNumber,
    required String? driverName,
    required String? cube,
    required String category,
    required String billNumber,
    required String? operatorName,
    required String loadType,
    required String unloadingSiteName,
    double? distanceKm,
  }) async {
    // Wrapped in try/catch on purpose — the caller (the Bill Number
    // dialog's SUBMIT button) closes its dialog and calls this without
    // awaiting it, so any exception thrown by _startNewWork used to become
    // an unhandled Future error: no SnackBar, no dialog, nothing — the
    // task just silently never got created. Same fix applied to
    // _showNewWorkDialog's onSubmit below, which had the identical gap.
    try {
      final isPrivate = loadType == 'private';
      final newDocRef = await _startNewWork(
        category: category,
        isLoadingCategory: true,
        truckNumber: truckNumber,
        billNumber: billNumber,
        unloadingSiteName: unloadingSiteName,
        distanceKm: distanceKm,
        truckDriverName: driverName,
        cubeCount: cube,
        machineOperatorName: operatorName,
        loadType: loadType,
        autoCompleteViaGps: isPrivate ? null : true,
        completeImmediately: isPrivate,
      );

      if (isPrivate) {
        final newDoc = await newDocRef.get();
        final newData = newDoc.data() as Map<String, dynamic>;
        await _syncCompletedRecordToSheets(newDocRef.id, newData, 0);
      }

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              isPrivate
                  ? 'Private load recorded via QR scan for Truck '
                        '$truckNumber — marked complete.'
                  : 'Load started via QR scan for Truck $truckNumber — '
                        'completion will be detected automatically via GPS.',
            ),
          ),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Failed to start load via QR scan: $e'),
            backgroundColor: Colors.red,
          ),
        );
      }
    }
  }

  // Complete a loading record. Meter readings are no longer taken per task -
  // endMeter stays null here and only gets filled in for the day's last
  // Loading task when the supervisor ends the day (see _showEndDayDialog).
  Future<void> _completeLoadingRecord(String recordId) async {
    try {
      final doc = await _recordsRef.doc(recordId).get();
      final data = doc.data() as Map<String, dynamic>;
      final lastResumedAt = (data['lastResumedAt'] as Timestamp?)?.toDate();
      final currentTotal = (data['totalDurationSeconds'] ?? 0) as int;

      int addedSeconds = 0;
      if (lastResumedAt != null) {
        addedSeconds = DateTime.now().difference(lastResumedAt).inSeconds;
      }
      final newTotal = currentTotal + addedSeconds;

      await _recordsRef.doc(recordId).update({
        'status': 'paused',
        'totalDurationSeconds': newTotal,
        'lastResumedAt': null,
        'endMeter': null,
        'loadCompletedAt': FieldValue.serverTimestamp(),
        'isCompleted': true,
      });

      final updatedDoc = await _recordsRef.doc(recordId).get();
      final updatedData = updatedDoc.data() as Map<String, dynamic>;
      await _syncCompletedRecordToSheets(recordId, updatedData, newTotal);
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to complete load: $e')));
      }
    }
  }

  // A Company Load's COMPLETE button ends only its *loading* phase — the
  // truck still has to reach the unloading site. So this stops the timer
  // and stamps loadingFinishedAt (which LiveTimerText then shows frozen),
  // and deliberately leaves isCompleted alone: AutoArrivalDetectionService's
  // GPS arrival check is the only thing that ever sets that true, and the
  // Sheets sync happens there too, once the load is genuinely delivered.
  Future<void> _finishLoadingPhase(String recordId) async {
    try {
      final doc = await _recordsRef.doc(recordId).get();
      final data = doc.data() as Map<String, dynamic>;
      final lastResumedAt = (data['lastResumedAt'] as Timestamp?)?.toDate();
      final currentTotal = (data['totalDurationSeconds'] ?? 0) as int;

      int addedSeconds = 0;
      if (lastResumedAt != null) {
        addedSeconds = DateTime.now().difference(lastResumedAt).inSeconds;
      }

      await _recordsRef.doc(recordId).update({
        'status': 'paused',
        'totalDurationSeconds': currentTotal + addedSeconds,
        'lastResumedAt': null,
        'loadingFinishedAt': FieldValue.serverTimestamp(),
      });
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to finish loading: $e')),
        );
      }
    }
  }

  // Shared by _completeLoadingRecord and the Private Load
  // immediate-completion paths in _submitViaQrScan/_showNewWorkDialog's
  // onSubmit — same 17-column Supervisor_Loads row shape,
  // Plant_Loads/site-specific-sheet follow-up.
  Future<void> _syncCompletedRecordToSheets(
    String recordId,
    Map<String, dynamic> data,
    int durationSeconds,
  ) async {
    final row = [
      GoogleSheetsService.formatDate(DateTime.now()),
      widget.machineName,
      widget.siteName,
      widget.supervisorName,
      data['category'] ?? '',
      data['truckNumber'] ?? '',
      data['billNumber'] ?? '',
      data['unloadingSiteName'] ?? '',
      data['distanceKm']?.toString() ?? '',
      data['startMeter']?.toString() ?? '',
      data['endMeter']?.toString() ?? '',
      _formatDuration(durationSeconds),
      GoogleSheetsService.formatTime(data['loadStartedAt']),
      GoogleSheetsService.formatTime(data['loadCompletedAt']),
      data['truckDriverName'] ?? '',
      data['cubeCount'] ?? '',
      data['machineOperatorName'] ?? '',
    ];

    GoogleSheetsService.sendRow(
      sheetName: 'Supervisor_Loads',
      row: row,
      recordId: recordId,
    );

    // Plant sites also get a copy of every completed load in a dedicated
    // sheet, in addition to the regular Supervisor_Loads log.
    final siteDoc = await FirebaseFirestore.instance
        .collection('sites')
        .doc(widget.siteId)
        .get();
    final isPlantSite = siteDoc.data()?['isPlantSite'] == true;
    if (isPlantSite) {
      GoogleSheetsService.sendRow(
        sheetName: 'Plant_Loads',
        row: row,
        recordId: recordId,
      );
    }

    // Independent of the Plant_Loads check above: some loading sites also
    // get their own dedicated sheet tab.
    _syncToSiteSpecificSheet(row, recordId, siteDoc.data());
  }

  int _liveElapsedSeconds(Map<String, dynamic> data) {
    final total = (data['totalDurationSeconds'] ?? 0) as int;
    if (data['status'] == 'running' && data['lastResumedAt'] != null) {
      final lastResumedAt = (data['lastResumedAt'] as Timestamp).toDate();
      final extra = DateTime.now().difference(lastResumedAt).inSeconds;
      return total + extra;
    }
    return total;
  }

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    final s = seconds % 60;
    return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  void _showNewWorkDialog() {
    showDialog(
      context: context,
      builder: (_) => NewWorkDialog(
        loadingCategories: _loadingCategories,
        otherCategories: _otherCategories,
        currentSiteId: widget.siteId,
        onSubmit:
            (
              category,
              truckNumber,
              billNumber,
              unloadingSiteName,
              distanceKm,
              startMeter,
              truckDriverName,
              cubeCount,
              machineOperatorName,
              loadType,
            ) async {
              Navigator.pop(context);
              // Same gap _submitViaQrScan had: this closure used to call
              // _startNewWork without await or a try/catch, so any
              // exception became an unhandled Future error — nothing
              // shown, task silently never created. This is the manual
              // (non-QR) New Work flow, so this bug predates and is
              // independent of today's QR changes.
              try {
                // Private Load: NewWorkDialog already requires Unloading
                // Site + Distance (KM) for every Loading task, so that
                // manually-entered data is all a Private Load needs —
                // create it already complete instead of running/waiting on
                // GPS detection. A Company Load instead stays open for
                // AutoArrivalDetectionService, exactly like the QR flow's
                // Company branch — its COMPLETE button only ends the
                // loading phase (_finishLoadingPhase), so GPS arrival is
                // the only thing that can mark it isCompleted.
                final isPrivate = loadType == 'private';
                // Temporary — traces exactly what this submission is about
                // to write, for the "Loading category completes instantly"
                // investigation. Remove once confirmed fixed.
                print(
                  '[NEWWORK_DEBUG] category=$category, loadType=$loadType, '
                  'isPrivate=$isPrivate, completeImmediately=$isPrivate, '
                  'isLoadingCategory='
                  '${_loadingCategories.contains(category)}',
                );
                final newDocRef = await _startNewWork(
                  category: category,
                  isLoadingCategory: _loadingCategories.contains(category),
                  truckNumber: truckNumber,
                  billNumber: billNumber,
                  unloadingSiteName: unloadingSiteName,
                  distanceKm: distanceKm,
                  truckDriverName: truckDriverName,
                  cubeCount: cubeCount,
                  machineOperatorName: machineOperatorName,
                  loadType: loadType,
                  completeImmediately: isPrivate,
                  autoCompleteViaGps: isPrivate ? null : true,
                );
                final newDoc = await newDocRef.get();
                final newData = newDoc.data() as Map<String, dynamic>;
                print(
                  '[NEWWORK_DEBUG] Created record ${newDocRef.id}: '
                  'isCompleted=${newData['isCompleted']}, '
                  'status=${newData['status']}, '
                  'loadType=${newData['loadType']}',
                );
                if (isPrivate) {
                  await _syncCompletedRecordToSheets(newDocRef.id, newData, 0);
                }
              } catch (e) {
                if (mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(
                      content: Text('Failed to start task: $e'),
                      backgroundColor: Colors.red,
                    ),
                  );
                }
              }
            },
      ),
    );
  }

  String _formatTime(Timestamp? ts) {
    if (ts == null) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  void _showEndDayDialog() {
    final endMeterController = TextEditingController();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('End Day'),
        content: TextField(
          controller: endMeterController,
          keyboardType: TextInputType.number,
          decoration: InputDecoration(
            labelText: 'End Meter Reading',
            border: OutlineInputBorder(borderRadius: BorderRadius.circular(12)),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              if (endMeterController.text.trim().isEmpty) return;
              try {
                await _pauseRunningRecord();
                final endMeterValue =
                    double.tryParse(endMeterController.text.trim()) ?? 0;

                await FirebaseFirestore.instance
                    .collection('daily_sessions')
                    .doc(widget.sessionId)
                    .update({
                      'endMeter': endMeterValue,
                      'status': 'completed',
                      'completedAt': FieldValue.serverTimestamp(),
                    });

                // Stamp the day's last Loading task with the same end meter.
                // No orderBy here on purpose: pairing it with the equality
                // filter above would require a composite Firestore index
                // that isn't provisioned for this project, which made this
                // query throw FAILED_PRECONDITION and abort the handler
                // before the dialog could close.
                final loadingSnap = await _recordsRef
                    .where('isLoadingCategory', isEqualTo: true)
                    .get();
                if (loadingSnap.docs.isNotEmpty) {
                  QueryDocumentSnapshot? lastLoadingDoc;
                  Timestamp? lastLoadingTime;
                  for (final candidate in loadingSnap.docs) {
                    final candidateTime =
                        (candidate.data() as Map<String, dynamic>)['createdAt']
                            as Timestamp?;
                    if (lastLoadingDoc == null) {
                      // First candidate always starts as the current pick.
                      lastLoadingDoc = candidate;
                      lastLoadingTime = candidateTime;
                    } else if (lastLoadingTime == null) {
                      // Current pick has no createdAt to compare against; any
                      // later candidate replaces it.
                      lastLoadingDoc = candidate;
                      lastLoadingTime = candidateTime;
                    } else if (candidateTime != null &&
                        candidateTime.compareTo(lastLoadingTime) > 0) {
                      // Strictly newer candidate replaces the current pick.
                      lastLoadingDoc = candidate;
                      lastLoadingTime = candidateTime;
                    }
                  }
                  await lastLoadingDoc!.reference.update({
                    'endMeter': endMeterValue,
                  });
                }

                // Day-end summary row — just the meter reading and when it
                // was taken, not a rebuild of any single task's full detail
                // row (those already went out when each task was
                // paused/completed). Column order matches the existing
                // 17-column Supervisor_Loads/Plant_Loads header; every slot
                // other than these six stays blank.
                final row = [
                  GoogleSheetsService.formatDate(DateTime.now()),
                  widget.machineName,
                  widget.siteName,
                  widget.supervisorName,
                  '',
                  '',
                  '',
                  '',
                  '',
                  '',
                  endMeterValue.toString(),
                  '',
                  '',
                  GoogleSheetsService.formatTime(Timestamp.now()),
                  '',
                  '',
                  '',
                ];

                GoogleSheetsService.sendRow(
                  sheetName: 'Supervisor_Loads',
                  row: row,
                );

                final siteDoc = await FirebaseFirestore.instance
                    .collection('sites')
                    .doc(widget.siteId)
                    .get();
                if (siteDoc.data()?['isPlantSite'] == true) {
                  GoogleSheetsService.sendRow(
                    sheetName: 'Plant_Loads',
                    row: row,
                  );
                }

                // Independent of the Plant_Loads check above: some loading
                // sites also get their own dedicated sheet tab. No recordId
                // here — this summary row doesn't correspond 1:1 with any
                // single existing Sheet row (see the comment above), so it
                // must always append, never overwrite.
                _syncToSiteSpecificSheet(row, null, siteDoc.data());

                if (context.mounted) {
                  // Close dialog and go back to supervisor home in one atomic
                  // call — two sequential pop()s on the same Navigator race
                  // with the first pop's in-flight rebuild and hit the
                  // '!_debugLocked' assertion.
                  Navigator.of(context).popUntil((route) => route.isFirst);
                }
              } catch (e) {
                if (context.mounted) {
                  ScaffoldMessenger.of(context).showSnackBar(
                    SnackBar(content: Text('Failed to end day: $e')),
                  );
                }
              }
            },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            child: const Text('END DAY', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final isWideWeb = kIsWeb && MediaQuery.of(context).size.width > 700;

    return Scaffold(
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () {
            if (Navigator.canPop(context)) {
              Navigator.pop(context);
            } else {
              Navigator.pushReplacement(
                context,
                MaterialPageRoute(
                  builder: (_) => SupervisorScreen(name: widget.supervisorName),
                ),
              );
            }
          },
        ),
        title: Text(widget.machineName),
        backgroundColor: Colors.orange[800],
        actions: [
          IconButton(
            icon: const Icon(Icons.qr_code_scanner),
            tooltip: 'QR Scan',
            onPressed: _openQrScanner,
          ),
          IconButton(
            icon: const Icon(Icons.history),
            onPressed: () {
              Navigator.push(
                context,
                MaterialPageRoute(
                  builder: (_) =>
                      SupervisorHistoryScreen(sessionId: widget.sessionId),
