                  );
                }

                final records = snapshot.data!.docs;

                final list = ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: records.length,
                  itemBuilder: (context, index) {
                    final doc = records[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final isRunning = data['status'] == 'running';
                    final elapsed = _liveElapsedSeconds(data);
                    // For a Company Load, COMPLETE means "loading phase
                    // finished" (stops the timer, stamps loadingFinishedAt)
                    // — not "delivered". Only AutoArrivalDetectionService's
                    // GPS arrival check ever sets isCompleted true.
                    final isCompanyLoadingTask =
                        data['isLoadingCategory'] == true &&
                        (data['loadType'] ?? 'company') == 'company';
                    final loadingFinishedAt =
                        (data['loadingFinishedAt'] as Timestamp?)?.toDate();
                    final loadStartedAt =
                        (data['loadStartedAt'] as Timestamp?)?.toDate();

                    return _WebStaggeredFadeIn(
                      index: index,
                      child: _WebHoverCard(
                        child: Card(
                          color: isRunning ? Colors.green[50] : Colors.white,
                          margin: const EdgeInsets.only(bottom: 10),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                            side: BorderSide(
                              color: isRunning
                                  ? Colors.green
                                  : Colors.grey[300]!,
                              width: isRunning ? 1.5 : 1,
                            ),
                          ),
                          child: Padding(
                            padding: const EdgeInsets.all(12),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  mainAxisAlignment:
                                      MainAxisAlignment.spaceBetween,
                                  children: [
                                    Text(
                                      data['category'] ?? '',
                                      style: const TextStyle(
                                        fontWeight: FontWeight.bold,
                                        fontSize: 16,
                                      ),
                                    ),
                                    Container(
                                      padding: const EdgeInsets.symmetric(
                                        horizontal: 8,
                                        vertical: 4,
                                      ),
                                      decoration: BoxDecoration(
                                        color: isRunning
                                            ? Colors.green
                                            : Colors.grey[400],
                                        borderRadius: BorderRadius.circular(20),
                                      ),
                                      child: Text(
                                        isRunning ? 'RUNNING' : 'PAUSED',
                                        style: const TextStyle(
                                          color: Colors.white,
                                          fontSize: 11,
                                        ),
                                      ),
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 6),
                                LiveTimerText(
                                  totalDurationSeconds:
                                      (data['totalDurationSeconds'] ?? 0)
                                          as int,
                                  isRunning: isRunning,
                                  lastResumedAt:
                                      (data['lastResumedAt'] as Timestamp?)
                                          ?.toDate(),
                                  frozenDuration:
                                      (loadingFinishedAt != null &&
                                          loadStartedAt != null)
                                      ? loadingFinishedAt.difference(
                                          loadStartedAt,
                                        )
                                      : null,
                                ),
                                if (data['truckNumber'] != null) ...[
                                  const SizedBox(height: 6),
                                  Text(
                                    'Truck: ${data['truckNumber']} • Bill: ${data['billNumber']}',
                                    style: const TextStyle(fontSize: 13),
                                  ),
                                  Text(
                                    'To: ${data['unloadingSiteName']} • ${data['distanceKm']} KM',
                                    style: const TextStyle(fontSize: 13),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    'Start Meter: ${data['startMeter'] ?? "-"}'
                                    '${data['isCompleted'] == true ? "  •  End Meter: ${data['endMeter'] ?? "-"}" : ""}',
                                    style: const TextStyle(fontSize: 13),
                                  ),
                                  if (data['isCompleted'] == true &&
                                      data['startMeter'] != null &&
                                      data['endMeter'] != null)
                                    Text(
                                      'Meter Run: ${((data['endMeter'] as num) - (data['startMeter'] as num)).toStringAsFixed(1)}',
                                      style: const TextStyle(
                                        fontSize: 13,
                                        fontWeight: FontWeight.bold,
                                        color: Colors.blue,
                                      ),
                                    ),
                                  Text(
                                    'Started: ${_formatTime(data['loadStartedAt'])}'
                                    '${data['loadCompletedAt'] != null ? "  •  Completed: ${_formatTime(data['loadCompletedAt'])}" : ""}',
                                    style: const TextStyle(
                                      fontSize: 12,
                                      color: Colors.grey,
                                    ),
                                  ),
                                ],
                                const SizedBox(height: 8),
                                if (data['isCompleted'] == true)
                                  Container(
                                    padding: const EdgeInsets.symmetric(
                                      vertical: 6,
                                    ),
                                    alignment: Alignment.center,
                                    decoration: BoxDecoration(
                                      color: Colors.blue[50],
                                      borderRadius: BorderRadius.circular(8),
                                    ),
                                    child: const Text(
                                      'LOAD COMPLETED',
                                      style: TextStyle(
                                        color: Colors.blue,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                                  )
                                else if (!isRunning)
                                  Row(
                                    children: [
                                      Expanded(
                                        child: OutlinedButton.icon(
                                          onPressed: () =>
                                              _resumeRecord(doc.id),
                                          icon: const Icon(Icons.play_arrow),
                                          label: const Text('RESUME'),
                                        ),
                                      ),
                                      if (data['isLoadingCategory'] ==
                                          true) ...[
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: ElevatedButton.icon(
                                            onPressed: () {
                                              if (isCompanyLoadingTask) {
                                                _finishLoadingPhase(doc.id);
                                              } else {
                                                _completeLoadingRecord(doc.id);
                                              }
                                            },
                                            icon: const Icon(
                                              Icons.check,
                                              color: Colors.white,
                                            ),
                                            label: const Text(
                                              'COMPLETE',
                                              style: TextStyle(
                                                color: Colors.white,
                                              ),
                                            ),
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor:
                                                  Colors.green[700],
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  )
                                else if (isRunning)
                                  Row(
                                    children: [
                                      Expanded(
                                        child: OutlinedButton.icon(
                                          onPressed: () =>
                                              _pauseRunningRecord(),
                                          icon: const Icon(Icons.pause),
                                          label: const Text('PAUSE'),
                                        ),
                                      ),
                                      if (data['isLoadingCategory'] ==
                                          true) ...[
                                        const SizedBox(width: 8),
                                        Expanded(
                                          child: ElevatedButton.icon(
                                            onPressed: () {
                                              if (isCompanyLoadingTask) {
                                                _finishLoadingPhase(doc.id);
                                              } else {
                                                _completeLoadingRecord(doc.id);
                                              }
                                            },
                                            icon: const Icon(
                                              Icons.check,
                                              color: Colors.white,
                                            ),
                                            label: const Text(
                                              'COMPLETE',
                                              style: TextStyle(
                                                color: Colors.white,
                                              ),
                                            ),
                                            style: ElevatedButton.styleFrom(
                                              backgroundColor:
                                                  Colors.green[700],
                                            ),
                                          ),
                                        ),
                                      ],
                                    ],
                                  ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                );

                if (!isWideWeb) return list;
                return Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 800),
                    child: list,
                  ),
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: isWideWeb
          ? null
          : FloatingActionButton.extended(
              onPressed: _showNewWorkDialog,
              backgroundColor: Colors.orange[800],
              icon: const Icon(Icons.add, color: Colors.white),
              label: const Text(
                'NEW WORK',
                style: TextStyle(color: Colors.white),
              ),
            ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _showEndDayDialog,
              icon: const Icon(Icons.flag, color: Colors.white),
              label: const Text(
                'END DAY',
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                ),
              ),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            ),
          ),
        ),
      ),
    );
  }
}

// ---------------- QR SCANNER SCREEN (WorkSessionScreen's QR Scan) ----------------
// Full-screen camera scanner. Works on both mobile and web — mobile_scanner
// uses the browser's camera API on web (kIsWeb) automatically, no separate
// codepath needed. Pops with the first successfully-decoded raw QR string,
// or null if the supervisor backs out without scanning anything.
class _QrScannerScreen extends StatefulWidget {
  const _QrScannerScreen();

  @override
  State<_QrScannerScreen> createState() => _QrScannerScreenState();
}

class _QrScannerScreenState extends State<_QrScannerScreen> {
  bool _handled = false;

  void _onDetect(BarcodeCapture capture) {
    if (_handled || capture.barcodes.isEmpty) return;
    final rawValue = capture.barcodes.first.rawValue;
    if (rawValue == null) return;
    _handled = true;
    Navigator.pop(context, rawValue);
  }

  // Without this, MobileScanner falls back to its own default error UI,
  // which for anything other than the few specifically-recognized native
  // error codes (permission denied, no camera, already started) just shows
  // "An unexpected error occurred." — MobileScannerException.errorDetails
  // carries the real underlying PlatformException code/message even in
  // that generic-error case, so this surfaces that instead, and gives a
  // way back out rather than leaving the supervisor stuck on a dead screen.
  String _describeError(MobileScannerException error) {
    switch (error.errorCode) {
      case MobileScannerErrorCode.permissionDenied:
        return 'Camera permission was denied. Please allow camera access '
            'for this app in your device settings and try again.';
      case MobileScannerErrorCode.unsupported:
        return 'No camera is available on this device.';
      default:
        final detail = error.errorDetails?.message;
        return 'Could not open the camera'
            '${detail != null && detail.isNotEmpty ? ': $detail' : '.'}';
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.black,
      appBar: AppBar(
        title: const Text('Scan Truck QR Code'),
        backgroundColor: Colors.black,
        foregroundColor: Colors.white,
      ),
      body: MobileScanner(
        onDetect: _onDetect,
        errorBuilder: (context, error) => Container(
          color: Colors.black,
          alignment: Alignment.center,
          padding: const EdgeInsets.all(24),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              const Icon(
                Icons.camera_alt_outlined,
                color: Colors.white54,
                size: 48,
              ),
              const SizedBox(height: 16),
              Text(
                _describeError(error),
                textAlign: TextAlign.center,
                style: const TextStyle(color: Colors.white),
              ),
              const SizedBox(height: 20),
              OutlinedButton(
                onPressed: () => Navigator.pop(context),
                style: OutlinedButton.styleFrom(
                  foregroundColor: Colors.white,
                  side: const BorderSide(color: Colors.white54),
                ),
                child: const Text('Go Back'),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- NEW WORK DIALOG ----------------
class NewWorkDialog extends StatefulWidget {
  final List<String> loadingCategories;
  final List<String> otherCategories;
  // The supervisor's current loading site (WorkSessionScreen's widget.siteId)
  // — excluded from _showUnloadingSitePicker's selectable list, same as
  // _showQrUnloadingSitePicker's fix for the QR flow: selecting it as its
  // own "unloading site" would make AutoArrivalDetectionService's 50m
  // arrival check pass instantly, completing the load before the truck has
  // actually gone anywhere.
  final String currentSiteId;
  final Function(
    String category,
    String? truckNumber,
    String? billNumber,
    String? unloadingSiteName,
    double? distanceKm,
    double? startMeter,
    String? truckDriverName,
    String? cubeCount,
    String? machineOperatorName,
    String loadType,
  )
  onSubmit;

  const NewWorkDialog({
    super.key,
    required this.loadingCategories,
    required this.otherCategories,
    required this.currentSiteId,
    required this.onSubmit,
  });

  @override
  State<NewWorkDialog> createState() => _NewWorkDialogState();
}

class _NewWorkDialogState extends State<NewWorkDialog> {
  String? _selectedCategory;
  String? _selectedUnloadingSiteId;
  String? _selectedUnloadingSiteName;
  String? _selectedTruckNumber;
  final _truckDriverController = TextEditingController();
  final _cubeController = TextEditingController();
  String? _selectedOperatorUid;
  String? _selectedOperatorName;
  final _billNumberController = TextEditingController();
  final _distanceController = TextEditingController();
  String _selectedLoadType = 'company';
  String _errorText = '';

  // Search-bottom-sheet pattern: typing a name with no exact match surfaces
  // a "use as new unloading site" option instead of restricting selection
  // to the registered list, so any supervisor can log a delivery to a site
  // that hasn't been registered yet.
  Future<void> _showUnloadingSitePicker() async {
    final selected = await showModalBottomSheet<Map<String, String?>>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        String searchText = '';
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.75,
                child: Column(
                  children: [
                    const SizedBox(height: 12),
                    Container(
                      width: 40,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.grey[300],
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        autofocus: true,
                        decoration: InputDecoration(
                          hintText: 'Search or type a new site name',
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onChanged: (val) {
                          debugPrint('[UNLOADPICKER] onChanged val="$val"');
                          setSheetState(() => searchText = val);
                        },
                      ),
                    ),
                    Expanded(
                      child: StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection('sites')
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }
                          debugPrint(
                            '[UNLOADPICKER_DEBUG] Total sites: ${snapshot.data!.docs.length}',
                          );
                          final trimmedSearch = searchText.trim();
                          final filtered = snapshot.data!.docs.where((doc) {
                            // Excludes the supervisor's own current loading
                            // site — see widget.currentSiteId's doc comment.
                            if (doc.id == widget.currentSiteId) return false;
                            final data = doc.data() as Map<String, dynamic>;
                            if (data['canBeUnloadingSite'] == false)
                              return false;
                            final name = (data['name'] ?? '').toString();
                            return name.toLowerCase().contains(
                              trimmedSearch.toLowerCase(),
                            );
                          }).toList();
                          debugPrint(
                            '[UNLOADPICKER_DEBUG] Filtered unloading sites: ${filtered.length}',
                          );
                          final hasExactMatch = filtered.any(
                            (doc) =>
                                ((doc.data() as Map<String, dynamic>)['name'] ??
                                        '')
                                    .toString()
                                    .toLowerCase() ==
                                trimmedSearch.toLowerCase(),
                          );
                          debugPrint(
                            '[UNLOADPICKER] build: searchText="$searchText" '
                            'trimmedSearch="$trimmedSearch" filtered=${filtered.length} '
                            'hasExactMatch=$hasExactMatch '
                            'showAddNew=${trimmedSearch.isNotEmpty && !hasExactMatch}',
                          );

                          return ListView(
                            children: [
                              if (trimmedSearch.isNotEmpty && !hasExactMatch)
                                ListTile(
                                  leading: const Icon(
                                    Icons.add_circle,
                                    color: AppTheme.accent,
                                  ),
                                  title: Text(
                                    "Use '$trimmedSearch' as new unloading site",
                                  ),
                                  onTap: () {
                                    debugPrint(
                                      '[UNLOADPICKER] add-new tapped, name="$trimmedSearch"',
                                    );
                                    Navigator.pop(sheetContext, {
                                      'id': null,
                                      'name': trimmedSearch,
                                    });
                                  },
                                ),
                              for (final doc in filtered)
                                Builder(
                                  builder: (context) {
                                    final data =
                                        doc.data() as Map<String, dynamic>;
                                    return ListTile(
                                      leading: const Icon(
                                        Icons.location_on,
                                        color: Colors.teal,
                                      ),
                                      title: Text(data['name'] ?? ''),
                                      subtitle: Text(data['location'] ?? ''),
                                      onTap: () => Navigator.pop(sheetContext, {
                                        'id': doc.id,
                                        'name': (data['name'] ?? '').toString(),
                                      }),
                                    );
                                  },
                                ),
                              if (filtered.isEmpty && trimmedSearch.isEmpty)
                                const Padding(
                                  padding: EdgeInsets.all(24),
                                  child: Text(
                                    'No sites yet — start typing to add one.',
                                  ),
                                ),
                            ],
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );

    debugPrint('[UNLOADPICKER] sheet closed, selected=$selected');
    if (selected != null) {
      setState(() {
        _selectedUnloadingSiteId = selected['id'];
        _selectedUnloadingSiteName = selected['name'];
      });
      debugPrint(
        '[UNLOADPICKER] set _selectedUnloadingSiteName=$_selectedUnloadingSiteName',
      );
    }
  }

  bool get _isLoadingCategory =>
      _selectedCategory != null &&
      widget.loadingCategories.contains(_selectedCategory);

  void _handleSubmit() {
    if (_selectedCategory == null) {
      setState(() => _errorText = 'Please select a work category.');
      return;
    }

    if (_isLoadingCategory) {
      if (_selectedTruckNumber == null ||
          _selectedTruckNumber!.trim().isEmpty) {
        setState(() => _errorText = 'Please select a truck.');
        return;
      }
      if (_billNumberController.text.trim().isEmpty) {
        setState(
          () => _errorText = 'Bill Number is required for loading work.',
        );
        return;
      }
      final unloadingSiteName = _selectedUnloadingSiteName?.trim();
      if (unloadingSiteName == null || unloadingSiteName.isEmpty) {
        setState(() => _errorText = 'Please select Unloading Site.');
        return;
      }
      if (_distanceController.text.trim().isEmpty) {
        setState(() => _errorText = 'Distance (KM) is required.');
        return;
      }

      widget.onSubmit(
        _selectedCategory!,
        _selectedTruckNumber!.trim(),
        _billNumberController.text.trim(),
        unloadingSiteName,
        double.tryParse(_distanceController.text.trim()),
        null,
        _truckDriverController.text.trim().isEmpty
            ? null
            : _truckDriverController.text.trim(),
        _cubeController.text.trim().isEmpty
            ? null
            : _cubeController.text.trim(),
        _selectedOperatorName,
        _selectedLoadType,
      );
    } else {
      widget.onSubmit(
        _selectedCategory!,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        null,
        'company',
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: const Text('Start New Work'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Work Category',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            DropdownButtonFormField<String>(
              initialValue: _selectedCategory,
              decoration: InputDecoration(
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
              items: [
                ...widget.loadingCategories.map(
                  (c) => DropdownMenuItem(value: c, child: Text('$c 🚛')),
                ),
                ...widget.otherCategories.map(
                  (c) => DropdownMenuItem(value: c, child: Text(c)),
                ),
              ],
              onChanged: (val) => setState(() {
                _selectedCategory = val;
                _errorText = '';
              }),
            ),
            if (_isLoadingCategory) ...[
              const SizedBox(height: 16),
              const Text(
                'Select Truck',
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
              ),
              const SizedBox(height: 8),
              StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                    .collection('trucks')
                    .snapshots(),
                builder: (context, snapshot) {
                  final Set<String> truckNumbers = {};
                  // Truck Number -> assigned driver name (set via Truck
                  // Profile's "Change Driver" dialog), used below to
                  // auto pre-fill Truck Driver Name when a truck is picked —
                  // pure convenience: that field stays fully editable so a
                  // substitute driver can still be typed over it.
                  final Map<String, String> assignedDriverByTruckNumber = {};
                  if (snapshot.hasData) {
                    for (final doc in snapshot.data!.docs) {
                      final data = doc.data() as Map<String, dynamic>;
                      final number = data['truckNumber'];
                      if (number != null && number.toString().isNotEmpty) {
                        truckNumbers.add(number.toString());
                        final driverName = data['assignedDriverName'];
                        if (driverName != null &&
                            driverName.toString().isNotEmpty) {
                          assignedDriverByTruckNumber[number.toString()] =
                              driverName.toString();
                        }
                      }
                    }
                  }
                  // Always overwrites Truck Driver Name (falling back to
                  // empty when the newly picked truck has no assigned
                  // driver) so switching trucks never leaves a stale name
                  // behind from whichever truck was selected before.
                  void applyTruckSelection(String truckNumber) {
                    setState(() {
                      _selectedTruckNumber = truckNumber;
                      _truckDriverController.text =
                          assignedDriverByTruckNumber[truckNumber] ?? '';
                    });
                  }

                  return Autocomplete<String>(
                    optionsBuilder: (textEditingValue) {
                      if (textEditingValue.text.isEmpty)
                        return const Iterable<String>.empty();
                      return truckNumbers.where(
                        (number) => number.toLowerCase().contains(
                          textEditingValue.text.toLowerCase(),
                        ),
                      );
                    },
                    onSelected: applyTruckSelection,
                    fieldViewBuilder:
                        (context, controller, focusNode, onSubmit) {
                          controller.text = _selectedTruckNumber ?? '';
                          return TextField(
                            controller: controller,
                            focusNode: focusNode,
                            onChanged: (val) {
                              // Also cover typing a truck's exact number
                              // out without tapping the suggestion —
                              // onSelected alone wouldn't fire then.
                              if (truckNumbers.contains(val)) {
                                applyTruckSelection(val);
                              } else {
                                _selectedTruckNumber = val;
                              }
                            },
                            decoration: InputDecoration(
                              hintText: 'Enter or choose truck number',
                              border: OutlineInputBorder(
                                borderRadius: BorderRadius.circular(10),
                              ),
                            ),
                          );
                        },
                  );
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _billNumberController,
                keyboardType: TextInputType.number,
                inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                decoration: InputDecoration(
                  labelText: 'Bill Number *',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Unloading Site *',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              const SizedBox(height: 8),
              InkWell(
                borderRadius: BorderRadius.circular(10),
                onTap: _showUnloadingSitePicker,
                child: InputDecorator(
                  decoration: InputDecoration(
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  child: Text(
                    _selectedUnloadingSiteName ??
                        'Search or type unloading site name',
                    style: TextStyle(
                      color: _selectedUnloadingSiteName == null
                          ? Colors.grey[600]
                          : Colors.black87,
                    ),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Load Type',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Company Load'),
                value: 'company',
                groupValue: _selectedLoadType,
                onChanged: (val) =>
                    setState(() => _selectedLoadType = val ?? 'company'),
              ),
              RadioListTile<String>(
                contentPadding: EdgeInsets.zero,
                dense: true,
                title: const Text('Private Load'),
                value: 'private',
                groupValue: _selectedLoadType,
                onChanged: (val) =>
                    setState(() => _selectedLoadType = val ?? 'company'),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _distanceController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: 'Distance (KM) *',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              FutureBuilder<QuerySnapshot>(
                future: FirebaseFirestore.instance
                    .collection('daily_sessions')
                    .doc('_dummy_')
                    .collection('work_records')
                    .limit(1)
                    .get(),
                builder: (context, _) {
                  return StreamBuilder<QuerySnapshot>(
                    stream: FirebaseFirestore.instance
                        .collectionGroup('work_records')
                        .where('truckDriverName', isNotEqualTo: null)
                        .limit(50)
                        .snapshots(),
                    builder: (context, snapshot) {
                      final Set<String> pastNames = {};
                      if (snapshot.hasData) {
                        for (final doc in snapshot.data!.docs) {
                          final data = doc.data() as Map<String, dynamic>;
                          final name = data['truckDriverName'];
                          if (name != null && name.toString().isNotEmpty) {
                            pastNames.add(name.toString());
                          }
                        }
                      }
                      return Autocomplete<String>(
                        optionsBuilder: (textEditingValue) {
                          if (textEditingValue.text.isEmpty)
                            return const Iterable<String>.empty();
                          return pastNames.where(
                            (name) => name.toLowerCase().contains(
                              textEditingValue.text.toLowerCase(),
                            ),
                          );
                        },
                        onSelected: (selection) {
                          _truckDriverController.text = selection;
                        },
                        fieldViewBuilder:
                            (context, controller, focusNode, onSubmit) {
                              controller.text = _truckDriverController.text;
                              return TextField(
                                controller: controller,
                                focusNode: focusNode,
                                onChanged: (val) =>
                                    _truckDriverController.text = val,
                                decoration: InputDecoration(
                                  labelText: 'Truck Driver Name',
                                  border: OutlineInputBorder(
                                    borderRadius: BorderRadius.circular(10),
                                  ),
                                ),
                              );
                            },
                      );
                    },
                  );
                },
              ),
              const SizedBox(height: 12),
              TextField(
                controller: _cubeController,
                keyboardType: TextInputType.number,
                decoration: InputDecoration(
                  labelText: 'Cube (Quantity)',
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(10),
                  ),
                ),
              ),
              const SizedBox(height: 12),
              const Text(
                'Machine Operator',
                style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
              ),
              const SizedBox(height: 8),
              StreamBuilder<QuerySnapshot>(
                stream: FirebaseFirestore.instance
                    .collection('users')
                    .where('canOperateMachine', isEqualTo: true)
                    .snapshots(),
                builder: (context, snapshot) {
                  if (!snapshot.hasData)
                    return const CircularProgressIndicator();
                  final operators = snapshot.data!.docs;
                  if (operators.isEmpty) {
                    return const Text(
                      'No operators registered.',
                      style: TextStyle(color: Colors.grey, fontSize: 12),
                    );
                  }
                  return DropdownButtonFormField<String>(
                    initialValue: _selectedOperatorUid,
                    decoration: InputDecoration(
                      hintText: 'Choose operator',
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(10),
                      ),
                    ),
                    items: operators.map((doc) {
                      final data = doc.data() as Map<String, dynamic>;
                      return DropdownMenuItem<String>(
                        value: doc.id,
                        child: Text(data['name'] ?? ''),
                      );
                    }).toList(),
                    onChanged: (val) {
                      final selected = operators.firstWhere((d) => d.id == val);
                      final data = selected.data() as Map<String, dynamic>;
                      setState(() {
                        _selectedOperatorUid = val;
                        _selectedOperatorName = data['name'];
                      });
                    },
                  );
                },
              ),
            ],
            if (_errorText.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text(
                _errorText,
                style: const TextStyle(color: Colors.red, fontSize: 13),
              ),
            ],
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: _handleSubmit,
          style: ElevatedButton.styleFrom(backgroundColor: Colors.orange[800]),
          child: const Text('START', style: TextStyle(color: Colors.white)),
        ),
      ],
    );
  }
}

// ---------------- LIVE TIMER TEXT (isolated rebuild) ----------------
class LiveTimerText extends StatefulWidget {
  final int totalDurationSeconds;
  final bool isRunning;
  final DateTime? lastResumedAt;

  // Set once a Company Load's loading phase is finished
  // (loadingFinishedAt - loadStartedAt): displayed as-is, with no ticking,
  // in place of the accumulated running total.
  final Duration? frozenDuration;

  const LiveTimerText({
    super.key,
    required this.totalDurationSeconds,
    required this.isRunning,
    required this.lastResumedAt,
    this.frozenDuration,
  });

  @override
  State<LiveTimerText> createState() => _LiveTimerTextState();
}

class _LiveTimerTextState extends State<LiveTimerText> {
  Timer? _timer;

  @override
  void initState() {
    super.initState();
    if (widget.isRunning && widget.frozenDuration == null) {
      _timer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void didUpdateWidget(covariant LiveTimerText oldWidget) {
    super.didUpdateWidget(oldWidget);
    _timer?.cancel();
    if (widget.isRunning && widget.frozenDuration == null) {
      _timer = Timer.periodic(const Duration(seconds: 1), (_) {
        if (mounted) setState(() {});
      });
    }
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  String _formatDuration(int seconds) {
    final h = seconds ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    final s = seconds % 60;
    return '${h.toString().padLeft(2, '0')}:${m.toString().padLeft(2, '0')}:${s.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final frozen = widget.frozenDuration;
    int elapsed = frozen?.inSeconds ?? widget.totalDurationSeconds;
    if (frozen == null && widget.isRunning && widget.lastResumedAt != null) {
      elapsed += DateTime.now().difference(widget.lastResumedAt!).inSeconds;
    }

    return Text(
      _formatDuration(elapsed),
      style: const TextStyle(
        fontSize: 22,
        fontWeight: FontWeight.bold,
        fontFamily: 'monospace',
      ),
    );
  }
}

// ---------------- DRIVER: TYPE SELECT (Trucks / Machines) ----------------
class DriverTypeScreen extends StatefulWidget {
  final String name;
  const DriverTypeScreen({super.key, required this.name});

  @override
  State<DriverTypeScreen> createState() => _DriverTypeScreenState();
}

class _DriverTypeScreenState extends State<DriverTypeScreen> {
  bool _checkingActiveSession = true;

  @override
  void initState() {
    super.initState();
    _checkForActiveSession();
  }

  Future<void> _checkForActiveSession() async {
    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      final existing = await FirebaseFirestore.instance
          .collection('driver_sessions')
          .where('driverUid', isEqualTo: FirebaseAuth.instance.currentUser!.uid)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      if (existing.docs.isNotEmpty && mounted) {
        final data = existing.docs.first.data();
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (_) => DriverWorkAreaScreen(
              sessionId: existing.docs.first.id,
              machineName: data['machineName'] ?? '',
              machineType: data['machineType'] ?? '',
              siteName: data['siteName'] ?? '',
              driverName: widget.name,
            ),
          ),
        );
        return;
      }
    } catch (e) {
      // Offline or error — fall through to normal selection screen
    }
    if (mounted) setState(() => _checkingActiveSession = false);
  }

  @override
  Widget build(BuildContext context) {
    if (_checkingActiveSession) {
      return Scaffold(
        body: Container(
          decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
          child: const Center(
            child: CircularProgressIndicator(color: Colors.white),
          ),
        ),
      );
    }

    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      'Welcome, ${widget.name}',
                      style: const TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(
                              builder: (_) => const LoginScreen(),
                            ),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Text(
                        'What are you operating today?',
                        style: TextStyle(
                          fontSize: 15,
                          color: Colors.white.withOpacity(0.8),
                        ),
                      ),
                      const SizedBox(height: 20),
                      GradientButton(
                        label: '1. Trucks',
                        icon: Icons.local_shipping,
                        height: 90,
                        onTap: () {
                          Navigator.push(
