// Same purpose/shape as _GarageNotificationsTab — every item (any category)
// at or below its own lowStockThreshold, worst-first. A collectionGroup
// isn't needed since warehouse_items is already a flat top-level
// collection; unlike Garage's per-truck GPS fetch this is a single
// Firestore query with no external API calls.
class _WarehouseNotificationsTab extends StatelessWidget {
  const _WarehouseNotificationsTab();

  @override
  Widget build(BuildContext context) {
    return StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
      stream: FirebaseFirestore.instance
          .collection(kWarehouseItemsCollection)
          .snapshots(),
      builder: (context, snapshot) {
        if (snapshot.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }
        if (snapshot.hasError) {
          return Center(child: Text('Failed to load: ${snapshot.error}'));
        }
        final lowItems =
            (snapshot.data?.docs ?? []).where((doc) {
                final data = doc.data();
                final currentQuantity =
                    (data['currentQuantity'] as num?)?.toDouble() ?? 0;
                final lowStockThreshold =
                    (data['lowStockThreshold'] as num?)?.toDouble() ?? 0;
                return currentQuantity <= lowStockThreshold;
              }).toList()
              ..sort((a, b) {
                final aRemaining =
                    (a.data()['currentQuantity'] as num?)?.toDouble() ?? 0;
                final bRemaining =
                    (b.data()['currentQuantity'] as num?)?.toDouble() ?? 0;
                return aRemaining.compareTo(bRemaining);
              });
        if (lowItems.isEmpty) {
          return const Center(
            child: Text(
              'No low-stock items.',
              style: TextStyle(color: Colors.grey),
            ),
          );
        }
        return ListView.builder(
          padding: const EdgeInsets.all(12),
          itemCount: lowItems.length,
          itemBuilder: (context, index) {
            final data = lowItems[index].data();
            final currentQuantity =
                (data['currentQuantity'] as num?)?.toDouble() ?? 0;
            final unit = (data['unit'] ?? '').toString();
            return Card(
              color: Colors.red[50],
              margin: const EdgeInsets.only(bottom: 10),
              child: ListTile(
                leading: const Icon(
                  Icons.warning_amber_rounded,
                  color: Colors.red,
                ),
                title: Text(
                  (data['itemName'] ?? '').toString(),
                  style: const TextStyle(fontWeight: FontWeight.bold),
                ),
                subtitle: Text(
                  '${warehouseCategoryLabel((data['category'] ?? '').toString())} — '
                  'Low Stock: ${currentQuantity.toStringAsFixed(1)} $unit remaining',
                  style: const TextStyle(color: Colors.red),
                ),
              ),
            );
          },
        );
      },
    );
  }
}

// ---------------- GPS DEVICE MANAGEMENT SCREEN (web-only) ----------------
// Native NODA-styled complement to Traccar's own web console: a quick-link
// button out to the real console for anything this screen doesn't cover,
// a registered-devices list cross-referenced against trucks/{id}.gpsDeviceId
// so it's obvious at a glance which devices are actually assigned, and a
// truck-wise KM history panel (Total + last 30 days) built on
// TraccarService.fetchDistanceSummary.
class GpsDeviceManagementScreen extends StatefulWidget {
  const GpsDeviceManagementScreen({super.key});

  @override
  State<GpsDeviceManagementScreen> createState() =>
      _GpsDeviceManagementScreenState();
}

class _GpsDeviceManagementScreenState extends State<GpsDeviceManagementScreen> {
  static const String _traccarUsername = 'pabodamilan.rpm@gmail.com';
  static const String _traccarPassword = 'Pa@20010707';

  late final Future<List<Map<String, dynamic>>> _devicesFuture;
  String? _selectedTruckId;
  String? _selectedTruckNumber;
  String? _selectedGpsDeviceId;

  @override
  void initState() {
    super.initState();
    _devicesFuture = TraccarService.fetchDevices(
      username: _traccarUsername,
      password: _traccarPassword,
    );
  }

  Future<void> _openTraccarConsole() async {
    final launched = await launchUrl(
      Uri.parse(TraccarService.baseUrl),
      mode: LaunchMode.externalApplication,
    );
    if (!launched && mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Could not open Traccar Console.')),
      );
    }
  }

  String _formatLastUpdate(String? iso) {
    if (iso == null) return 'Never';
    final dt = DateTime.tryParse(iso);
    if (dt == null) return 'Unknown';
    final local = dt.toLocal();
    final hour = local.hour % 12 == 0 ? 12 : local.hour % 12;
    final period = local.hour >= 12 ? 'PM' : 'AM';
    final minute = local.minute.toString().padLeft(2, '0');
    return '${local.year}-${local.month.toString().padLeft(2, '0')}-${local.day.toString().padLeft(2, '0')} '
        '$hour:$minute $period';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('GPS Devices'),
        backgroundColor: AppTheme.primaryDark,
        foregroundColor: Colors.white,
      ),
      body: StreamBuilder<QuerySnapshot>(
        stream: FirebaseFirestore.instance.collection('trucks').snapshots(),
        builder: (context, truckSnap) {
          final truckDocs = truckSnap.data?.docs ?? [];
          // deviceId (Identifier) -> truck number, for the "Assigned to"
          // badge in the devices list below.
          final assignedTruckByDeviceId = <String, String>{};
          // Trucks that actually have a GPS Device ID set — these are the
          // only ones offered in the KM History truck selector.
          final trucksWithGps = <QueryDocumentSnapshot>[];
          for (final doc in truckDocs) {
            final data = doc.data() as Map<String, dynamic>;
            final gpsDeviceId = (data['gpsDeviceId'] as String?)?.trim();
            if (gpsDeviceId != null && gpsDeviceId.isNotEmpty) {
              assignedTruckByDeviceId[gpsDeviceId] = (data['truckNumber'] ?? '')
                  .toString();
              trucksWithGps.add(doc);
            }
          }

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.all(16),
                child: SizedBox(
                  width: double.infinity,
                  height: 52,
                  child: DecoratedBox(
                    decoration: BoxDecoration(
                      gradient: AppTheme.cardGradient,
                      borderRadius: BorderRadius.circular(12),
                    ),
                    child: ElevatedButton.icon(
                      onPressed: _openTraccarConsole,
                      icon: const Icon(Icons.open_in_new, color: Colors.white),
                      label: const Text(
                        'Open Traccar Console',
                        style: TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                      style: ElevatedButton.styleFrom(
                        backgroundColor: Colors.transparent,
                        shadowColor: Colors.transparent,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
              const Padding(
                padding: EdgeInsets.symmetric(horizontal: 16),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    'Registered Devices',
                    style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
                  ),
                ),
              ),
              SizedBox(
                height: 220,
                child: FutureBuilder<List<Map<String, dynamic>>>(
                  future: _devicesFuture,
                  builder: (context, deviceSnap) {
                    if (deviceSnap.connectionState == ConnectionState.waiting) {
                      return const Center(child: CircularProgressIndicator());
                    }
                    if (deviceSnap.hasError) {
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(16),
                          child: Text(
                            'Failed to load devices from Traccar: '
                            '${deviceSnap.error}',
                            textAlign: TextAlign.center,
                          ),
                        ),
                      );
                    }
                    final devices = deviceSnap.data ?? [];
                    if (devices.isEmpty) {
                      return const Center(
                        child: Text('No devices registered on Traccar.'),
                      );
                    }
                    return ListView.builder(
                      scrollDirection: Axis.horizontal,
                      padding: const EdgeInsets.all(16),
                      itemCount: devices.length,
                      itemBuilder: (context, index) {
                        final device = devices[index];
                        final uniqueId = (device['uniqueId'] ?? '').toString();
                        final assignedTruck = assignedTruckByDeviceId[uniqueId];
                        return Container(
                          width: 220,
                          margin: const EdgeInsets.only(right: 12),
                          child: Card(
                            child: Padding(
                              padding: const EdgeInsets.all(12),
                              child: Column(
                                crossAxisAlignment: CrossAxisAlignment.start,
                                children: [
                                  Text(
                                    (device['name'] ?? '').toString(),
                                    style: const TextStyle(
                                      fontWeight: FontWeight.bold,
                                    ),
                                    overflow: TextOverflow.ellipsis,
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    'ID: $uniqueId',
                                    style: TextStyle(
                                      fontSize: 12,
                                      color: Colors.grey[700],
                                    ),
                                  ),
                                  const SizedBox(height: 4),
                                  Text(
                                    'Last Update: '
                                    '${_formatLastUpdate(device['lastUpdate'] as String?)}',
                                    style: TextStyle(
                                      fontSize: 11,
                                      color: Colors.grey[600],
                                    ),
                                  ),
                                  const Spacer(),
                                  Align(
                                    alignment: Alignment.centerLeft,
                                    child: Container(
                                      padding: const EdgeInsets.symmetric(
                                        horizontal: 8,
                                        vertical: 4,
                                      ),
                                      decoration: BoxDecoration(
                                        color: assignedTruck == null
                                            ? Colors.grey[300]
                                            : Colors.green[100],
                                        borderRadius: BorderRadius.circular(8),
                                      ),
                                      child: Text(
                                        assignedTruck == null
                                            ? 'Unassigned'
                                            : 'Assigned to: $assignedTruck',
                                        style: TextStyle(
                                          fontSize: 11,
                                          fontWeight: FontWeight.bold,
                                          color: assignedTruck == null
                                              ? Colors.grey[700]
                                              : Colors.green[800],
                                        ),
                                      ),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
              const Divider(height: 1),
              const Padding(
                padding: EdgeInsets.all(16),
                child: Align(
                  alignment: Alignment.centerLeft,
                  child: Text(
                    'Truck-wise KM History',
                    style: TextStyle(fontWeight: FontWeight.bold, fontSize: 15),
                  ),
                ),
              ),
              Expanded(
                child: Builder(
                  builder: (context) {
                    // Same breakpoint WebAppShell/Garage already use — see
                    // _GarageTrucksTabState's doc comment for the full
                    // reasoning. Wide keeps this screen's existing
                    // side-by-side Row; narrow pushes a full-screen detail
                    // route instead of squeezing the KM history panel into
                    // whatever's left after a fixed-width sidebar.
                    final isWide =
                        MediaQuery.of(context).size.width >
                        WebAppShell.desktopBreakpoint;

                    final truckList = trucksWithGps.isEmpty
                        ? const Padding(
                            padding: EdgeInsets.all(16),
                            child: Text(
                              'No trucks have a GPS Device ID set yet — '
                              'set one in Truck Profile.',
                              style: TextStyle(fontSize: 12),
                            ),
                          )
                        : ListView.builder(
                            itemCount: trucksWithGps.length,
                            itemBuilder: (context, index) {
                              final doc = trucksWithGps[index];
                              final data =
                                  doc.data() as Map<String, dynamic>;
                              final truckNumber =
                                  (data['truckNumber'] ?? '').toString();
                              final gpsDeviceId =
                                  (data['gpsDeviceId'] as String?)?.trim() ??
                                  '';
                              final isSelected =
                                  isWide && doc.id == _selectedTruckId;
                              return ListTile(
                                selected: isSelected,
                                selectedTileColor: AppTheme.primaryMid
                                    .withOpacity(0.08),
                                leading: const Icon(Icons.local_shipping),
                                title: Text(truckNumber),
                                subtitle: Text(gpsDeviceId),
                                onTap: () {
                                  if (isWide) {
                                    setState(() {
                                      _selectedTruckId = doc.id;
                                      _selectedTruckNumber = truckNumber;
                                      _selectedGpsDeviceId = gpsDeviceId;
                                    });
                                  } else {
                                    Navigator.push(
                                      context,
                                      MaterialPageRoute(
                                        builder: (_) => _GpsKmHistoryScreen(
                                          truckNumber: truckNumber,
                                          gpsDeviceId: gpsDeviceId,
                                          devicesFuture: _devicesFuture,
                                          username: _traccarUsername,
                                          password: _traccarPassword,
                                        ),
                                      ),
                                    );
                                  }
                                },
                              );
                            },
                          );

                    if (!isWide) return truckList;

                    return Row(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        SizedBox(width: 260, child: truckList),
                        const VerticalDivider(width: 1),
                        Expanded(
                          child: _selectedGpsDeviceId == null
                              ? const Center(
                                  child: Text(
                                    'Select a truck to view KM history.',
                                  ),
                                )
                              : _ResolvedKmHistoryPanel(
                                  truckNumber: _selectedTruckNumber!,
                                  gpsDeviceId: _selectedGpsDeviceId!,
                                  devicesFuture: _devicesFuture,
                                  username: _traccarUsername,
                                  password: _traccarPassword,
                                ),
                        ),
                      ],
                    );
                  },
                ),
              ),
            ],
          );
        },
      ),
    );
  }
}

// Resolves a truck's gpsDeviceId (trucks/{id}.gpsDeviceId, a Traccar
// uniqueId string) to Traccar's numeric device id and renders _KmHistoryPanel
// — shared between GpsDeviceManagementScreen's desktop Expanded panel and
// _GpsKmHistoryScreen's mobile full-screen route below, so the two layouts
// can't drift apart. Takes devicesFuture rather than fetching its own, so
// both call sites share the one /api/devices call already in flight.
class _ResolvedKmHistoryPanel extends StatelessWidget {
  final String truckNumber;
  final String gpsDeviceId;
  final Future<List<Map<String, dynamic>>> devicesFuture;
  final String username;
  final String password;

  const _ResolvedKmHistoryPanel({
    required this.truckNumber,
    required this.gpsDeviceId,
    required this.devicesFuture,
    required this.username,
    required this.password,
  });

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<List<Map<String, dynamic>>>(
      future: devicesFuture,
      builder: (context, deviceSnap) {
        if (deviceSnap.connectionState == ConnectionState.waiting) {
          return const Center(child: CircularProgressIndicator());
        }
        final devices = deviceSnap.data ?? [];
        final matchedDevice = devices.cast<Map<String, dynamic>?>().firstWhere(
          (d) => (d?['uniqueId'] ?? '').toString() == gpsDeviceId,
          orElse: () => null,
        );
        final numericDeviceId = (matchedDevice?['id'] as num?)?.toInt();
        if (numericDeviceId == null) {
          return Center(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Text(
                'No matching Traccar device found for GPS Device ID '
                '"$gpsDeviceId".',
                textAlign: TextAlign.center,
              ),
            ),
          );
        }
        return _KmHistoryPanel(
          key: ValueKey(numericDeviceId),
          truckNumber: truckNumber,
          deviceId: numericDeviceId,
          username: username,
          password: password,
        );
      },
    );
  }
}

// Full-screen KM history route for narrow (< WebAppShell.desktopBreakpoint)
