// ---------------- TRUCK: SELECT TRUCK ----------------
class TruckTypeScreen extends StatelessWidget {
  final String name;
  const TruckTypeScreen({super.key, required this.name});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    const Text(
                      'Select Truck',
                      style: TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                    IconButton(
                      icon: const Icon(Icons.logout, color: Colors.white),
                      onPressed: () async {
                        await FirebaseAuth.instance.signOut();
                        if (context.mounted) {
                          Navigator.pushReplacement(
                            context,
                            MaterialPageRoute(
                              builder: (_) => const LoginScreen(),
                            ),
                          );
                        }
                      },
                    ),
                  ],
                ),
              ),
              Expanded(
                child: StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('trucks')
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Center(
                        child: CircularProgressIndicator(color: Colors.white),
                      );
                    }
                    final trucks = snapshot.data!.docs;
                    if (trucks.isEmpty) {
                      return const Center(
                        child: Text(
                          'No trucks registered yet. Contact Admin.',
                          style: TextStyle(color: Colors.white),
                        ),
                      );
                    }

                    return ListView.builder(
                      padding: const EdgeInsets.all(16),
                      itemCount: trucks.length,
                      itemBuilder: (context, index) {
                        final data =
                            trucks[index].data() as Map<String, dynamic>;
                        return Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: DashboardMenuCard(
                            icon: Icons.local_shipping,
                            title: data['truckNumber'] ?? '',
                            subtitle: 'Tap to select this truck',
                            color: Colors.deepOrange,
                            onTap: () async {
                              final today = DateTime.now();
                              final dateString =
                                  "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

                              final existing = await FirebaseFirestore.instance
                                  .collection('truck_sessions')
                                  .where('truckId', isEqualTo: trucks[index].id)
                                  .where('date', isEqualTo: dateString)
                                  .where('status', isEqualTo: 'active')
                                  .limit(1)
                                  .get();

                              String sessionId;
                              if (existing.docs.isNotEmpty) {
                                sessionId = existing.docs.first.id;
                              } else {
                                final docRef = await FirebaseFirestore.instance
                                    .collection('truck_sessions')
                                    .add({
                                      'driverUid': FirebaseAuth
                                          .instance
                                          .currentUser!
                                          .uid,
                                      'driverName': name,
                                      'truckId': trucks[index].id,
                                      'truckNumber': data['truckNumber'] ?? '',
                                      'date': dateString,
                                      'status': 'active',
                                      'createdAt': FieldValue.serverTimestamp(),
                                    });
                                sessionId = docRef.id;
                              }

                              if (context.mounted) {
                                Navigator.push(
                                  context,
                                  MaterialPageRoute(
                                    builder: (_) => TruckWorkAreaScreen(
                                      sessionId: sessionId,
                                      truckNumber: data['truckNumber'] ?? '',
                                      siteName: '',
                                      driverName: name,
                                    ),
                                  ),
                                );
                              }
                            },
                          ),
                        );
                      },
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- TRUCK: SITE SELECT + CODE VERIFY ----------------
class TruckSiteSelectScreen extends StatefulWidget {
  final String name;
  final String truckId;
  final String truckNumber;

  const TruckSiteSelectScreen({
    super.key,
    required this.name,
    required this.truckId,
    required this.truckNumber,
  });

  @override
  State<TruckSiteSelectScreen> createState() => _TruckSiteSelectScreenState();
}

class _TruckSiteSelectScreenState extends State<TruckSiteSelectScreen> {
  String? _selectedSiteId;
  String? _selectedSiteName;
  final _codeController = TextEditingController();
  bool _isLoading = false;

  Future<void> _submit() async {
    if (_selectedSiteId == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please select a site.')));
      return;
    }
    if (_codeController.text.trim().length != 4) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Please enter the 4-digit supervisor code.'),
        ),
      );
      return;
    }

    setState(() => _isLoading = true);

    try {
      final today = DateTime.now();
      final dateString =
          "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";

      final supervisorMatch = await FirebaseFirestore.instance
          .collection('daily_sessions')
          .where('siteId', isEqualTo: _selectedSiteId)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .where('verificationCode', isEqualTo: _codeController.text.trim())
          .limit(1)
          .get();

      if (supervisorMatch.docs.isEmpty) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Invalid code. Check with your supervisor.'),
            ),
          );
          setState(() => _isLoading = false);
        }
        return;
      }

      final existing = await FirebaseFirestore.instance
          .collection('truck_sessions')
          .where('truckId', isEqualTo: widget.truckId)
          .where('date', isEqualTo: dateString)
          .where('status', isEqualTo: 'active')
          .limit(1)
          .get();

      String sessionId;

      if (existing.docs.isNotEmpty) {
        sessionId = existing.docs.first.id;
      } else {
        final docRef = await FirebaseFirestore.instance
            .collection('truck_sessions')
            .add({
              'driverUid': FirebaseAuth.instance.currentUser!.uid,
              'driverName': widget.name,
              'truckId': widget.truckId,
              'truckNumber': widget.truckNumber,
              'siteId': _selectedSiteId,
              'siteName': _selectedSiteName,
              'supervisorSessionId': supervisorMatch.docs.first.id,
              'date': dateString,
              'status': 'active',
              'createdAt': FieldValue.serverTimestamp(),
            });
        sessionId = docRef.id;
      }

      if (mounted) {
        Navigator.push(
          context,
          MaterialPageRoute(
            builder: (_) => TruckWorkAreaScreen(
              sessionId: sessionId,
              truckNumber: widget.truckNumber,
              siteName: _selectedSiteName ?? '',
              driverName: widget.name,
            ),
          ),
        );
      }
    } catch (e) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Error: $e')));
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Container(
        decoration: const BoxDecoration(gradient: AppTheme.mainGradient),
        child: SafeArea(
          child: Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 8, 16, 0),
                child: Row(
                  children: [
                    IconButton(
                      icon: const Icon(Icons.arrow_back, color: Colors.white),
                      onPressed: () => Navigator.pop(context),
                    ),
                    Text(
                      widget.truckNumber,
                      style: const TextStyle(
                        fontSize: 18,
                        fontWeight: FontWeight.bold,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
              Expanded(
                child: Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: GlassCard(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        const Text(
                          'Select Working Site',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                        const SizedBox(height: 8),
                        StreamBuilder<QuerySnapshot>(
                          stream: FirebaseFirestore.instance
                              .collection('sites')
                              .snapshots(),
                          builder: (context, snapshot) {
                            if (!snapshot.hasData) {
                              return const CircularProgressIndicator(
                                color: Colors.white,
                              );
                            }
                            final sites = snapshot.data!.docs;
                            return DropdownButtonFormField<String>(
                              initialValue: _selectedSiteId,
                              dropdownColor: AppTheme.primaryMid,
                              style: const TextStyle(color: Colors.white),
                              decoration: InputDecoration(
                                hintText: 'Choose a site',
                                hintStyle: TextStyle(
                                  color: Colors.white.withOpacity(0.6),
                                ),
                                prefixIcon: Icon(
                                  Icons.location_on,
                                  color: Colors.white.withOpacity(0.7),
                                ),
                                enabledBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                  borderSide: BorderSide(
                                    color: Colors.white.withOpacity(0.3),
                                  ),
                                ),
                                focusedBorder: OutlineInputBorder(
                                  borderRadius: BorderRadius.circular(12),
                                  borderSide: const BorderSide(
                                    color: AppTheme.accent,
                                  ),
                                ),
                              ),
                              items: sites.map((doc) {
                                final data = doc.data() as Map<String, dynamic>;
                                return DropdownMenuItem<String>(
                                  value: doc.id,
                                  child: Text(data['name'] ?? ''),
                                );
                              }).toList(),
                              onChanged: (val) {
                                final selected = sites.firstWhere(
                                  (d) => d.id == val,
                                );
                                final data =
                                    selected.data() as Map<String, dynamic>;
                                setState(() {
                                  _selectedSiteId = val;
                                  _selectedSiteName = data['name'];
                                });
                              },
                            );
                          },
                        ),
                        const SizedBox(height: 20),
                        const Text(
                          'Supervisor Code',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.white,
                          ),
                        ),
                        const SizedBox(height: 8),
                        TextField(
                          controller: _codeController,
                          keyboardType: TextInputType.number,
                          maxLength: 4,
                          style: const TextStyle(
                            color: Colors.white,
                            fontSize: 20,
                            letterSpacing: 6,
                          ),
                          inputFormatters: [
                            FilteringTextInputFormatter.digitsOnly,
                          ],
                          decoration: InputDecoration(
                            counterText: '',
                            hintText: '••••',
                            hintStyle: TextStyle(
                              color: Colors.white.withOpacity(0.4),
                            ),
                            prefixIcon: Icon(
                              Icons.vpn_key,
                              color: Colors.white.withOpacity(0.7),
                            ),
                            enabledBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: BorderSide(
                                color: Colors.white.withOpacity(0.3),
                              ),
                            ),
                            focusedBorder: OutlineInputBorder(
                              borderRadius: BorderRadius.circular(12),
                              borderSide: const BorderSide(
                                color: AppTheme.accent,
                              ),
                            ),
                          ),
                        ),
                        const SizedBox(height: 24),
                        _isLoading
                            ? const Center(
                                child: CircularProgressIndicator(
                                  color: Colors.white,
                                ),
                              )
                            : GradientButton(
                                label: 'SUBMIT',
                                icon: Icons.check,
                                onTap: _submit,
                              ),
                      ],
                    ),
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

// ---------------- TRUCK: WORK AREA ----------------
class TruckWorkAreaScreen extends StatefulWidget {
  final String sessionId;
  final String truckNumber;
  final String siteName;
  final String driverName;

  const TruckWorkAreaScreen({
    super.key,
    required this.sessionId,
    required this.truckNumber,
    required this.siteName,
    required this.driverName,
  });

  @override
  State<TruckWorkAreaScreen> createState() => _TruckWorkAreaScreenState();
}

class _TruckWorkAreaScreenState extends State<TruckWorkAreaScreen> {
  @override
  void initState() {
    super.initState();
    TruckLocationService.startTracking(widget.sessionId, widget.truckNumber);
  }

  CollectionReference get _tripsRef => FirebaseFirestore.instance
      .collection('truck_sessions')
      .doc(widget.sessionId)
      .collection('trips');

  Future<bool> _hasOngoingTrip() async {
    final snap = await _tripsRef
        .where('status', isEqualTo: 'ongoing')
        .limit(1)
        .get();
    return snap.docs.isNotEmpty;
  }

  Future<void> _completeTrip(String tripId) async {
    await _tripsRef.doc(tripId).update({
      'status': 'completed',
      'endedAt': FieldValue.serverTimestamp(),
    });

    // Sync this completed trip to Google Sheets
    final updatedDoc = await _tripsRef.doc(tripId).get();
    final data = updatedDoc.data() as Map<String, dynamic>;

    final startedAt = (data['startedAt'] as Timestamp?)?.toDate();
    final endedAt = (data['endedAt'] as Timestamp?)?.toDate();
    String durationText = '-';
    if (startedAt != null && endedAt != null) {
      final diff = endedAt.difference(startedAt);
      final h = diff.inHours;
      final m = diff.inMinutes % 60;
      durationText = '${h}h ${m}m';
    }

    GoogleSheetsService.sendRow(
      sheetName: 'Truck_Trips',
      row: [
        GoogleSheetsService.formatDate(DateTime.now()),
        widget.truckNumber,
        widget.driverName,
        data['startSiteName'] ?? '',
        data['endSiteName'] ?? '',
        data['billNumber'] ?? '',
        GoogleSheetsService.formatTime(data['startedAt']),
        GoogleSheetsService.formatTime(data['endedAt']),
        durationText,
        data['cubeCount'] ?? '',
      ],
    );
  }

  void _showNewTripDialog() async {
    final ongoing = await _hasOngoingTrip();
    if (ongoing) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text(
              'Complete the current trip before starting a new one.',
            ),
          ),
        );
      }
      return;
    }

    if (!mounted) return;

    showDialog(
      context: context,
      builder: (_) => NewTripDialog(
        onSubmit:
            (
              startSiteName,
              endSiteId,
              endSiteName,
              billNumber,
              cubeCount,
            ) async {
              Navigator.pop(context);
              await _tripsRef.add({
                'startSiteName': startSiteName,
                'endSiteId': endSiteId,
                'endSiteName': endSiteName,
                'billNumber': billNumber,
                'cubeCount': cubeCount,
                'status': 'ongoing',
                'startedAt': FieldValue.serverTimestamp(),
                'endedAt': null,
              });
            },
      ),
    );
  }

  void _showEndDayDialog() {
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('End Day'),
        content: const Text('Are you sure you want to end your work day?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final totalKm =
                  await TruckLocationService.stopTrackingAndCalculateDistance();

              await FirebaseFirestore.instance
                  .collection('truck_sessions')
                  .doc(widget.sessionId)
                  .update({
                    'status': 'completed',
                    'completedAt': FieldValue.serverTimestamp(),
                    'totalKm': totalKm,
                  });

              // Columns: Date, Truck Number, Type, Location, Distance So Far (KM), Time
              GoogleSheetsService.sendRow(
                sheetName: 'Truck_Locations',
                row: [
                  GoogleSheetsService.formatDate(DateTime.now()),
                  widget.truckNumber,
                  'DAY SUMMARY',
                  'Total Distance',
                  '${totalKm.toStringAsFixed(2)} km',
                  GoogleSheetsService.formatTime(Timestamp.now()),
                ],
              );

              if (context.mounted) {
                Navigator.pop(context);
                Navigator.popUntil(context, (route) => route.isFirst);
              }
            },
            style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            child: const Text('END DAY', style: TextStyle(color: Colors.white)),
          ),
        ],
      ),
    );
  }

  String _formatTime(Timestamp? ts) {
    if (ts == null) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () {
            if (Navigator.canPop(context)) {
              Navigator.pop(context);
            } else {
              Navigator.pushReplacement(
                context,
                MaterialPageRoute(
                  builder: (_) => TruckTypeScreen(name: widget.driverName),
                ),
              );
            }
          },
        ),
        title: Text(widget.truckNumber),
        backgroundColor: Colors.deepOrange[800],
      ),
      body: Column(
        children: [
          Container(
            width: double.infinity,
            padding: const EdgeInsets.all(12),
            color: Colors.deepOrange[50],
            child: Text(
              'Truck: ${widget.truckNumber}  •  Driver: ${widget.driverName}',
              style: const TextStyle(fontSize: 13),
            ),
          ),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: _tripsRef
                  .orderBy('startedAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (!snapshot.hasData) {
                  return const Center(child: CircularProgressIndicator());
                }
                final trips = snapshot.data!.docs;
                if (trips.isEmpty) {
                  return const Center(
                    child: Text(
                      'No trips yet.\nTap "+ NEW TASK" to begin.',
                      textAlign: TextAlign.center,
                    ),
                  );
                }

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: trips.length,
                  itemBuilder: (context, index) {
                    final doc = trips[index];
                    final data = doc.data() as Map<String, dynamic>;
                    final isOngoing = data['status'] == 'ongoing';

                    return Card(
                      color: isOngoing ? Colors.green[50] : Colors.white,
                      margin: const EdgeInsets.only(bottom: 10),
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                        side: BorderSide(
                          color: isOngoing ? Colors.green : Colors.grey[300]!,
                          width: isOngoing ? 1.5 : 1,
                        ),
                      ),
                      child: Padding(
                        padding: const EdgeInsets.all(12),
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Row(
                              mainAxisAlignment: MainAxisAlignment.spaceBetween,
                              children: [
                                Expanded(
                                  child: Text(
                                    '${data['startSiteName']} → ${data['endSiteName']}',
                                    style: const TextStyle(
                                      fontWeight: FontWeight.bold,
                                      fontSize: 15,
                                    ),
                                  ),
                                ),
                                Container(
                                  padding: const EdgeInsets.symmetric(
                                    horizontal: 8,
                                    vertical: 4,
                                  ),
                                  decoration: BoxDecoration(
                                    color: isOngoing
                                        ? Colors.green
                                        : Colors.grey[400],
                                    borderRadius: BorderRadius.circular(20),
                                  ),
                                  child: Text(
                                    isOngoing ? 'ONGOING' : 'DONE',
                                    style: const TextStyle(
                                      color: Colors.white,
                                      fontSize: 11,
                                    ),
                                  ),
                                ),
                              ],
                            ),
                            const SizedBox(height: 8),
                            TripTimerText(
                              isOngoing: isOngoing,
                              startedAt: (data['startedAt'] as Timestamp?)
                                  ?.toDate(),
                              endedAt: (data['endedAt'] as Timestamp?)
                                  ?.toDate(),
                            ),
                            if (data['billNumber'] != null &&
                                data['billNumber'].toString().isNotEmpty) ...[
                              const SizedBox(height: 6),
                              Text(
                                'Bill Number: ${data['billNumber']}',
                                style: const TextStyle(fontSize: 13),
                              ),
                            ],
                            const SizedBox(height: 6),
                            Text(
                              'Started: ${_formatTime(data['startedAt'] as Timestamp?)}'
                              '${data['endedAt'] != null ? "  •  Ended: ${_formatTime(data['endedAt'] as Timestamp?)}" : ""}',
                              style: const TextStyle(
                                fontSize: 12,
                                color: Colors.grey,
                              ),
                            ),
                            if (isOngoing) ...[
                              const SizedBox(height: 10),
                              SizedBox(
                                width: double.infinity,
                                child: ElevatedButton.icon(
                                  onPressed: () => _completeTrip(doc.id),
                                  icon: const Icon(
                                    Icons.check,
                                    color: Colors.white,
                                  ),
                                  label: const Text(
                                    'COMPLETE TASK',
                                    style: TextStyle(color: Colors.white),
                                  ),
                                  style: ElevatedButton.styleFrom(
                                    backgroundColor: Colors.green[700],
                                  ),
                                ),
                              ),
                            ],
                          ],
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
      floatingActionButton: FloatingActionButton.extended(
        onPressed: _showNewTripDialog,
        backgroundColor: Colors.deepOrange[800],
        icon: const Icon(Icons.add, color: Colors.white),
        label: const Text('NEW TASK', style: TextStyle(color: Colors.white)),
      ),
      bottomNavigationBar: SafeArea(
        child: Padding(
          padding: const EdgeInsets.all(12.0),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _showEndDayDialog,
              icon: const Icon(Icons.flag, color: Colors.white),
              label: const Text(
                'END DAY',
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                ),
              ),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red[700]),
            ),
          ),
        ),
      ),
    );
  }
}

// ---------------- NEW TRIP DIALOG (Truck) ----------------
class NewTripDialog extends StatefulWidget {
  final Function(
    String? startSiteName,
    String? endSiteId,
    String? endSiteName,
    String? billNumber,
    String? cubeCount,
  )
  onSubmit;

  const NewTripDialog({super.key, required this.onSubmit});

  @override
  State<NewTripDialog> createState() => _NewTripDialogState();
}

class _NewTripDialogState extends State<NewTripDialog> {
  String? _selectedStartSiteId;
  String? _selectedStartSiteName;
  String? _selectedEndSiteId;
  String? _selectedEndSiteName;
  final _billNumberController = TextEditingController();
  final _cubeController = TextEditingController();
  String _errorText = '';

  void _handleSubmit() {
    if (_selectedStartSiteId == null) {
      setState(() => _errorText = 'Please select the start site.');
      return;
    }
    if (_selectedEndSiteId == null) {
      setState(() => _errorText = 'Please select the end site.');
      return;
    }
    widget.onSubmit(
      _selectedStartSiteName,
      _selectedEndSiteId,
      _selectedEndSiteName,
      _billNumberController.text.trim().isEmpty
          ? null
          : _billNumberController.text.trim(),
      _cubeController.text.trim().isEmpty ? null : _cubeController.text.trim(),
    );
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
      title: const Text('Start New Task'),
      content: SingleChildScrollView(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Start Site',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('sites')
                  .snapshots(),
              builder: (context, snapshot) {
                if (!snapshot.hasData) return const CircularProgressIndicator();
                final sites = snapshot.data!.docs;
                return DropdownButtonFormField<String>(
                  initialValue: _selectedStartSiteId,
                  decoration: InputDecoration(
                    hintText: 'Choose start site',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  items: sites.map((doc) {
                    final data = doc.data() as Map<String, dynamic>;
                    return DropdownMenuItem<String>(
                      value: doc.id,
                      child: Text(data['name'] ?? ''),
                    );
                  }).toList(),
                  onChanged: (val) {
                    final selected = sites.firstWhere((d) => d.id == val);
                    final data = selected.data() as Map<String, dynamic>;
                    setState(() {
                      _selectedStartSiteId = val;
                      _selectedStartSiteName = data['name'];
                    });
                  },
                );
              },
            ),
            const SizedBox(height: 16),
            const Text(
              'End Site',
              style: TextStyle(fontWeight: FontWeight.bold),
            ),
            const SizedBox(height: 8),
            StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('sites')
                  .snapshots(),
              builder: (context, snapshot) {
                if (!snapshot.hasData) return const CircularProgressIndicator();
                final sites = snapshot.data!.docs;
                return DropdownButtonFormField<String>(
                  initialValue: _selectedEndSiteId,
                  decoration: InputDecoration(
                    hintText: 'Choose end site',
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(10),
                    ),
                  ),
                  items: sites.map((doc) {
                    final data = doc.data() as Map<String, dynamic>;
                    return DropdownMenuItem<String>(
                      value: doc.id,
                      child: Text(data['name'] ?? ''),
                    );
                  }).toList(),
                  onChanged: (val) {
                    final selected = sites.firstWhere((d) => d.id == val);
                    final data = selected.data() as Map<String, dynamic>;
                    setState(() {
                      _selectedEndSiteId = val;
                      _selectedEndSiteName = data['name'];
                    });
                  },
                );
              },
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _billNumberController,
              keyboardType: TextInputType.number,
              inputFormatters: [FilteringTextInputFormatter.digitsOnly],
              decoration: InputDecoration(
                labelText: 'Bill Number (optional)',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            const SizedBox(height: 16),
            TextField(
              controller: _cubeController,
              keyboardType: TextInputType.number,
              decoration: InputDecoration(
                labelText: 'Cube (Quantity)',
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(10),
                ),
              ),
            ),
            if (_errorText.isNotEmpty) ...[
              const SizedBox(height: 12),
              Text(
                _errorText,
                style: const TextStyle(color: Colors.red, fontSize: 13),
              ),
            ],
          ],
        ),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.pop(context),
          child: const Text('Cancel'),
        ),
        ElevatedButton(
          onPressed: _handleSubmit,
          style: ElevatedButton.styleFrom(
            backgroundColor: Colors.deepOrange[800],
          ),
          child: const Text('START', style: TextStyle(color: Colors.white)),
        ),
      ],
    );
  }
}

// ---------------- VEHICLE REGISTRATION SCREEN (Admin, 2 tabs) ----------------
// Tab 1 reuses TruckManagementScreen as-is (Truck Registration, including
// the Cube Capacity field) — deliberately the same widget, not a
// body-only extract, so it stays a single source of truth for the truck
// form. Tab 2 (QR Generate) picks a registered truck, shows its assigned
// driver + cube capacity read-only, and renders a QR code encoding
// {"truckNumber", "driverName", "cube"} for Supervisor's QR Scan
// (WorkSessionScreen) to scan and submit a load in one step.
class VehicleRegistrationScreen extends StatefulWidget {
  const VehicleRegistrationScreen({super.key});

  @override
  State<VehicleRegistrationScreen> createState() =>
      _VehicleRegistrationScreenState();
}

class _VehicleRegistrationScreenState extends State<VehicleRegistrationScreen>
    with SingleTickerProviderStateMixin {
  late final TabController _tabController;

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: 2, vsync: this);
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Vehicle Registration'),
        backgroundColor: Colors.deepOrange[800],
        bottom: TabBar(
          controller: _tabController,
          indicatorColor: Colors.white,
          labelColor: Colors.white,
          unselectedLabelColor: Colors.white70,
          tabs: const [
            Tab(text: 'Truck Registration'),
            Tab(text: 'QR Generate'),
          ],
        ),
      ),
      body: TabBarView(
        controller: _tabController,
        children: const [_VehicleRegistrationTab(), _QrGenerateTab()],
      ),
    );
  }
}

// Tab 1's Truck/Bike switch. Trucks and bikes are separate collections with
// separate forms (see the Isolated Design note on kBikesCollection), so this
// just picks which of the two existing screens to show — neither form knows
// about the other. The QR Generate tab (Tab 2) stays truck-only: bikes have
// no QR workflow.
class _VehicleRegistrationTab extends StatefulWidget {
  const _VehicleRegistrationTab();

  @override
  State<_VehicleRegistrationTab> createState() => _VehicleRegistrationTabState();
}

class _VehicleRegistrationTabState extends State<_VehicleRegistrationTab> {
  bool _isBike = false;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
          child: SizedBox(
            width: double.infinity,
            child: SegmentedButton<bool>(
              segments: const [
                ButtonSegment<bool>(
                  value: false,
                  label: Text('Truck'),
                  icon: Icon(Icons.local_shipping),
                ),
                ButtonSegment<bool>(
                  value: true,
                  label: Text('Bike'),
                  icon: Icon(Icons.two_wheeler),
                ),
              ],
              selected: {_isBike},
              onSelectionChanged: (selection) =>
                  setState(() => _isBike = selection.first),
            ),
          ),
        ),
        Expanded(
          child: _isBike
              ? const BikeManagementScreen()
              : const TruckManagementScreen(),
        ),
      ],
    );
  }
}

class _QrGenerateTab extends StatefulWidget {
  const _QrGenerateTab();

  @override
  State<_QrGenerateTab> createState() => _QrGenerateTabState();
}

class _QrGenerateTabState extends State<_QrGenerateTab> {
  String? _selectedTruckId;
  String? _selectedTruckNumber;
  String? _selectedDriverName;
  double? _selectedCubeCapacity;
  String? _qrData;
  final _qrCaptureKey = GlobalKey();

  void _onTruckSelected(String truckId, Map<String, dynamic> data) {
    setState(() {
      _selectedTruckId = truckId;
      _selectedTruckNumber = (data['truckNumber'] ?? '').toString();
      _selectedDriverName = data['assignedDriverName'] as String?;
      _selectedCubeCapacity = (data['cubeCapacity'] as num?)?.toDouble();
      // Force an explicit re-generate for the newly selected truck, rather
      // than leaving the previous truck's QR code showing.
      _qrData = null;
    });
  }

  // Deterministic on purpose: the QR only ever encodes the truck number, so
  // regenerating it later (a lost sticker, say) always produces the exact
  // same code — driver assignment and cube capacity are mutable fields that
  // would otherwise silently stale a printed sticker every time either one
  // changes. QR Scan (WorkSessionScreen._openQrScanner) looks those up live
  // from Firestore at scan time instead of trusting embedded values.
  void _generateQrCode() {
    if (_selectedTruckNumber == null) return;
    setState(() {
      _qrData = jsonEncode({'truckNumber': _selectedTruckNumber});
    });
  }

  // Captures the RepaintBoundary wrapping the QR + Truck Number card (see
  // build()) as a PNG and triggers a browser download — safe to call here
  // since it's a delayed, user-triggered action well after the widget has
  // already been laid out and painted (unlike LiveTrackingScreen's earlier
  // truck-marker icon, which hit an "Assertion failed: !debugNeedsPaint"
  // error from calling toImage() too early, right after the first frame).
  Future<void> _downloadQrCode() async {
    try {
      final boundary =
          _qrCaptureKey.currentContext?.findRenderObject()
              as RenderRepaintBoundary?;
      if (boundary == null) return;
      final image = await boundary.toImage(pixelRatio: 3);
      final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
      if (byteData == null) return;
      final bytes = byteData.buffer.asUint8List();
      qr_download.downloadPngBytes(bytes, '${_selectedTruckNumber}_QR.png');
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to download QR code: $e')),
        );
      }
    }
  }

  // Search-bottom-sheet pattern, same as NewWorkDialog's
  // _showUnloadingSitePicker: a search TextField over a scrollable filtered
  // list, tap to select. No "add new" option here, unlike that one — a
  // truck not yet registered belongs in Truck Registration (Tab 1), not
  // invented inline from the QR Generate tab.
  Future<void> _showTruckSearchPicker() async {
    final selected = await showModalBottomSheet<Map<String, dynamic>>(
      context: context,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        String searchText = '';
        return StatefulBuilder(
          builder: (sheetContext, setSheetState) {
            return Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SizedBox(
                height: MediaQuery.of(sheetContext).size.height * 0.75,
                child: Column(
                  children: [
                    const SizedBox(height: 12),
                    Container(
                      width: 40,
                      height: 4,
                      decoration: BoxDecoration(
                        color: Colors.grey[300],
                        borderRadius: BorderRadius.circular(2),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.all(16),
                      child: TextField(
                        autofocus: true,
                        decoration: InputDecoration(
                          hintText: 'Search truck number',
                          prefixIcon: const Icon(Icons.search),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onChanged: (val) =>
                            setSheetState(() => searchText = val),
                      ),
                    ),
                    Expanded(
                      child: StreamBuilder<QuerySnapshot>(
                        stream: FirebaseFirestore.instance
                            .collection('trucks')
                            .snapshots(),
                        builder: (context, snapshot) {
                          if (!snapshot.hasData) {
                            return const Center(
                              child: CircularProgressIndicator(),
                            );
                          }
                          final trimmedSearch = searchText.trim().toLowerCase();
                          final filtered = snapshot.data!.docs.where((doc) {
                            final data = doc.data() as Map<String, dynamic>;
                            final truckNumber = (data['truckNumber'] ?? '')
                                .toString();
                            return truckNumber.toLowerCase().contains(
                              trimmedSearch,
                            );
                          }).toList();
                          if (filtered.isEmpty) {
                            return const Center(
                              child: Text('No trucks found.'),
                            );
                          }
                          return ListView(
                            children: [
                              for (final doc in filtered)
                                Builder(
                                  builder: (context) {
                                    final data =
                                        doc.data() as Map<String, dynamic>;
                                    return ListTile(
                                      leading: const Icon(
                                        Icons.local_shipping,
                                        color: Colors.deepOrange,
                                      ),
                                      title: Text(
                                        (data['truckNumber'] ?? '').toString(),
                                      ),
                                      subtitle: Text(
                                        (data['assignedDriverName']
                                                as String?) ??
                                            'Not assigned',
                                      ),
                                      onTap: () => Navigator.pop(sheetContext, {
                                        'id': doc.id,
                                        'data': data,
                                      }),
                                    );
                                  },
                                ),
                            ],
                          );
                        },
                      ),
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );

    if (selected != null) {
      _onTruckSelected(
        selected['id'] as String,
        selected['data'] as Map<String, dynamic>,
      );
    }
  }

  Widget _readOnlyField(String label, String value) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        border: Border.all(color: Colors.grey.shade400),
        borderRadius: BorderRadius.circular(12),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(label, style: TextStyle(fontSize: 11, color: Colors.grey[600])),
          const SizedBox(height: 4),
          Text(
            value,
            style: const TextStyle(fontSize: 15, fontWeight: FontWeight.bold),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          const Text(
            'Select Truck',
            style: TextStyle(fontWeight: FontWeight.bold),
          ),
          const SizedBox(height: 8),
          InkWell(
            borderRadius: BorderRadius.circular(12),
            onTap: _showTruckSearchPicker,
            child: InputDecorator(
              decoration: InputDecoration(
                labelText: 'Truck Number',
                prefixIcon: const Icon(Icons.local_shipping),
                suffixIcon: const Icon(Icons.search, size: 18),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
              child: Text(
                _selectedTruckNumber ?? 'Search or select a truck',
                style: TextStyle(
                  color: _selectedTruckNumber == null
                      ? Colors.grey[600]
                      : Colors.black87,
                ),
              ),
            ),
          ),
          if (_selectedTruckId != null) ...[
            const SizedBox(height: 16),
            _readOnlyField(
              'Driver Name',
              _selectedDriverName ?? 'Not assigned',
            ),
            const SizedBox(height: 12),
            _readOnlyField(
              'Cube Capacity',
              _selectedCubeCapacity?.toString() ?? 'Not set',
            ),
            const SizedBox(height: 16),
            SizedBox(
              width: double.infinity,
              height: 48,
              child: ElevatedButton.icon(
                onPressed: _generateQrCode,
                icon: const Icon(Icons.qr_code, color: Colors.white),
                label: const Text(
                  'Generate QR Code',
                  style: TextStyle(color: Colors.white),
                ),
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.deepOrange[800],
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
              ),
            ),
          ],
          if (_qrData != null) ...[
            const SizedBox(height: 24),
            Center(
              child: RepaintBoundary(
                key: _qrCaptureKey,
                child: Card(
                  color: Colors.white,
                  child: Padding(
                    padding: const EdgeInsets.all(16),
                    child: Column(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        QrImageView(
                          data: _qrData!,
                          version: QrVersions.auto,
                          size: 200,
                          backgroundColor: Colors.white,
                        ),
                        const SizedBox(height: 12),
                        Text(
                          _selectedTruckNumber ?? '',
                          style: const TextStyle(
                            fontSize: 20,
                            fontWeight: FontWeight.bold,
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            ),
            if (kIsWeb) ...[
              const SizedBox(height: 16),
              Center(
                child: SizedBox(
                  width: 220,
                  height: 44,
                  child: OutlinedButton.icon(
                    onPressed: _downloadQrCode,
                    icon: const Icon(Icons.download),
                    label: const Text('Download QR Code'),
                  ),
                ),
              ),
            ],
          ],
        ],
      ),
    );
  }
}

// ---------------- TRUCK MANAGEMENT SCREEN (Admin) ----------------
class TruckManagementScreen extends StatefulWidget {
  const TruckManagementScreen({super.key});

  @override
  State<TruckManagementScreen> createState() => _TruckManagementScreenState();
}

class _TruckManagementScreenState extends State<TruckManagementScreen> {
  final _truckNumberController = TextEditingController();
  final _gpsDeviceIdController = TextEditingController();
  final _cubeCapacityController = TextEditingController();
  final _searchController = TextEditingController();
  String _searchQuery = '';
  String? _selectedDriverUid;
  String? _selectedDriverName;
  bool _isCompanyTruck = false;

  Future<void> _addTruck() async {
    final enteredTruckNumber = _truckNumberController.text.trim();
    if (enteredTruckNumber.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a truck number.')),
      );
      return;
    }

    final existingTrucks = await FirebaseFirestore.instance
        .collection('trucks')
        .get();
    final normalizedEntry = enteredTruckNumber.trim().toUpperCase();
    final isDuplicate = existingTrucks.docs.any((doc) {
      final data = doc.data();
      final existingNumber =
          (data['truckNumber'] as String?)?.trim().toUpperCase() ?? '';
      return existingNumber == normalizedEntry;
    });

    if (isDuplicate) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This truck number is already registered.'),
            backgroundColor: Colors.red,
          ),
        );
      }
      return;
    }

    final enteredGpsDeviceId = _gpsDeviceIdController.text.trim();
    final enteredCubeCapacity = double.tryParse(
      _cubeCapacityController.text.trim(),
    );

    await FirebaseFirestore.instance.collection('trucks').add({
      'truckNumber': enteredTruckNumber,
      'assignedDriverUid': _selectedDriverUid,
      'assignedDriverName': _selectedDriverName,
      'gpsDeviceId': enteredGpsDeviceId.isEmpty ? null : enteredGpsDeviceId,
      'cubeCapacity': enteredCubeCapacity,
      'isCompanyTruck': _isCompanyTruck,
      'createdAt': FieldValue.serverTimestamp(),
    });

    _truckNumberController.clear();
    _gpsDeviceIdController.clear();
    _cubeCapacityController.clear();
    setState(() {
      _selectedDriverUid = null;
      _selectedDriverName = null;
      _isCompanyTruck = false;
    });

    if (mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Truck added successfully!')),
      );
    }
  }

  Future<void> _deleteTruck(String docId) async {
    await FirebaseFirestore.instance.collection('trucks').doc(docId).delete();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Manage Trucks'),
        backgroundColor: Colors.deepOrange[800],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                TextField(
                  controller: _truckNumberController,
                  textCapitalization: TextCapitalization.characters,
                  decoration: InputDecoration(
                    labelText: 'Truck Number / Plate',
                    prefixIcon: const Icon(Icons.local_shipping),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('users')
                      .where('canDriveTruck', isEqualTo: true)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData)
                      return const CircularProgressIndicator();
                    final drivers = snapshot.data!.docs;
                    return DropdownButtonFormField<String>(
                      initialValue: _selectedDriverUid,
                      decoration: InputDecoration(
                        labelText: 'Assign Driver (optional)',
                        prefixIcon: const Icon(Icons.person),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                      items: drivers.map((doc) {
                        final data = doc.data() as Map<String, dynamic>;
                        return DropdownMenuItem<String>(
                          value: doc.id,
                          child: Text(data['name'] ?? ''),
                        );
                      }).toList(),
                      onChanged: (val) {
                        final selected = drivers.firstWhere((d) => d.id == val);
                        final data = selected.data() as Map<String, dynamic>;
                        setState(() {
                          _selectedDriverUid = val;
                          _selectedDriverName = data['name'];
                        });
                      },
                    );
                  },
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _gpsDeviceIdController,
                  decoration: InputDecoration(
                    labelText: 'GPS Device ID (optional)',
                    hintText: 'Traccar Device Identifier, e.g. 9210188280',
                    prefixIcon: const Icon(Icons.gps_fixed),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _cubeCapacityController,
                  keyboardType: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  decoration: InputDecoration(
                    labelText: 'Cube Capacity (optional)',
                    prefixIcon: const Icon(Icons.square_foot),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                // Garage module (see GarageScreen) — only company trucks
                // with a GPS device are eligible for KM-based service
                // tracking there.
                CheckboxListTile(
                  title: const Text('Is Company Truck?'),
                  value: _isCompanyTruck,
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                  onChanged: (val) =>
                      setState(() => _isCompanyTruck = val ?? false),
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _addTruck,
                    icon: const Icon(Icons.add, color: Colors.white),
                    label: const Text(
                      'ADD TRUCK',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.deepOrange[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Divider(),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
            child: TextField(
              controller: _searchController,
              onChanged: (val) => setState(() => _searchQuery = val),
              decoration: InputDecoration(
                labelText: 'Search by Truck Number',
                prefixIcon: const Icon(Icons.search),
                suffixIcon: _searchQuery.isEmpty
                    ? null
                    : IconButton(
                        icon: const Icon(Icons.clear),
                        onPressed: () {
                          _searchController.clear();
                          setState(() => _searchQuery = '');
                        },
                      ),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('trucks')
                  .orderBy('createdAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                  return const Center(child: Text('No trucks added yet.'));
                }

                // Client-side filter over the same stream's data — no
                // separate Firestore query, matches as the typed text
                // appears anywhere in the truck number, case-insensitive.
                final query = _searchQuery.trim().toLowerCase();
                final trucks = query.isEmpty
                    ? snapshot.data!.docs
                    : snapshot.data!.docs.where((doc) {
                        final data = doc.data() as Map<String, dynamic>;
                        final truckNumber = (data['truckNumber'] ?? '')
                            .toString()
                            .toLowerCase();
                        return truckNumber.contains(query);
                      }).toList();

                if (trucks.isEmpty) {
                  return Center(
                    child: Text("No trucks found matching '$_searchQuery'"),
                  );
                }

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: trucks.length,
                  itemBuilder: (context, index) {
                    final data = trucks[index].data() as Map<String, dynamic>;
                    final docId = trucks[index].id;

                    return _WebStaggeredFadeIn(
                      index: index,
                      child: _WebHoverCard(
                        child: Card(
                          margin: const EdgeInsets.only(bottom: 10),
                          child: ListTile(
                            leading: CircleAvatar(
                              backgroundColor: Colors.deepOrange.withOpacity(
                                0.15,
                              ),
                              child: const Icon(
                                Icons.local_shipping,
                                color: Colors.deepOrange,
                              ),
                            ),
                            title: Text(data['truckNumber'] ?? ''),
                            subtitle: Text(
                              data['assignedDriverName'] != null
                                  ? 'Driver: ${data['assignedDriverName']}'
                                  : 'No driver assigned',
                            ),
                            trailing: IconButton(
                              icon: const Icon(Icons.delete, color: Colors.red),
                              onPressed: () => confirmDelete(
                                context: context,
                                title: 'Delete Truck?',
                                message:
                                    'Are you sure you want to delete this truck? This cannot be undone.',
                                onConfirm: () => _deleteTruck(docId),
                              ),
                            ),
                            onTap: () {
                              pushWebAware(
                                context,
                                TruckProfileScreen(
                                  truckId: docId,
                                  truckNumber: data['truckNumber'] ?? '',
                                ),
                              );
                            },
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------- BIKE MANAGEMENT SCREEN ----------------
// Bike equivalent of TruckManagementScreen above, writing to the separate
// bikes collection. Deliberately NOT folded into that screen: truck
// documents drive the QR system, GPS live tracking and every work_record
// flow, none of which apply to a bike — the only thing the two share is the
// Garage's KM-since-service tracking (see GarageService).
class BikeManagementScreen extends StatefulWidget {
  const BikeManagementScreen({super.key});

  @override
  State<BikeManagementScreen> createState() => _BikeManagementScreenState();
}

class _BikeManagementScreenState extends State<BikeManagementScreen> {
  final _bikeNumberController = TextEditingController();
  final _driverNameController = TextEditingController();
  final _gpsDeviceIdController = TextEditingController();
  final _searchController = TextEditingController();
  String _searchQuery = '';
  bool _isCompanyBike = true;

  @override
  void dispose() {
    _bikeNumberController.dispose();
    _driverNameController.dispose();
    _gpsDeviceIdController.dispose();
    _searchController.dispose();
    super.dispose();
  }

  Future<void> _addBike() async {
    final enteredBikeNumber = _bikeNumberController.text.trim();
    if (enteredBikeNumber.isEmpty) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Please enter a bike number.')));
      return;
    }

    final existingBikes = await FirebaseFirestore.instance
        .collection(kBikesCollection)
        .get();
    final normalizedEntry = enteredBikeNumber.toUpperCase();
    final isDuplicate = existingBikes.docs.any((doc) {
      final existingNumber =
          (doc.data()['bikeNumber'] as String?)?.trim().toUpperCase() ?? '';
      return existingNumber == normalizedEntry;
    });

    if (isDuplicate) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('This bike number is already registered.'),
            backgroundColor: Colors.red,
          ),
        );
      }
      return;
    }

    final enteredDriverName = _driverNameController.text.trim();
    final enteredGpsDeviceId = _gpsDeviceIdController.text.trim();

    await FirebaseFirestore.instance.collection(kBikesCollection).add({
      'bikeNumber': enteredBikeNumber,
      'driverName': enteredDriverName.isEmpty ? null : enteredDriverName,
      'gpsDeviceId': enteredGpsDeviceId.isEmpty ? null : enteredGpsDeviceId,
      'isCompanyBike': _isCompanyBike,
      'createdAt': FieldValue.serverTimestamp(),
    });

    _bikeNumberController.clear();
    _driverNameController.clear();
    _gpsDeviceIdController.clear();
    setState(() => _isCompanyBike = true);

    if (mounted) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Bike added successfully!')));
    }
  }

  Future<void> _deleteBike(String docId) async {
    await FirebaseFirestore.instance
        .collection(kBikesCollection)
        .doc(docId)
        .delete();
  }

  // Same pattern as TruckProfileScreen._showSetGpsDeviceDialog — a bike can
  // be registered with GPS Device ID left empty (see _addBike) and this is
  // how it gets set or changed afterwards.
  void _showSetGpsDeviceDialog(String bikeId, String? currentDeviceId) {
    final deviceIdController = TextEditingController(
      text: currentDeviceId ?? '',
    );
    showDialog(
      context: context,
      builder: (dialogContext) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Assigned GPS Device'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Enter this bike\'s Traccar Device Identifier (copy it from '
              'the Traccar Devices list).',
              style: TextStyle(fontSize: 13, color: Colors.black54),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: deviceIdController,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: 'GPS Device Identifier',
                hintText: 'e.g. 9210188280',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final typedId = deviceIdController.text.trim();
              await FirebaseFirestore.instance
                  .collection(kBikesCollection)
                  .doc(bikeId)
                  .update({'gpsDeviceId': typedId.isEmpty ? null : typedId});
              if (dialogContext.mounted) Navigator.pop(dialogContext);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                TextField(
                  controller: _bikeNumberController,
                  textCapitalization: TextCapitalization.characters,
                  decoration: InputDecoration(
                    labelText: 'Bike Number / Plate',
                    prefixIcon: const Icon(Icons.two_wheeler),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _driverNameController,
                  decoration: InputDecoration(
                    labelText: 'Driver Name (optional)',
                    prefixIcon: const Icon(Icons.person),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _gpsDeviceIdController,
                  decoration: InputDecoration(
                    labelText: 'GPS Device ID (optional)',
                    hintText: 'Traccar Device Identifier, e.g. 9210188280',
                    prefixIcon: const Icon(Icons.gps_fixed),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                // Garage module (see GarageScreen's Bikes tab) — only
                // company bikes with a GPS device are eligible for KM-based
                // service tracking there.
                CheckboxListTile(
                  title: const Text('Is Company Bike?'),
                  value: _isCompanyBike,
                  contentPadding: EdgeInsets.zero,
                  controlAffinity: ListTileControlAffinity.leading,
                  onChanged: (val) =>
                      setState(() => _isCompanyBike = val ?? false),
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _addBike,
                    icon: const Icon(Icons.add, color: Colors.white),
                    label: const Text(
                      'ADD BIKE',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.deepOrange[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Divider(),
          Padding(
            padding: const EdgeInsets.fromLTRB(16, 8, 16, 8),
            child: TextField(
              controller: _searchController,
              onChanged: (val) => setState(() => _searchQuery = val),
              decoration: InputDecoration(
                labelText: 'Search by Bike Number',
                prefixIcon: const Icon(Icons.search),
                suffixIcon: _searchQuery.isEmpty
                    ? null
                    : IconButton(
                        icon: const Icon(Icons.clear),
                        onPressed: () {
                          _searchController.clear();
                          setState(() => _searchQuery = '');
                        },
                      ),
                border: OutlineInputBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
          Expanded(
            child: StreamBuilder<QuerySnapshot<Map<String, dynamic>>>(
              stream: FirebaseFirestore.instance
                  .collection(kBikesCollection)
                  .orderBy('createdAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                  return const Center(child: Text('No bikes added yet.'));
                }

                final query = _searchQuery.trim().toLowerCase();
                final bikes = query.isEmpty
                    ? snapshot.data!.docs
                    : snapshot.data!.docs.where((doc) {
                        final bikeNumber = (doc.data()['bikeNumber'] ?? '')
                            .toString()
                            .toLowerCase();
                        return bikeNumber.contains(query);
                      }).toList();

                if (bikes.isEmpty) {
                  return Center(
                    child: Text("No bikes found matching '$_searchQuery'"),
                  );
                }

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: bikes.length,
                  itemBuilder: (context, index) {
                    final data = bikes[index].data();
                    final docId = bikes[index].id;
                    final bikeNumber = (data['bikeNumber'] ?? '').toString();
                    final gpsDeviceId = data['gpsDeviceId'] as String?;

                    return _WebStaggeredFadeIn(
                      index: index,
                      child: _WebHoverCard(
                        child: Card(
                          margin: const EdgeInsets.only(bottom: 10),
                          child: ListTile(
                            isThreeLine: true,
                            leading: CircleAvatar(
                              backgroundColor: Colors.deepOrange.withOpacity(
                                0.15,
                              ),
                              child: const Icon(
                                Icons.two_wheeler,
                                color: Colors.deepOrange,
                              ),
                            ),
                            title: Text(bikeNumber),
                            subtitle: Text(
                              '${data['driverName'] != null ? 'Driver: ${data['driverName']}' : 'No driver assigned'}\n'
                              'GPS Device: ${gpsDeviceId ?? 'Not assigned'}',
                            ),
                            trailing: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                IconButton(
                                  icon: Icon(
                                    gpsDeviceId == null
                                        ? Icons.add_location_alt
                                        : Icons.gps_fixed,
                                  ),
                                  tooltip: gpsDeviceId == null
                                      ? 'Set GPS Device'
                                      : 'Change GPS Device',
                                  onPressed: () => _showSetGpsDeviceDialog(
                                    docId,
                                    gpsDeviceId,
                                  ),
                                ),
                                IconButton(
                                  icon: const Icon(Icons.history),
                                  tooltip: 'View History',
                                  onPressed: () =>
                                      showGarageServiceHistoryDialog(
                                        context: context,
                                        collectionName: kBikesCollection,
                                        vehicleId: docId,
                                        vehicleNumber: bikeNumber,
                                      ),
                                ),
                                IconButton(
                                  icon: const Icon(
                                    Icons.delete,
                                    color: Colors.red,
                                  ),
                                  onPressed: () => confirmDelete(
                                    context: context,
                                    title: 'Delete Bike?',
                                    message:
                                        'Are you sure you want to delete this bike? This cannot be undone.',
                                    onConfirm: () => _deleteBike(docId),
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------- FUEL STATION MANAGEMENT SCREEN ----------------
class FuelStationManagementScreen extends StatefulWidget {
  const FuelStationManagementScreen({super.key});

  @override
  State<FuelStationManagementScreen> createState() =>
      _FuelStationManagementScreenState();
}

class _FuelStationManagementScreenState
    extends State<FuelStationManagementScreen> {
  final _stationNameController = TextEditingController();
  final _stationLocationController = TextEditingController();

  Future<void> _addFuelStation() async {
    final enteredName = _stationNameController.text.trim();
    if (enteredName.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Please enter a station name.')),
      );
      return;
    }

    try {
      final existingStations = await FirebaseFirestore.instance
          .collection('fuel_stations')
          .get();
      final normalizedEntry = enteredName.toUpperCase();
      final isDuplicate = existingStations.docs.any((doc) {
        final data = doc.data();
        final existingName =
            (data['name'] as String?)?.trim().toUpperCase() ?? '';
        return existingName == normalizedEntry;
      });

      if (isDuplicate) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('This fuel station is already registered.'),
              backgroundColor: Colors.red,
            ),
          );
        }
        return;
      }

      await FirebaseFirestore.instance.collection('fuel_stations').add({
        'name': enteredName,
        'location': _stationLocationController.text.trim(),
        'createdAt': FieldValue.serverTimestamp(),
      });

      _stationNameController.clear();
      _stationLocationController.clear();

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Fuel station added successfully!')),
        );
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('Failed to add fuel station: $e')),
        );
      }
    }
  }

  Future<void> _deleteFuelStation(String docId) async {
    await FirebaseFirestore.instance
        .collection('fuel_stations')
        .doc(docId)
        .delete();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text('Manage Fuel Stations'),
        backgroundColor: Colors.deepOrange[800],
      ),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.all(16.0),
            child: Column(
              children: [
                TextField(
                  controller: _stationNameController,
                  decoration: InputDecoration(
                    labelText: 'Station Name',
                    prefixIcon: const Icon(Icons.local_gas_station),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: _stationLocationController,
                  decoration: InputDecoration(
                    labelText: 'Location (optional)',
                    prefixIcon: const Icon(Icons.map),
                    border: OutlineInputBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                SizedBox(
                  width: double.infinity,
                  height: 48,
                  child: ElevatedButton.icon(
                    onPressed: _addFuelStation,
                    icon: const Icon(Icons.add, color: Colors.white),
                    label: const Text(
                      'ADD FUEL STATION',
                      style: TextStyle(color: Colors.white),
                    ),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.deepOrange[800],
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(12),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
          const Divider(),
          Expanded(
            child: StreamBuilder<QuerySnapshot>(
              stream: FirebaseFirestore.instance
                  .collection('fuel_stations')
                  .orderBy('createdAt', descending: true)
                  .snapshots(),
              builder: (context, snapshot) {
                if (snapshot.connectionState == ConnectionState.waiting) {
                  return const Center(child: CircularProgressIndicator());
                }
                if (!snapshot.hasData || snapshot.data!.docs.isEmpty) {
                  return const Center(
                    child: Text('No fuel stations added yet.'),
                  );
                }

                final stations = snapshot.data!.docs;

                return ListView.builder(
                  padding: const EdgeInsets.all(12),
                  itemCount: stations.length,
                  itemBuilder: (context, index) {
                    final data = stations[index].data() as Map<String, dynamic>;
                    final docId = stations[index].id;

                    return _WebStaggeredFadeIn(
                      index: index,
                      child: _WebHoverCard(
                        child: Card(
                          margin: const EdgeInsets.only(bottom: 10),
                          child: ListTile(
                            leading: CircleAvatar(
                              backgroundColor: Colors.deepOrange.withOpacity(
                                0.15,
                              ),
                              child: const Icon(
                                Icons.local_gas_station,
                                color: Colors.deepOrange,
                              ),
                            ),
                            title: Text(data['name'] ?? ''),
                            subtitle: Text(
                              (data['location'] ?? '').toString().isEmpty
                                  ? 'No location set'
                                  : data['location'],
                            ),
                            trailing: IconButton(
                              icon: const Icon(Icons.delete, color: Colors.red),
                              onPressed: () => confirmDelete(
                                context: context,
                                title: 'Delete Fuel Station?',
                                message:
                                    'Are you sure you want to delete this fuel station? This cannot be undone.',
                                onConfirm: () => _deleteFuelStation(docId),
                              ),
                            ),
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

// ---------------- WEBSITE CONTENT MANAGEMENT SCREEN (web-only content, Admin) ----------------
class WebsiteContentManagementScreen extends StatefulWidget {
  const WebsiteContentManagementScreen({super.key});

  @override
  State<WebsiteContentManagementScreen> createState() =>
      _WebsiteContentManagementScreenState();
}

class _WebsiteContentManagementScreenState
    extends State<WebsiteContentManagementScreen> {
  final _heroTitleController = TextEditingController();
  final _heroSubtitleController = TextEditingController();
  final _aboutTextController = TextEditingController();
  final _whatsappController = TextEditingController();
  final _contactEmailController = TextEditingController();
  bool _loadingContent = true;
  bool _savingContent = false;

  @override
  void initState() {
    super.initState();
    _loadContent();
  }

  @override
  void dispose() {
    _heroTitleController.dispose();
    _heroSubtitleController.dispose();
    _aboutTextController.dispose();
    _whatsappController.dispose();
    _contactEmailController.dispose();
    super.dispose();
  }

  Future<void> _loadContent() async {
    final doc = await FirebaseFirestore.instance
        .collection('website_content')
        .doc('main')
        .get();
    final data = doc.data();
    if (data != null) {
      _heroTitleController.text = data['heroTitle'] ?? '';
      _heroSubtitleController.text = data['heroSubtitle'] ?? '';
      _aboutTextController.text = data['aboutText'] ?? '';
      _whatsappController.text = data['whatsappNumber'] ?? '';
      _contactEmailController.text = data['contactEmail'] ?? '';
    }
    if (mounted) setState(() => _loadingContent = false);
  }

  Future<void> _saveContent() async {
    setState(() => _savingContent = true);
    try {
      await FirebaseFirestore.instance
          .collection('website_content')
          .doc('main')
          .set({
            'heroTitle': _heroTitleController.text.trim(),
            'heroSubtitle': _heroSubtitleController.text.trim(),
            'aboutText': _aboutTextController.text.trim(),
            'whatsappNumber': _whatsappController.text.trim(),
            'contactEmail': _contactEmailController.text.trim(),
          }, SetOptions(merge: true));
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Website content saved.')));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Failed to save: $e')));
      }
    } finally {
      if (mounted) setState(() => _savingContent = false);
    }
  }

  Future<void> _addGalleryPhoto() async {
    try {
      final picker = ImagePicker();
      final pickedFile = await picker.pickImage(
        source: ImageSource.gallery,
        maxWidth: 1200,
        imageQuality: 70,
      );
      if (pickedFile == null) return;

      final bytes = await pickedFile.readAsBytes();
      final base64String = base64Encode(bytes);

      // Firestore document limit is 1MB; keep a safety margin
      if (base64String.length > 700000) {
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Image too large. Please choose a smaller photo.'),
            ),
          );
        }
        return;
      }

      final existing = await FirebaseFirestore.instance
          .collection('website_gallery')
          .get();
      int maxOrder = -1;
      for (final doc in existing.docs) {
        final order = (doc.data()['order'] as num?)?.toInt() ?? -1;
        if (order > maxOrder) maxOrder = order;
      }

      await FirebaseFirestore.instance.collection('website_gallery').add({
        'imageBase64': base64String,
        'caption': '',
        'order': maxOrder + 1,
        'createdAt': FieldValue.serverTimestamp(),
      });

      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(const SnackBar(content: Text('Photo added.')));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('Error adding photo: $e')));
      }
    }
  }

  Future<void> _editGalleryCaption(String docId, String currentCaption) async {
    final controller = TextEditingController(text: currentCaption);
    final result = await showDialog<String>(
      context: context,
      builder: (dialogContext) => AlertDialog(
        title: const Text('Edit Caption'),
        content: TextField(
          controller: controller,
          decoration: const InputDecoration(labelText: 'Caption'),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(dialogContext),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () =>
                Navigator.pop(dialogContext, controller.text.trim()),
            child: const Text('Save'),
          ),
        ],
      ),
    );
    if (result != null) {
      await FirebaseFirestore.instance
          .collection('website_gallery')
          .doc(docId)
          .update({'caption': result});
    }
  }

  Future<void> _deleteGalleryPhoto(String docId) async {
    await FirebaseFirestore.instance
        .collection('website_gallery')
        .doc(docId)
        .delete();
  }

  void _showServiceDialog({String? docId, Map<String, dynamic>? existingData}) {
    final titleController = TextEditingController(
      text: existingData?['title'] ?? '',
    );
    final descController = TextEditingController(
      text: existingData?['description'] ?? '',
    );
    String selectedIcon =
        (existingData?['iconName'] as String?) ??
        kWebsiteServiceIcons.keys.first;

    showDialog(
      context: context,
      builder: (dialogContext) => StatefulBuilder(
        builder: (dialogContext, setDialogState) => AlertDialog(
          title: Text(docId == null ? 'Add Service' : 'Edit Service'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                TextField(
                  controller: titleController,
                  decoration: const InputDecoration(labelText: 'Title'),
                ),
                const SizedBox(height: 12),
                TextField(
                  controller: descController,
                  decoration: const InputDecoration(labelText: 'Description'),
                  maxLines: 3,
                ),
                const SizedBox(height: 12),
                DropdownButtonFormField<String>(
                  initialValue: selectedIcon,
                  decoration: const InputDecoration(labelText: 'Icon'),
                  items: kWebsiteServiceIcons.entries
                      .map(
                        (e) => DropdownMenuItem(
                          value: e.key,
                          child: Row(
                            children: [
                              Icon(e.value, size: 18),
                              const SizedBox(width: 8),
                              Text(e.key),
                            ],
                          ),
                        ),
                      )
                      .toList(),
                  onChanged: (val) =>
                      setDialogState(() => selectedIcon = val ?? selectedIcon),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('Cancel'),
            ),
            ElevatedButton(
              onPressed: () async {
                final title = titleController.text.trim();
                final description = descController.text.trim();
                if (title.isEmpty) return;

                if (docId == null) {
                  final existing = await FirebaseFirestore.instance
                      .collection('website_services')
                      .get();
                  int maxOrder = -1;
                  for (final doc in existing.docs) {
                    final order = (doc.data()['order'] as num?)?.toInt() ?? -1;
                    if (order > maxOrder) maxOrder = order;
                  }
                  await FirebaseFirestore.instance
                      .collection('website_services')
                      .add({
                        'title': title,
                        'description': description,
                        'iconName': selectedIcon,
                        'order': maxOrder + 1,
                        'createdAt': FieldValue.serverTimestamp(),
                      });
                } else {
                  await FirebaseFirestore.instance
                      .collection('website_services')
                      .doc(docId)
                      .update({
                        'title': title,
                        'description': description,
                        'iconName': selectedIcon,
                      });
                }
                if (dialogContext.mounted) Navigator.pop(dialogContext);
              },
              child: const Text('Save'),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _deleteService(String docId) async {
    await FirebaseFirestore.instance
        .collection('website_services')
        .doc(docId)
        .delete();
  }

  Widget _buildHeroAboutTab() {
    if (_loadingContent) {
      return const Center(child: CircularProgressIndicator());
    }
    return SingleChildScrollView(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          TextField(
            controller: _heroTitleController,
            decoration: InputDecoration(
              labelText: 'Hero Title',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _heroSubtitleController,
            maxLines: 2,
            decoration: InputDecoration(
              labelText: 'Hero Subtitle',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _aboutTextController,
            maxLines: 5,
            decoration: InputDecoration(
              labelText: 'About Text',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _whatsappController,
            decoration: InputDecoration(
              labelText: 'WhatsApp Number',
              hintText: 'e.g. 94XXXXXXXXX',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 16),
          TextField(
            controller: _contactEmailController,
            keyboardType: TextInputType.emailAddress,
            // Shown on the public Account Deletion page (see
            // AccountDeletionScreen) — Google Play's Data Safety review
            // actually uses this address, so keep it a real, monitored one.
            decoration: InputDecoration(
              labelText: 'Contact Email',
              hintText: 'e.g. support@nodacivimech.com',
              border: OutlineInputBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
          ),
          const SizedBox(height: 20),
          SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton(
              onPressed: _savingContent ? null : _saveContent,
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
              child: Text(
                _savingContent ? 'Saving...' : 'SAVE CHANGES',
                style: const TextStyle(color: Colors.white),
              ),
            ),
          ),
        ],
      ),
    );
  }

  Widget _buildGalleryTab() {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(16),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: _addGalleryPhoto,
              icon: const Icon(Icons.add_a_photo, color: Colors.white),
              label: const Text(
                'ADD PHOTO',
                style: TextStyle(color: Colors.white),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('website_gallery')
                .orderBy('order')
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Center(child: CircularProgressIndicator());
              }
              final docs = snapshot.data?.docs ?? [];
              if (docs.isEmpty) {
                return const Center(child: Text('No photos added yet.'));
              }
              return GridView.builder(
                padding: const EdgeInsets.all(16),
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                  crossAxisCount: 3,
                  crossAxisSpacing: 12,
                  mainAxisSpacing: 12,
                  childAspectRatio: 0.85,
                ),
                itemCount: docs.length,
                itemBuilder: (context, index) {
                  final doc = docs[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final caption = (data['caption'] ?? '').toString();
                  return Card(
                    clipBehavior: Clip.antiAlias,
                    child: Column(
                      children: [
                        Expanded(
                          child: Image.memory(
                            base64Decode(data['imageBase64']),
                            fit: BoxFit.cover,
                            width: double.infinity,
                          ),
                        ),
                        Padding(
                          padding: const EdgeInsets.symmetric(
                            horizontal: 6,
                            vertical: 4,
                          ),
                          child: Row(
                            children: [
                              Expanded(
                                child: Text(
                                  caption.isEmpty ? 'No caption' : caption,
                                  style: TextStyle(
                                    fontSize: 11,
                                    color: caption.isEmpty
                                        ? Colors.grey
                                        : Colors.black87,
                                  ),
                                  overflow: TextOverflow.ellipsis,
                                ),
                              ),
                              InkWell(
                                onTap: () =>
                                    _editGalleryCaption(doc.id, caption),
                                child: const Icon(
                                  Icons.edit,
                                  size: 16,
                                  color: Colors.indigo,
                                ),
                              ),
                              const SizedBox(width: 6),
                              InkWell(
                                onTap: () => confirmDelete(
                                  context: context,
                                  title: 'Delete Photo?',
                                  message:
                                      'Are you sure you want to delete this photo? This cannot be undone.',
                                  onConfirm: () => _deleteGalleryPhoto(doc.id),
                                ),
                                child: const Icon(
                                  Icons.delete,
                                  size: 16,
                                  color: Colors.red,
                                ),
                              ),
                            ],
                          ),
                        ),
                      ],
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  Widget _buildServicesTab() {
    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.all(16),
          child: SizedBox(
            width: double.infinity,
            height: 48,
            child: ElevatedButton.icon(
              onPressed: () => _showServiceDialog(),
              icon: const Icon(Icons.add, color: Colors.white),
              label: const Text(
                'ADD SERVICE',
                style: TextStyle(color: Colors.white),
              ),
              style: ElevatedButton.styleFrom(
                backgroundColor: Colors.indigo[800],
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(12),
                ),
              ),
            ),
          ),
        ),
        Expanded(
          child: StreamBuilder<QuerySnapshot>(
            stream: FirebaseFirestore.instance
                .collection('website_services')
                .orderBy('order')
                .snapshots(),
            builder: (context, snapshot) {
              if (snapshot.connectionState == ConnectionState.waiting) {
                return const Center(child: CircularProgressIndicator());
              }
              final docs = snapshot.data?.docs ?? [];
              if (docs.isEmpty) {
                return const Center(child: Text('No services added yet.'));
              }
              return ListView.builder(
                padding: const EdgeInsets.all(12),
                itemCount: docs.length,
                itemBuilder: (context, index) {
                  final doc = docs[index];
                  final data = doc.data() as Map<String, dynamic>;
                  final iconName = (data['iconName'] ?? '').toString();
                  final icon = kWebsiteServiceIcons[iconName] ?? Icons.build;
                  return Card(
                    margin: const EdgeInsets.only(bottom: 10),
                    child: ListTile(
                      leading: CircleAvatar(
                        backgroundColor: Colors.indigo.withOpacity(0.15),
                        child: Icon(icon, color: Colors.indigo),
                      ),
                      title: Text(data['title'] ?? ''),
                      subtitle: Text(data['description'] ?? ''),
                      trailing: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          IconButton(
                            icon: const Icon(Icons.edit, color: Colors.indigo),
                            onPressed: () => _showServiceDialog(
                              docId: doc.id,
                              existingData: data,
                            ),
                          ),
                          IconButton(
                            icon: const Icon(Icons.delete, color: Colors.red),
                            onPressed: () => confirmDelete(
                              context: context,
                              title: 'Delete Service?',
                              message:
                                  'Are you sure you want to delete this service? This cannot be undone.',
                              onConfirm: () => _deleteService(doc.id),
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              );
            },
          ),
        ),
      ],
    );
  }

  @override
  Widget build(BuildContext context) {
    return DefaultTabController(
      length: 3,
      child: Scaffold(
        appBar: AppBar(
          title: const Text('Website Content'),
          backgroundColor: Colors.indigo[800],
          bottom: const TabBar(
            tabs: [
              Tab(text: 'Hero & About'),
              Tab(text: 'Gallery'),
              Tab(text: 'Services'),
            ],
          ),
        ),
        body: TabBarView(
          children: [
            _buildHeroAboutTab(),
            _buildGalleryTab(),
            _buildServicesTab(),
          ],
        ),
      ),
    );
  }
}

// ---------------- TRUCK PROFILE SCREEN (Admin/Owner) ----------------
class TruckProfileScreen extends StatelessWidget {
  final String truckId;
  final String truckNumber;

  const TruckProfileScreen({
    super.key,
    required this.truckId,
    required this.truckNumber,
  });

  void _showChangeDriverDialog(BuildContext context, String? currentDriverUid) {
    // Ephemeral to this dialog invocation only — same pattern as
    // _showEditSiteNameDialog's nameController, no explicit dispose needed.
    final manualNameController = TextEditingController();
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Change Assigned Driver'),
        content: SizedBox(
          width: double.maxFinite,
          child: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                StreamBuilder<QuerySnapshot>(
                  stream: FirebaseFirestore.instance
                      .collection('users')
                      .where('canDriveTruck', isEqualTo: true)
                      .snapshots(),
                  builder: (context, snapshot) {
                    if (!snapshot.hasData) {
                      return const Padding(
                        padding: EdgeInsets.symmetric(vertical: 20),
                        child: Center(child: CircularProgressIndicator()),
                      );
                    }
                    final drivers = snapshot.data!.docs;
                    if (drivers.isEmpty) {
                      return const Padding(
                        padding: EdgeInsets.symmetric(vertical: 20),
                        child: Text('No drivers available.'),
                      );
                    }
                    return SizedBox(
                      height: 300,
                      child: ListView.builder(
                        shrinkWrap: true,
                        itemCount: drivers.length,
                        itemBuilder: (context, index) {
                          final data =
                              drivers[index].data() as Map<String, dynamic>;
                          final uid = drivers[index].id;
                          final isSelected = uid == currentDriverUid;
                          return ListTile(
                            leading: CircleAvatar(
                              backgroundColor: Colors.deepOrange.withOpacity(
                                0.15,
                              ),
                              child: const Icon(
                                Icons.person,
                                color: Colors.deepOrange,
                              ),
                            ),
                            title: Text(data['name'] ?? ''),
                            trailing: isSelected
                                ? const Icon(
                                    Icons.check,
                                    color: Colors.deepOrange,
                                  )
                                : null,
                            onTap: () async {
                              await FirebaseFirestore.instance
                                  .collection('trucks')
                                  .doc(truckId)
                                  .update({
                                    'assignedDriverUid': uid,
                                    'assignedDriverName': data['name'] ?? '',
                                  });
                              if (context.mounted) Navigator.pop(context);
                            },
                          );
                        },
                      ),
                    );
                  },
                ),
                const Padding(
                  padding: EdgeInsets.symmetric(vertical: 12),
                  child: Row(
                    children: [
                      Expanded(child: Divider()),
                      Padding(
                        padding: EdgeInsets.symmetric(horizontal: 8),
                        child: Text(
                          'OR',
                          style: TextStyle(
                            fontWeight: FontWeight.bold,
                            color: Colors.grey,
                          ),
                        ),
                      ),
                      Expanded(child: Divider()),
                    ],
                  ),
                ),
                const Text(
                  'Type a name manually',
                  style: TextStyle(fontWeight: FontWeight.bold, fontSize: 13),
                ),
                const SizedBox(height: 4),
                const Text(
                  'For a driver who isn\'t registered in the app (e.g. a '
                  'substitute or contract driver).',
                  style: TextStyle(fontSize: 12, color: Colors.grey),
                ),
                const SizedBox(height: 8),
                TextField(
                  controller: manualNameController,
                  decoration: const InputDecoration(
                    hintText: 'Driver name',
                    border: OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.deepOrange[800],
                    ),
                    onPressed: () async {
                      final typedName = manualNameController.text.trim();
                      if (typedName.isEmpty) return;
                      // Not a registered user — no canDriveTruck account —
                      // so assignedDriverUid stays null. Auto-fill in the
                      // Loading dialog reads assignedDriverName either way,
                      // so this works there with no further changes.
                      await FirebaseFirestore.instance
                          .collection('trucks')
                          .doc(truckId)
                          .update({
                            'assignedDriverUid': null,
                            'assignedDriverName': typedName,
                          });
                      if (context.mounted) Navigator.pop(context);
                    },
                    child: const Text(
                      'Assign This Name',
                      style: TextStyle(color: Colors.white),
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
        ],
      ),
    );
  }

  // GPS Live Tracking (Phase 1, web-only — see LiveTrackingScreen): the
  // gpsDeviceId manually entered here is matched against each Traccar
  // position's deviceId to place this truck's marker on the map. It's
  // typed in by hand (copied from the Traccar Devices list's Identifier
  // column) rather than looked up live, since this app has no Traccar
  // device-provisioning integration — Traccar is the source of truth for
  // which identifiers exist.
  void _showSetGpsDeviceDialog(BuildContext context, String? currentDeviceId) {
    final deviceIdController = TextEditingController(
      text: currentDeviceId ?? '',
    );
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Assigned GPS Device'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            const Text(
              'Enter this truck\'s Traccar Device Identifier (copy it from '
              'the Traccar Devices list).',
              style: TextStyle(fontSize: 13, color: Colors.black54),
            ),
            const SizedBox(height: 12),
            TextField(
              controller: deviceIdController,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: 'GPS Device Identifier',
                hintText: 'e.g. 9210188280',
                border: OutlineInputBorder(),
              ),
            ),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final typedId = deviceIdController.text.trim();
              await FirebaseFirestore.instance
                  .collection('trucks')
                  .doc(truckId)
                  .update({'gpsDeviceId': typedId.isEmpty ? null : typedId});
              if (context.mounted) Navigator.pop(context);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  // Cube Capacity (trucks/{id}.cubeCapacity) — shown read-only on Vehicle
  // Registration's QR Generate tab so a supervisor scanning the QR knows
  // this truck's max load without asking, and used by QR Scan's submitted
  // work_records.cubeCount.
  void _showSetCubeCapacityDialog(BuildContext context, double? currentValue) {
    final capacityController = TextEditingController(
      text: currentValue?.toString() ?? '',
    );
    showDialog(
      context: context,
      builder: (_) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: const Text('Cube Capacity'),
        content: TextField(
          controller: capacityController,
          autofocus: true,
          keyboardType: const TextInputType.numberWithOptions(decimal: true),
          decoration: const InputDecoration(
            labelText: 'Cube Capacity',
            border: OutlineInputBorder(),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('Cancel'),
          ),
          ElevatedButton(
            onPressed: () async {
              final typedValue = double.tryParse(
                capacityController.text.trim(),
              );
              await FirebaseFirestore.instance
                  .collection('trucks')
                  .doc(truckId)
                  .update({'cubeCapacity': typedValue});
              if (context.mounted) Navigator.pop(context);
            },
            child: const Text('Save'),
          ),
        ],
      ),
    );
  }

  String _formatTime(Timestamp? ts) {
    if (ts == null) return '-';
    final dt = ts.toDate();
    final hour = dt.hour % 12 == 0 ? 12 : dt.hour % 12;
    final period = dt.hour >= 12 ? 'PM' : 'AM';
    final minute = dt.minute.toString().padLeft(2, '0');
    return '$hour:$minute $period';
  }

  String _formatDateHeader(String dateString) {
    final parts = dateString.split('-');
    if (parts.length != 3) return dateString;
    final date = DateTime(
      int.parse(parts[0]),
      int.parse(parts[1]),
      int.parse(parts[2]),
    );
    final today = DateTime.now();
    final todayStr =
        "${today.year}-${today.month.toString().padLeft(2, '0')}-${today.day.toString().padLeft(2, '0')}";
    if (dateString == todayStr) return 'Today';
    final yesterday = today.subtract(const Duration(days: 1));
    final yestStr =
        "${yesterday.year}-${yesterday.month.toString().padLeft(2, '0')}-${yesterday.day.toString().padLeft(2, '0')}";
    if (dateString == yestStr) return 'Yesterday';
    const months = [
      'Jan',
      'Feb',
      'Mar',
      'Apr',
      'May',
      'Jun',
      'Jul',
      'Aug',
      'Sep',
      'Oct',
      'Nov',
      'Dec',
    ];
    return '${date.day} ${months[date.month - 1]} ${date.year}';
  }

  static const List<Color> _dayColors = [
    Color(0xFF3D9DE0),
    Color(0xFF4CAF7D),
    Color(0xFFE0A93D),
    Color(0xFF9B6BE0),
    Color(0xFFE05C97),
    Color(0xFF3DBFC4),
    Color(0xFFEF6C57),
    Color(0xFF7D8CE0),
  ];

