                                                          decoration: BoxDecoration(
                                                            color: isActive
                                                                ? Colors.green
                                                                : Colors.grey,
                                                            borderRadius:
                                                                BorderRadius.circular(
                                                                  20,
                                                                ),
                                                          ),
                                                          child: Text(
                                                            isActive
                                                                ? 'ACTIVE'
                                                                : 'DONE',
                                                            style:
                                                                const TextStyle(
                                                                  color: Colors
                                                                      .white,
                                                                  fontSize: 10,
                                                                ),
                                                          ),
                                                        ),
                                                      ],
                                                    ),
                                                    const SizedBox(height: 4),
                                                    Text(
                                                      'Started: ${_formatTime(data['createdAt'] as Timestamp?)}'
                                                      '${data['completedAt'] != null ? "  •  Ended: ${_formatTime(data['completedAt'] as Timestamp?)}" : ""}',
                                                      style: TextStyle(
                                                        color: Colors.white
                                                            .withOpacity(0.6),
                                                        fontSize: 11,
                                                      ),
                                                    ),
                                                    const SizedBox(height: 8),
                                                    StreamBuilder<
                                                      QuerySnapshot
                                                    >(
                                                      stream: FirebaseFirestore
                                                          .instance
                                                          .collection(
                                                            'truck_sessions',
                                                          )
                                                          .doc(doc.id)
                                                          .collection('trips')
                                                          .snapshots(),
                                                      builder: (context, tripSnap) {
                                                        if (!tripSnap.hasData) {
                                                          return const SizedBox.shrink();
                                                        }
                                                        final tripCount =
                                                            tripSnap
                                                                .data!
                                                                .docs
                                                                .length;
                                                        return Row(
                                                          children: [
                                                            Icon(
                                                              Icons.route,
                                                              size: 14,
                                                              color: Colors
                                                                  .white
                                                                  .withOpacity(
                                                                    0.7,
                                                                  ),
                                                            ),
                                                            const SizedBox(
                                                              width: 4,
                                                            ),
                                                            Text(
                                                              '$tripCount trip(s)',
                                                              style: TextStyle(
                                                                color: Colors
                                                                    .white
                                                                    .withOpacity(
                                                                      0.8,
                                                                    ),
                                                                fontSize: 12,
                                                              ),
                                                            ),
                                                          ],
                                                        );
                                                      },
                                                    ),
                                                  ],
                                                ),
                                              ),
                                            );
                                          }),
                                        ],
                                      ),
                                    );
                                  }),
                                );
                              },
                            ),
                        ],
                      ),
                    );
                  },
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

